src/lib.rs
```
pub mod graph {
    //! An internal Domain Specific Language, modelled after the Graphviz DOT language.
    //!
    //! Each DOT statement has a builder-style equivalent:
    //!
    //! - `graph [bgcolor="yellow"]` becomes `Graph::new().with_attrs(&[("bgcolor", "yellow")])`
    //! - `a [color="red"]` becomes `Node::new("a").with_attrs(&[("color", "red")])`
    //! - `a -- b [color="green"]` becomes `Edge::new("a", "b").with_attrs(&[("color", "green")])`

    use std::collections::BTreeMap;

    /// Attributes are key/value pairs such as `color = "red"`.
    /// A `BTreeMap` keeps them sorted, so equality and iteration ignore insertion order.
    pub type Attributes = BTreeMap<String, String>;

    fn to_attributes(pairs: &[(&str, &str)]) -> Attributes {
        pairs
            .iter()
            .map(|&(key, value)| (key.to_string(), value.to_string()))
            .collect()
    }

    /// A node of a graph, identified by its name.
    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct Node {
        name: String,
        attrs: Attributes,
    }

    impl Node {
        /// Creates a node without attributes, like `a` in DOT.
        pub fn new(name: &str) -> Self {
            Node {
                name: name.to_string(),
                attrs: Attributes::new(),
            }
        }

        /// Sets attributes on the node. Keys that are already set are overwritten.
        pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
            self.attrs.extend(to_attributes(attrs));
            self
        }

        /// Returns the name of the node.
        pub fn name(&self) -> &str {
            &self.name
        }

        /// Returns the value of an attribute, if it is set.
        pub fn attr(&self, key: &str) -> Option<&str> {
            self.attrs.get(key).map(String::as_str)
        }
    }

    /// A connection from one node to another, like `a -- b` in DOT.
    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct Edge {
        source: String,
        target: String,
        attrs: Attributes,
    }

    impl Edge {
        /// Creates an edge without attributes, from `source` to `target`.
        pub fn new(source: &str, target: &str) -> Self {
            Edge {
                source: source.to_string(),
                target: target.to_string(),
                attrs: Attributes::new(),
            }
        }

        /// Sets attributes on the edge. Keys that are already set are overwritten.
        pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
            self.attrs.extend(to_attributes(attrs));
            self
        }

        /// Returns the name of the node the edge starts at.
        pub fn source(&self) -> &str {
            &self.source
        }

        /// Returns the name of the node the edge ends at.
        pub fn target(&self) -> &str {
            &self.target
        }

        /// Returns the value of an attribute, if it is set.
        pub fn attr(&self, key: &str) -> Option<&str> {
            self.attrs.get(key).map(String::as_str)
        }
    }

    /// A graph made of graph-level attributes, nodes and edges.
    #[derive(Debug, Clone, Default, PartialEq, Eq)]
    pub struct Graph {
        attrs: Attributes,
        nodes: BTreeMap<String, Node>,
        edges: Vec<Edge>,
    }

    impl Graph {
        /// Creates an empty graph. Describe it by chaining the `with_*` methods.
        pub fn new() -> Self {
            Self::default()
        }

        /// Sets graph-level attributes, like `graph [bgcolor="yellow"]` in DOT.
        pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
            self.attrs.extend(to_attributes(attrs));
            self
        }

        /// Adds nodes. Declaring a node that already exists merges the new attributes into it,
        /// just like repeating a node statement in DOT.
        pub fn with_nodes(mut self, nodes: &[Node]) -> Self {
            for node in nodes {
                self.declare_node(node);
            }
            self
        }

        /// Adds edges. Endpoints that are not yet nodes are created implicitly, as in DOT.
        pub fn with_edges(mut self, edges: &[Edge]) -> Self {
            for edge in edges {
                self.ensure_node(edge.source());
                self.ensure_node(edge.target());
                self.edges.push(edge.clone());
            }
            self
        }

        /// Returns the node with the given name, if it is part of the graph.
        pub fn node(&self, name: &str) -> Option<&Node> {
            self.nodes.get(name)
        }

        /// Iterates over all nodes, ordered by name.
        pub fn nodes(&self) -> impl Iterator<Item = &Node> {
            self.nodes.values()
        }

        /// Returns all edges, in the order they were added.
        pub fn edges(&self) -> &[Edge] {
            &self.edges
        }

        /// Returns the value of a graph-level attribute, if it is set.
        pub fn attr(&self, key: &str) -> Option<&str> {
            self.attrs.get(key).map(String::as_str)
        }

        fn declare_node(&mut self, node: &Node) {
            self.nodes
                .entry(node.name.clone())
                .and_modify(|existing| existing.attrs.extend(node.attrs.clone()))
                .or_insert_with(|| node.clone());
        }

        fn ensure_node(&mut self, name: &str) {
            self.nodes
                .entry(name.to_string())
                .or_insert_with(|| Node::new(name));
        }
    }
}
```

The task is to implement an internal DSL for building graphs in Rust, using the builder pattern. The existing `Graph::new()` must be kept. I'll add a `Graph` struct holding nodes and edges with attributes, plus a builder-style API (`graph`, `node`, `edge`, `attr`) that the existing `new()` constructor still supports.

Design:
- `Graph` stores attributes, nodes (name + attributes), and edges (from, to, attributes).
- `Graph::new()` still returns an empty graph.
- Builder methods take `self` and return `Self`, so they chain: `Graph::new().node("a").edge("a", "b")`.
- Attributes are added with `attr` on the graph, and `with_attr` on nodes/edges via a small `Node` / `Edge` builder.

