use std::fmt;

/// Errors that can occur when constructing a [`Scale`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Error {
    /// The tonic is not a valid note name such as `C`, `F#`, or `bb`.
    InvalidTonic(String),
    /// An interval character is not one of `m`, `M`, or `A`.
    InvalidInterval(char),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::InvalidTonic(tonic) => write!(f, "invalid tonic: {tonic:?}"),
            Error::InvalidInterval(c) => write!(f, "invalid interval: {c:?}"),
        }
    }
}

impl std::error::Error for Error {}

/// A musical scale: the tonic followed by one note for each interval in the pattern.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Scale {
    notes: Vec<String>,
}

const SHARP_NAMES: [&str; 12] = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];
const FLAT_NAMES: [&str; 12] = ["C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B"];

/// Converts a tonic such as `C`, `f#`, or `bb` into a pitch class
/// (0 = C, 1 = C#, ..., 11 = B).
fn pitch_class(tonic: &str) -> Result<usize, Error> {
    let invalid = || Error::InvalidTonic(tonic.to_string());
    let mut chars = tonic.chars();

    let natural: i32 = match chars.next().map(|c| c.to_ascii_uppercase()) {
        Some('C') => 0,
        Some('D') => 2,
        Some('E') => 4,
        Some('F') => 5,
        Some('G') => 7,
        Some('A') => 9,
        Some('B') => 11,
        _ => return Err(invalid()),
    };

    let accidental: i32 = match chars.next() {
        None => 0,
        Some('#') => 1,
        Some('b') => -1,
        Some(_) => return Err(invalid()),
    };

    if chars.next().is_some() {
        return Err(invalid());
    }

    Ok((natural + accidental).rem_euclid(12) as usize)
}

/// Decides whether a tonic is spelled with flats, following the conventional
/// key signatures. Uppercase tonics are major, lowercase tonics are minor.
fn uses_flats(tonic: &str) -> bool {
    let is_minor = tonic.starts_with(|c: char| c.is_ascii_lowercase());
    let key = tonic.to_ascii_lowercase();

    if is_minor {
        matches!(key.as_str(), "d" | "g" | "c" | "f" | "bb" | "eb")
    } else {
        matches!(key.as_str(), "f" | "bb" | "eb" | "ab" | "db" | "gb")
    }
}

/// Number of half steps spanned by an interval symbol.
fn semitones(interval: char) -> Result<usize, Error> {
    match interval {
        'm' => Ok(1), // minor second (half step)
        'M' => Ok(2), // major second (whole step)
        'A' => Ok(3), // augmented second (whole step + half step)
        other => Err(Error::InvalidInterval(other)),
    }
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let root = pitch_class(tonic)?;
        let names: &[&str] = if uses_flats(tonic) {
            &FLAT_NAMES
        } else {
            &SHARP_NAMES
        };

        let mut notes = Vec::with_capacity(intervals.len() + 1);
        let mut current = root;
        notes.push(names[current].to_string());

        for interval in intervals.chars() {
            current = (current + semitones(interval)?) % 12;
            notes.push(names[current].to_string());
        }

        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        // Eleven half steps visit all twelve pitches before returning to the tonic.
        Scale::new(tonic, &"m".repeat(11))
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
