];

const FLAT_TONICS: [&str; 12] = [
    "F", "Bb", "Eb", "Ab", "Db", "Gb", "d", "g", "c", "f", "bb", "eb",
];

/// Normalize a tonic into the canonical note name used in the scale tables
/// (e.g. "c#" -> "C#", "bb" -> "Bb"). Returns `None` for invalid input.
fn normalize_tonic(tonic: &str) -> Option<String> {
    let mut chars = tonic.chars();
    let first = chars.next()?;
    if !first.is_ascii_alphabetic() {
        return None;
    }
    let letter = first.to_ascii_uppercase();
    if !matches!(letter, 'A'..='G') {
        return None;
    }
    let rest: String = chars.collect();
    match rest.as_str() {
        "" => Some(letter.to_string()),
        "#" => Some(format!("{letter}#")),
        "b" => Some(format!("{letter}b")),
        _ => None,
    }
}

/// Index into the chromatic table for a canonical note name.
fn note_index(note: &str) -> Option<usize> {
    SHARP_NOTES
        .iter()
        .position(|n| *n == note)
        .or_else(|| FLAT_NOTES.iter().position(|n| *n == note))
}

/// Decide whether the chromatic scale for this tonic should use flats.
fn uses_flats(tonic: &str) -> bool {
    FLAT_TONICS.iter().any(|t| *t == tonic)
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let canonical = normalize_tonic(tonic).ok_or(Error)?;
        let table = if uses_flats(tonic) {
            &FLAT_NOTES
        } else {
            &SHARP_NOTES
        };
        let start = note_index(&canonical).ok_or(Error)?;

        let mut notes = Vec::new();
        let mut idx = start;
        notes.push(table[idx].to_string());

        for ch in intervals.chars() {
            let steps = match ch {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                _ => return Err(Error),
            };
            idx = (idx + steps) % 12;
            notes.push(table[idx].to_string());
        }

        // The final interval returns to the tonic; drop that duplicate note.
        if notes.len() > 1 && idx == start {
            notes.pop();
        }

        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        let canonical = normalize_tonic(tonic).ok_or(Error)?;
        let table = if uses_flats(tonic) {
            &FLAT_NOTES
        } else {
            &SHARP_NOTES
        };
        let start = note_index(&canonical).ok_or(Error)?;

        let notes = (0..12)
            .map(|i| table[(start + i) % 12].to_string())
            .collect();

        Ok(Scale { notes })
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
