// Errors that can occur when constructing a scale.
#[derive(Debug, PartialEq, Eq)]
pub enum Error {
    InvalidTonic(String),
    InvalidInterval(char),
}

const SHARP_NAMES: [&str; 12] = [
    "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B",
];
const FLAT_NAMES: [&str; 12] = [
    "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B",
];

pub struct Scale {
    // Pitch classes, 0 = C, 1 = C#/Db, ..., 11 = B
    pitches: Vec<usize>,
    use_flats: bool,
}

// Parses a tonic such as "C", "F#", "Bb", "bb" or "g" into a pitch class
// (0-11) and whether flats should be used when naming the notes.
fn parse_tonic(tonic: &str) -> Result<(usize, bool), Error> {
    let invalid = || Error::InvalidTonic(tonic.to_string());
    let mut chars = tonic.chars();

    let letter = chars.next().ok_or_else(invalid)?;
    let base: i32 = match letter.to_ascii_uppercase() {
        'C' => 0,
        'D' => 2,
        'E' => 4,
        'F' => 5,
        'G' => 7,
        'A' => 9,
        'B' => 11,
        _ => return Err(invalid()),
    };

    let accidental = match chars.next() {
        None => None,
        Some('#') => Some('#'),
        Some('b') => Some('b'),
        Some(_) => return Err(invalid()),
    };

    if chars.next().is_some() {
        return Err(invalid());
    }

    let offset = match accidental {
        Some('#') => 1,
        Some('b') => -1,
        _ => 0,
    };
    let pitch = (base + offset).rem_euclid(12) as usize;

    let use_flats = match accidental {
        Some('b') => true,
        Some('#') => false,
        // Uppercase naturals (major keys): only F uses flats.
        _ if letter.is_ascii_uppercase() => letter == 'F',
        // Lowercase naturals (minor keys): c, d, f, g use flats; a, b, e use sharps.
        _ => matches!(letter, 'c' | 'd' | 'f' | 'g'),
    };

    Ok((pitch, use_flats))
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let (start, use_flats) = parse_tonic(tonic)?;

        let mut pitches = Vec::with_capacity(intervals.len());
        let mut current = start;

        for c in intervals.chars() {
            let step = match c {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                other => return Err(Error::InvalidInterval(other)),
            };
            pitches.push(current);
            current = (current + step) % 12;
        }

        Ok(Scale { pitches, use_flats })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        let (start, use_flats) = parse_tonic(tonic)?;
        let pitches = (0..12).map(|i| (start + i) % 12).collect();
        Ok(Scale { pitches, use_flats })
    }

    pub fn enumerate(&self) -> Vec<String> {
        let names = if self.use_flats {
            &FLAT_NAMES
        } else {
            &SHARP_NAMES
        };
        self.pitches
            .iter()
            .map(|&p| names[p].to_string())
            .collect()
    }
}
