];

fn normalize_tonic(tonic: &str) -> String {
    let mut chars = tonic.chars();
    match chars.next() {
        Some(first) => {
            let rest: String = chars.collect();
            format!("{}{}", first.to_ascii_uppercase(), rest)
        }
        None => String::new(),
    }
}

fn uses_flats(tonic: &str) -> bool {
    FLAT_TONICS.contains(&tonic)
        || FLAT_TONICS
            .iter()
            .any(|t| t.eq_ignore_ascii_case(tonic) && tonic.chars().next().map_or(false, |c| c.is_lowercase()) == t.chars().next().map_or(false, |c| c.is_lowercase()))
}

fn note_index(name: &str, names: &[&str; 12]) -> Option<usize> {
    names.iter().position(|n| *n == name)
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let tonic_norm = normalize_tonic(tonic);
        let flats = uses_flats(tonic);
        let names = if flats { &FLAT_NOTES } else { &SHARP_NOTES };

        // Lowercase minor tonics are written in the input as e.g. "d", "g#", "bb".
        // Map to the canonical chromatic name by matching case-insensitively.
        let start_name = {
            let mut candidate = None;
            for name in names.iter() {
                if name.eq_ignore_ascii_case(tonic) {
                    candidate = Some(*name);
                    break;
                }
            }
            match candidate {
                Some(c) => c,
                None => {
                    // Fall back to the normalized spelling.
                    let mut found = None;
                    for name in names.iter() {
                        if name.eq_ignore_ascii_case(&tonic_norm) {
                            found = Some(*name);
                            break;
                        }
                    }
                    found.ok_or(Error)?
                }
            }
        };

        let mut idx = note_index(start_name, names).ok_or(Error)?;
        let mut notes = vec![names[idx].to_string()];

        for c in intervals.chars() {
            let step = match c {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                _ => return Err(Error),
            };
            idx = (idx + step) % 12;
            notes.push(names[idx].to_string());
        }

        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, "mmmmmmmmmmm")
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
