//
// Implementations of promisify, all, allSettled, race and any
// without using the built-in Promise combinator methods.
//

// Wraps a value (promise or plain value) into a promise.
const toPromise = (value) => new Promise((resolve) => resolve(value));

export const promisify = (fn) => {
  return (...args) =>
    new Promise((resolve, reject) => {
      fn(...args, (error, data) => {
        if (error) {
          reject(error);
        } else {
          resolve(data);
        }
      });
    });
};

export const all = (promises) => {
  return new Promise((resolve, reject) => {
    const items = Array.from(promises);
    const results = new Array(items.length);
    let remaining = items.length;

    if (remaining === 0) {
      resolve(results);
      return;
    }

    items.forEach((item, index) => {
      toPromise(item).then((value) => {
        results[index] = value;
        remaining -= 1;
        if (remaining === 0) {
          resolve(results);
        }
      }, reject);
    });
  });
};

export const allSettled = (promises) => {
  return new Promise((resolve) => {
    const items = Array.from(promises);
    const results = new Array(items.length);
    let remaining = items.length;

    if (remaining === 0) {
      resolve(results);
      return;
    }

    const settle = (index, result) => {
      results[index] = result;
      remaining -= 1;
      if (remaining === 0) {
        resolve(results);
      }
    };

    items.forEach((item, index) => {
      toPromise(item).then(
        (value) => settle(index, { status: 'fulfilled', value }),
        (reason) => settle(index, { status: 'rejected', reason })
      );
    });
  });
};

export const race = (promises) => {
  return new Promise((resolve, reject) => {
    Array.from(promises).forEach((item) => {
      toPromise(item).then(resolve, reject);
    });
  });
};

export const any = (promises) => {
  return new Promise((resolve, reject) => {
    const items = Array.from(promises);
    const errors = new Array(items.length);
    let remaining = items.length;

    const fail = (index, reason) => {
      errors[index] = reason;
      remaining -= 1;
      if (remaining === 0) {
        reject(new AggregateError(errors, 'All promises were rejected'));
      }
    };

    if (remaining === 0) {
      reject(new AggregateError(errors, 'All promises were rejected'));
      return;
    }

    items.forEach((item, index) => {
      toPromise(item).then(resolve, (reason) => fail(index, reason));
    });
  });
};
