import operator


OPERATIONS = {
    "plus": operator.add,
    "minus": operator.sub,
    "multiplied by": operator.mul,
    "divided by": None,  # handled specially to use integer division
}

BINARY_OPS = {
    "plus": lambda a, b: a + b,
    "minus": lambda a, b: a - b,
    "multiplied by": lambda a, b: a * b,
    "divided by": lambda a, b: int(a / b),
}


def _parse_int(token):
    try:
        return int(token)
    except ValueError:
        return None


def answer(question):
    if not isinstance(question, str):
        raise ValueError("syntax error")

    text = question.strip()
    if not text.startswith("What is") or not text.endswith("?"):
        raise ValueError("unknown operation")

    body = text[len("What is"):-1].strip()
    if body == "":
        raise ValueError("syntax error")

    tokens = body.split()

    # Rebuild tokens so that two-word operations become single items.
    items = []
    i = 0
    while i < len(tokens):
        if i + 1 < len(tokens) and f"{tokens[i]} {tokens[i + 1]}" in ("multiplied by", "divided by"):
            items.append(f"{tokens[i]} {tokens[i + 1]}")
            i += 2
        else:
            items.append(tokens[i])
            i += 1

    # First item must be a number.
    result = _parse_int(items[0])
    if result is None:
        if items[0] in BINARY_OPS:
            raise ValueError("syntax error")
        raise ValueError("unknown operation")

    idx = 1
    while idx < len(items):
        op = items[idx]
        if op not in BINARY_OPS:
            value = _parse_int(op)
            if value is not None:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")

        if idx + 1 >= len(items):
            raise ValueError("syntax error")

        operand = _parse_int(items[idx + 1])
        if operand is None:
            if items[idx + 1] in BINARY_OPS:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")

        if op == "divided by" and operand == 0:
            raise ValueError("division by zero")

        result = BINARY_OPS[op](result, operand)
        idx += 2

    return result
