```
import operator
import re

PREFIX = "What is"
NUMBER_PATTERN = re.compile(r"-?\d+")


def _divide(dividend, divisor):
    """Integer division that truncates toward zero, e.g. -7 / 2 == -3."""
    if divisor == 0:
        raise ValueError("division by zero")
    quotient = abs(dividend) // abs(divisor)
    if (dividend < 0) != (divisor < 0):
        quotient = -quotient
    return quotient


# Operations written as a single word, e.g. "plus".
SINGLE_WORD_OPERATIONS = {
    "plus": operator.add,
    "minus": operator.sub,
}

# Operations written as two words, e.g. "multiplied by".
# Keyed by the first word; the second word must be "by".
TWO_WORD_OPERATIONS = {
    "multiplied": operator.mul,
    "divided": _divide,
}


def _is_number(word):
    return NUMBER_PATTERN.fullmatch(word) is not None


def _is_operation_word(word):
    return word in SINGLE_WORD_OPERATIONS or word in TWO_WORD_OPERATIONS


def _read_number(words, index):
    """Return the number at words[index] and the index after it."""
    if index >= len(words):
        raise ValueError("syntax error")  # missing operand
    word = words[index]
    if _is_number(word):
        return int(word), index + 1
    if _is_operation_word(word):
        raise ValueError("syntax error")  # operation where a number belongs
    raise ValueError("unknown operation")


def _read_operation(words, index):
    """Return the operation at words[index] and the index after it."""
    word = words[index]
    if word in SINGLE_WORD_OPERATIONS:
        return SINGLE_WORD_OPERATIONS[word], index + 1
    if word in TWO_WORD_OPERATIONS:
        if index + 1 < len(words) and words[index + 1] == "by":
            return TWO_WORD_OPERATIONS[word], index + 2
        raise ValueError("syntax error")  # e.g. "multiplied" without "by"
    if _is_number(word):
        raise ValueError("syntax error")  # two numbers in a row
    raise ValueError("unknown operation")


def answer(question):
    """Evaluate a word problem such as 'What is 3 plus 2 multiplied by 3?'."""
    text = question.strip()
    if not text.startswith(PREFIX):
        raise ValueError("unknown operation")  # not a math question

    words = text[len(PREFIX):].rstrip("?").split()

    result, index = _read_number(words, 0)
    while index < len(words):
        operation, index = _read_operation(words, index)
        operand, index = _read_number(words, index)
        result = operation(result, operand)
    return result
