import operator
import re

_PREFIX = re.compile(r"what\s+is\b", re.IGNORECASE)
_NUMBER = re.compile(r"[-+]?\d+")


def _divide(left, right):
    if right == 0:
        raise ValueError("division by zero")
    # Integer division truncating toward zero
    quotient = abs(left) // abs(right)
    return quotient if (left < 0) == (right < 0) else -quotient


OPERATIONS = {
    "plus": operator.add,
    "minus": operator.sub,
    "multiplied": operator.mul,
    "divided": _divide,
}


def _tokenize(body):
    """Convert the body of a question into numbers and operation names."""
    words = body.split()
    tokens = []
    index = 0
    while index < len(words):
        word = words[index].lower()
        if _NUMBER.fullmatch(word):
            tokens.append(int(word))
        elif word in ("plus", "minus"):
            tokens.append(word)
        elif word in ("multiplied", "divided"):
            if index + 1 >= len(words) or words[index + 1].lower() != "by":
                raise ValueError("syntax error")
            tokens.append(word)
            index += 1  # skip the "by"
        else:
            raise ValueError("unknown operation")
        index += 1
    return tokens


def _evaluate(tokens):
    """Evaluate tokens strictly left-to-right, ignoring operator precedence."""
    if not tokens or not isinstance(tokens[0], int):
        raise ValueError("syntax error")

    result = tokens[0]
    rest = tokens[1:]

    # Operations and operands must come in pairs
    if len(rest) % 2 != 0:
        raise ValueError("syntax error")

    for operation, operand in zip(rest[0::2], rest[1::2]):
        if not isinstance(operation, str) or operation not in OPERATIONS:
            raise ValueError("syntax error")
        if not isinstance(operand, int):
            raise ValueError("syntax error")
        result = OPERATIONS[operation](result, operand)

    return result


