    public int hashCode() {
        return Objects.hash(a, b, c);
    }

    @Override
    public String toString() {
        return "{" + a + ", " + b + ", " + c + "}";
    }

    static class TripletListBuilder {

        private int sum = 0;
        private int maxFactor = Integer.MAX_VALUE;

        TripletListBuilder thatSumTo(int sum) {
            this.sum = sum;
            return this;
        }

        TripletListBuilder withFactorsLessThanOrEqualTo(int maxFactor) {
            this.maxFactor = maxFactor;
            return this;
        }

        List<PythagoreanTriplet> build() {
            List<PythagoreanTriplet> triplets = new ArrayList<>();
            long limit = Math.min((long) maxFactor, (long) sum);

            // a < b < c and a + b + c = sum implies a < sum / 3
            for (int a = 1; 3L * a < sum; a++) {
                // c > b with c = sum - a - b implies a + 2b < sum
                for (int b = a + 1; a + 2L * b < sum; b++) {
                    int c = sum - a - b;
                    if (c > limit) {
                        continue;
                    }
                    if ((long) a * a + (long) b * b == (long) c * c) {
                        triplets.add(new PythagoreanTriplet(a, b, c));
                    }
                }
            }
            return triplets;
        }
    }

