// smallest. The scan stops once no remaining product can beat the best so far.
const findSmallest = (minFactor, maxFactor) => {
  let value = Infinity;
  let factors = [];

  for (let a = minFactor; a <= maxFactor; a++) {
    // Every product in this row is at least a * a.
    if (a * a > value) break;

    for (let b = a; b <= maxFactor; b++) {
      const product = a * b;
      if (product > value) break;

      if (isPalindrome(product)) {
        if (product < value) {
          value = product;
          factors = [];
        }
        factors.push([a, b]);
      }
    }
  }

  return { value: factors.length > 0 ? value : null, factors };
};

// Scans downwards from the highest factor, so the first palindrome found is the
// largest. The scan stops once no remaining product can beat the best so far.
const findLargest = (minFactor, maxFactor) => {
  let value = -Infinity;
  let factors = [];

  for (let a = maxFactor; a >= minFactor; a--) {
    // Every product in this row is at most a * maxFactor.
