        const product = a * b;
        // Products only decrease as b decreases
        if (product < value) break;

        if (isPalindrome(product)) {
          if (product > value) {
            value = product;
            factors = [];
          }
          factors.push([a, b]);
        }
      }
    }

    if (value === -Infinity) {
      return { value: null, factors: [] };
    }

    return { value, factors: sortFactors(factors) };
  }
}
