namespace queen_attack {

std::pair<int, int> parse_position(const std::string& square) {
    if (square.size() != 2) {
        throw std::invalid_argument("invalid square: " + square);
    }
    char file = square[0];
    char rank = square[1];
    if (file < 'a' || file > 'h' || rank < '1' || rank > '8') {
        throw std::invalid_argument("invalid square: " + square);
    }
    int column = file - 'a';
    int row = rank - '1';
    return {row, column};
}

bool can_attack(const std::string& white, const std::string& black) {
    auto [wr, wc] = parse_position(white);
    auto [br, bc] = parse_position(black);

    if (wr == br && wc == bc) {
        throw std::invalid_argument("queens cannot share the same square");
    }

    if (wr == br || wc == bc) {
        return true;
    }

    return std::abs(wr - br) == std::abs(wc - bc);
}

}  // namespace queen_attack
