import java.util.ArrayList;
import java.util.List;

class Dominoes {

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        List<Domino> result = new ArrayList<>();
        if (inputDominoes == null || inputDominoes.isEmpty()) {
            return result;
        }

        boolean[] used = new boolean[inputDominoes.size()];
        Domino first = inputDominoes.get(0);
        used[0] = true;
        result.add(first);

        if (search(inputDominoes, used, result, first.getRight(), first.getLeft(), 1)) {
            return result;
        }
        throw new ChainNotFoundException("No valid domino chain exists");
    }

    private boolean search(List<Domino> dominoes, boolean[] used, List<Domino> chain,
                           int currentEnd, int startValue, int placed) {
        if (placed == dominoes.size()) {
            return currentEnd == startValue;
        }

        for (int i = 0; i < dominoes.size(); i++) {
            if (used[i]) {
                continue;
            }
            Domino d = dominoes.get(i);
            Domino oriented = null;
            if (d.getLeft() == currentEnd) {
                oriented = d;
            } else if (d.getRight() == currentEnd) {
                oriented = new Domino(d.getRight(), d.getLeft());
            }
            if (oriented == null) {
                continue;
            }

            used[i] = true;
            chain.add(oriented);
            if (search(dominoes, used, chain, oriented.getRight(), startValue, placed + 1)) {
                return true;
            }
            chain.remove(chain.size() - 1);
            used[i] = false;
        }
        return false;
    }

}
