- Each stone is an edge between its two dot values. A valid chain is a closed walk that uses every stone exactly once (an Eulerian circuit), and a stone is flipped whenever it is walked from right to left.
- Such a walk exists only if every dot value occurs an even number of times (a double counts twice) and all stones are connected. Otherwise `ChainNotFoundException` is thrown.
- The walk is built with Hierholzer's algorithm, which runs in linear time. Stones are tracked by index, so duplicate stones are handled naturally.
- Empty input returns an empty list.

I haven't seen `Domino.java` or `ChainNotFoundException.java`, so this assumes a `Domino(int left, int right)` constructor, `int getLeft()` and `int getRight()` accessors, and a `ChainNotFoundException(String message)` constructor. If your versions differ, share those files and I'll adjust.

src/main/java/Dominoes.java
```
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Dominoes {

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        if (inputDominoes.isEmpty()) {
            return new ArrayList<>();
        }
        if (!everyDotAppearsEvenTimes(inputDominoes)) {
            throw new ChainNotFoundException("Dot values cannot form a closed chain");
        }
        List<Domino> chain = buildChain(inputDominoes);
        if (chain.size() != inputDominoes.size()) {
            throw new ChainNotFoundException("Dominoes are not all connected into a single chain");
        }
        return chain;
    }

    /**
     * In a closed chain every dot value must occur an even number of times. A double such
     * as [3|3] contributes two occurrences of its value.
     */
    private static boolean everyDotAppearsEvenTimes(List<Domino> dominoes) {
        Map<Integer, Integer> dotCounts = new HashMap<>();
        for (Domino domino : dominoes) {
            dotCounts.merge(domino.getLeft(), 1, Integer::sum);
            dotCounts.merge(domino.getRight(), 1, Integer::sum);
        }
        for (int count : dotCounts.values()) {
            if (count % 2 != 0) {
                return false;
            }
        }
        return true;
    }

    /**
     * Treats every domino as an edge between its two dots and walks all edges exactly once
     * (Hierholzer's algorithm), flipping a domino when it is walked from right to left.
     * The result holds fewer dominoes than the input when they are not all connected.
     */
    private static List<Domino> buildChain(List<Domino> dominoes) {
        Map<Integer, Deque<Integer>> indexesByDot = new HashMap<>();
        for (int index = 0; index < dominoes.size(); index++) {
            Domino domino = dominoes.get(index);
            indexesByDot.computeIfAbsent(domino.getLeft(), key -> new ArrayDeque<>()).add(index);
            if (domino.getRight() != domino.getLeft()) {
                indexesByDot.computeIfAbsent(domino.getRight(), key -> new ArrayDeque<>()).add(index);
            }
        }

        boolean[] used = new boolean[dominoes.size()];
        Deque<Visit> stack = new ArrayDeque<>();
        stack.push(new Visit(dominoes.get(0).getLeft(), null));

        List<Domino> chainReversed = new ArrayList<>();
        while (!stack.isEmpty()) {
            Visit current = stack.peek();
            Deque<Integer> candidates = indexesByDot.get(current.dot);
            while (!candidates.isEmpty() && used[candidates.peek()]) {
                candidates.poll();
            }

            if (candidates.isEmpty()) {
                stack.pop();
                if (current.arrivedBy != null) {
                    chainReversed.add(current.arrivedBy);
                }
            } else {
                int index = candidates.poll();
                used[index] = true;
                Domino domino = dominoes.get(index);
                if (domino.getLeft() == current.dot) {
                    stack.push(new Visit(domino.getRight(), domino));
                } else {
                    Domino flipped = new Domino(domino.getRight(), domino.getLeft());
                    stack.push(new Visit(domino.getLeft(), flipped));
                }
            }
        }

        Collections.reverse(chainReversed);
        return chainReversed;
    }

    /**
     * A dot reached while walking, together with the domino that led here.
     * The domino is oriented so that its right half is this dot.
     */
    private static final class Visit {
        final int dot;
        final Domino arrivedBy;

        Visit(int dot, Domino arrivedBy) {
            this.dot = dot;
            this.arrivedBy = arrivedBy;
        }
    }

}
