import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Dominoes {

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        List<Domino> chain = new ArrayList<>();
        if (inputDominoes == null || inputDominoes.isEmpty()) {
            return chain;
        }

        int count = inputDominoes.size();

        // Treat every dot value as a vertex and every domino as an edge of a multigraph.
        Map<Integer, Deque<Integer>> adjacency = new HashMap<>();
        for (int i = 0; i < count; i++) {
            Domino domino = inputDominoes.get(i);
            adjacency.computeIfAbsent(domino.getLeft(), k -> new ArrayDeque<>()).push(i);
            adjacency.computeIfAbsent(domino.getRight(), k -> new ArrayDeque<>()).push(i);
        }

        // A closed chain (first and last dots equal) exists only if every dot value
        // occurs an even number of times.
        for (Deque<Integer> edges : adjacency.values()) {
            if (edges.size() % 2 != 0) {
                throw new ChainNotFoundException("No chain possible: a dot value occurs an odd number of times");
            }
        }

        boolean[] used = new boolean[count];
        Deque<Integer> vertexStack = new ArrayDeque<>();
        Deque<Integer> edgeStack = new ArrayDeque<>();

        int start = inputDominoes.get(0).getLeft();
        vertexStack.push(start);
        edgeStack.push(-1);

        // Hierholzer's algorithm: walk until stuck, then backtrack and splice in sub-circuits.
        // Dominoes are emitted in backtracking order, which is already a valid chain.
        while (!vertexStack.isEmpty()) {
            int vertex = vertexStack.peek();
            int edge = nextUnusedEdge(vertex, adjacency, used);
            if (edge >= 0) {
                used[edge] = true;
                Domino domino = inputDominoes.get(edge);
                int next = domino.getLeft() == vertex ? domino.getRight() : domino.getLeft();
                vertexStack.push(next);
                edgeStack.push(edge);
            } else {
                vertexStack.pop();
                int arrivedBy = edgeStack.pop();
                if (arrivedBy >= 0) {
                    int parent = vertexStack.peek();
                    chain.add(orient(inputDominoes.get(arrivedBy), vertex, parent));
                }
            }
        }

        if (chain.size() != count) {
            throw new ChainNotFoundException("No chain possible: dominoes are not all connected");
        }
        return chain;
    }

    private int nextUnusedEdge(int vertex, Map<Integer, Deque<Integer>> adjacency, boolean[] used) {
        Deque<Integer> edges = adjacency.get(vertex);
        while (!edges.isEmpty()) {
            int edge = edges.pop();
            if (!used[edge]) {
                return edge;
            }
        }
        return -1;
    }

    private Domino orient(Domino domino, int first, int second) {
        if (domino.getLeft() == first && domino.getRight() == second) {
            return domino;
        }
        return new Domino(first, second);
    }

}
