import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

class Dominoes {

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        List<Domino> result = new ArrayList<>();
        if (inputDominoes == null || inputDominoes.isEmpty()) {
            return result;
        }

        int n = inputDominoes.size();
        int[][] halves = new int[n][2];
        for (int i = 0; i < n; i++) {
            List<Integer> values = inputDominoes.get(i).getValues();
            halves[i][0] = values.get(0);
            halves[i][1] = values.get(1);
        }

        if (!hasEvenDotCounts(halves)) {
            throw new ChainNotFoundException("No chain possible: dot counts are not all even");
        }

        // Every closed chain can be rotated/reversed so that it starts with domino 0.
        boolean[] used = new boolean[n];
        used[0] = true;
        List<int[]> placed = new ArrayList<>(); // each entry: {index, left, right}
        placed.add(new int[]{0, halves[0][0], halves[0][1]});

        if (!extend(halves, used, placed, halves[0][0], halves[0][1])) {
            throw new ChainNotFoundException("No valid domino chain found");
        }

        for (int[] p : placed) {
            result.add(new Domino(p[1], p[2]));
        }
        return result;
    }

    private boolean hasEvenDotCounts(int[][] halves) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int[] domino : halves) {
            counts.merge(domino[0], 1, Integer::sum);
            counts.merge(domino[1], 1, Integer::sum);
        }
        for (int count : counts.values()) {
            if (count % 2 != 0) {
                return false;
            }
        }
        return true;
    }

    private boolean extend(int[][] halves, boolean[] used, List<int[]> placed, int start, int end) {
        if (placed.size() == halves.length) {
            return end == start;
        }

        // Identical stones at this level lead to identical outcomes; try each kind only once.
        Set<List<Integer>> tried = new HashSet<>();

        for (int i = 0; i < halves.length; i++) {
            if (used[i]) {
                continue;
            }
            int a = halves[i][0];
            int b = halves[i][1];
            if (!tried.add(Arrays.asList(Math.min(a, b), Math.max(a, b)))) {
                continue;
            }

            for (int orientation = 0; orientation < 2; orientation++) {
                if (orientation == 1 && a == b) {
                    continue; // reversed double is identical to the original
                }
                int left = (orientation == 0) ? a : b;
                int right = (orientation == 0) ? b : a;
                if (left != end) {
                    continue;
                }

                used[i] = true;
                placed.add(new int[]{i, left, right});
                if (extend(halves, used, placed, start, right)) {
                    return true;
                }
                placed.remove(placed.size() - 1);
                used[i] = false;
            }
        }
        return false;
    }

}
