```
class EmptyListException(Exception):
    """Exception raised when the linked list is empty.

    message: explanation of the error.
    """

    def __init__(self, message):
        super().__init__(message)
        self.message = message


class Node:
    """A single node in a singly linked list."""

    def __init__(self, value):
        self._value = value
        self._next = None

    def value(self):
        """Return the value stored in this node."""
        return self._value

    def next(self):
        """Return the next node, or None if this is the last node."""
        return self._next


class LinkedList:
    """A singly linked list used as a LIFO stack."""

    def __init__(self, values=None):
        self._head = None
        self._length = 0
        if values is not None:
            for value in values:
                self.push(value)

    def __iter__(self):
        """Iterate over the values from head to tail."""
        node = self._head
        while node is not None:
            yield node.value()
            node = node.next()

    def __len__(self):
        """Return the number of nodes in the list."""
        return self._length

    def head(self):
        """Return the head node without removing it."""
        if self._head is None:
            raise EmptyListException("The list is empty.")
        return self._head

    def push(self, value):
        """Add a new value to the head of the list."""
        new_node = Node(value)
        new_node._next = self._head
        self._head = new_node
        self._length += 1

    def pop(self):
        """Remove the head node and return its value."""
        if self._head is None:
            raise EmptyListException("The list is empty.")
        node = self._head
        self._head = node.next()
        self._length -= 1
        return node.value()

    def reversed(self):
        """Return a new LinkedList with the values in reverse order.

        Iterating the current list yields values head-first. Pushing
        them in that order onto a new list places the original tail at
        the new head, so the new list plays the songs in reverse.
        """
        return LinkedList(self)
