func parseNumber(word string) (int, bool) {
	n, err := strconv.Atoi(word)
	if err != nil {
		return 0, false
	}
	return n, true
}

// parseOperation recognises the operation at the start of words. It returns
// the operation and the number of words it consumed, or nil and 0 if the
// words do not start with a supported operation. words must not be empty.
func parseOperation(words []string) (operation, int) {
	switch {
	case words[0] == "plus":
		return add, 1
	case words[0] == "minus":
		return subtract, 1
	case len(words) > 1 && words[0] == "multiplied" && words[1] == "by":
		return multiply, 2
	case len(words) > 1 && words[0] == "divided" && words[1] == "by":
		return divide, 2
	default:
		return nil, 0
	}
