		result, ok = op.apply(result, operand)
		if !ok {
			return 0, false
		}
	}

	return toInt(result)
}

// problemWords checks that question has the form "What is ...", with an
// optional trailing question mark. It returns the words that follow "What is",
// lowercased so that the question is not case sensitive.
func problemWords(question string) ([]string, bool) {
	text := strings.TrimSuffix(strings.TrimSpace(question), "?")
	words := strings.Fields(strings.ToLower(text))
	if len(words) < 3 || words[0] != "what" || words[1] != "is" {
		return nil, false
	}
	return words[2:], true
}

// parseNumber parses a whole number, which may be negative, such as "-42".
func parseNumber(word string) (*big.Int, bool) {
	return new(big.Int).SetString(word, 10)
}

// parseOperation reads the operation at the start of words. It returns the
// operation and the number of words it occupies.
func parseOperation(words []string) (operation, int, bool) {
	if len(words) == 0 {
		return 0, 0, false
	}

	// "multiplied" and "divided" are only operations when followed by "by".
	if len(words) >= 2 && words[1] == "by" {
		switch words[0] {
		case "multiplied":
			return multipliedBy, 2, true
		case "divided":
			return dividedBy, 2, true
		}
	}

	switch words[0] {
	case "plus":
		return plus, 1, true
	case "minus":
		return minus, 1, true
	}
	return 0, 0, false
}

// apply returns the result of op applied with a as the left operand and b as
// the right operand. It reports false if the operation is undefined, which only
// happens when dividing by zero.
func (op operation) apply(a, b *big.Int) (*big.Int, bool) {
	switch op {
	case plus:
		return new(big.Int).Add(a, b), true
	case minus:
		return new(big.Int).Sub(a, b), true
	case multipliedBy:
		return new(big.Int).Mul(a, b), true
	case dividedBy:
		if b.Sign() == 0 {
			return nil, false
		}
		// Quo truncates towards zero, as Go's integer division does.
		return new(big.Int).Quo(a, b), true
	}
	return nil, false
}

// toInt converts n to an int. It reports false if n is outside the range of int.
func toInt(n *big.Int) (int, bool) {
	if !n.IsInt64() {
		return 0, false
	}
	v := n.Int64()
	// int can be narrower than 64 bits, so check against its actual range.
	if v < math.MinInt || v > math.MaxInt {
		return 0, false
	}
	return int(v), true
}
