		if (a == -1 && b == math.MinInt) || (b == -1 && a == math.MinInt) {
			return 0, false
		}
		r := a * b
		if r/b != a {
			return 0, false
		}
		return r, true
	case "/":
		if b == 0 {
			return 0, false
		}
		if a == math.MinInt && b == -1 {
			return 0, false
		}
		return a / b, true
