The current `Answer` is a stub that panics. I'll implement it as a left-to-right evaluator:

- **Validation:** The question must start with `What is ` and end with `?`. Anything else is rejected as a non-math question.
- **Tokenizing:** The body is split on whitespace. The first token must be an integer.
- **Operators:** `plus`, `minus`, `multiplied by`, and `divided by` are recognized. Each operator must be followed by an integer operand. Any other word, such as `cubed`, is rejected as an unsupported operation.
- **Evaluation:** Operations are applied strictly left to right, ignoring conventional precedence.
- **Errors:** Malformed syntax, missing operands, and division by zero return `(0, false)`.

wordy.go
```
package wordy

import (
	"strconv"
	"strings"
)

const questionPrefix = "What is "

// Answer evaluates a simple math word problem, applying operations strictly
// from left to right. It returns the result and true on success, or 0 and
// false if the question is not a valid or supported math problem.
func Answer(question string) (int, bool) {
	if !strings.HasPrefix(question, questionPrefix) || !strings.HasSuffix(question, "?") {
		return 0, false
	}

	body := strings.TrimSuffix(strings.TrimPrefix(question, questionPrefix), "?")
	tokens := strings.Fields(body)
	if len(tokens) == 0 {
		return 0, false
	}

	result, err := strconv.Atoi(tokens[0])
	if err != nil {
		return 0, false
	}

	i := 1
	for i < len(tokens) {
		var op string
		switch tokens[i] {
		case "plus", "minus":
			op = tokens[i]
			i++
		case "multiplied", "divided":
			if i+1 >= len(tokens) || tokens[i+1] != "by" {
				return 0, false
			}
			op = tokens[i]
			i += 2
		default:
			return 0, false
		}

		if i >= len(tokens) {
			return 0, false
		}

		operand, err := strconv.Atoi(tokens[i])
		if err != nil {
			return 0, false
		}
		i++

		switch op {
		case "plus":
			result += operand
		case "minus":
			result -= operand
		case "multiplied":
			result *= operand
		case "divided":
			if operand == 0 {
				return 0, false
			}
			result /= operand
		}
	}

	return result, true
}
