// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

/// A node in the doubly linked list. Nodes are heap-allocated via `Box::leak`
/// and owned by the list; they are freed either by `Cursor::take` or by `Drop`.
struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

/// Allocates a new node with the given neighbors and returns a pointer to it.
/// The node is not linked into any list by this function; the caller must do that.
fn new_node<T>(
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
) -> NonNull<Node<T>> {
    let boxed = Box::new(Node {
        element,
        prev,
        next,
    });
    NonNull::from(Box::leak(boxed))
}

// Safety invariants of the list:
// - `front` is `None` iff `back` is `None` iff `len == 0`.
// - If `front` is `Some(f)`, then `(*f).prev` is `None`, and `back` is `Some(b)`
//   where `(*b).next` is `None`.
// - For every adjacent pair of nodes `a`, `b`: `(*a).next == Some(b)` iff `(*b).prev == Some(a)`.
// - `len` equals the number of nodes reachable from `front` via `next`.
// - Every node pointer stored in the list was produced by `new_node` and is freed exactly once.
pub struct LinkedList<T> {
    front: Option<NonNull<Node<T>>>,
    back: Option<NonNull<Node<T>>>,
    len: usize,
    marker: PhantomData<Box<Node<T>>>,
}

// Safety invariants of the cursor:
// - `cur`, when `Some`, points to a live node that belongs to `list`.
// - `cur == None` is the "ghost" position between the back and the front of the list.
// - The cursor holds exclusive access (`&mut`) to the list, so no other references
//   to the nodes can exist while the cursor is alive.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    cur: Option<NonNull<Node<T>>>,
}

// Safety invariants of the iterator:
// - `next`, when `Some`, points to a live node of the list borrowed for `'a`.
// - The list cannot be mutated while the iterator exists, because it holds a shared borrow.
pub struct Iter<'a, T> {
    next: Option<NonNull<Node<T>>>,
    marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            front: None,
            back: None,
            len: 0,
            marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let cur = self.front;
        Cursor { list: self, cur }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let cur = self.back;
        Cursor { list: self, cur }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.front,
            marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cur = self.front;
        while let Some(node) = cur {
            // SAFETY: `node` is a live node owned by this list, and each node is
            // visited exactly once because we walk the list forward and never revisit.
            // Reconstructing the Box transfers ownership back so it is freed here.
            let boxed = unsafe { Box::from_raw(node.as_ptr()) };
            cur = boxed.next;
        }
        self.front = None;
        self.back = None;
        self.len = 0;
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `cur`, when `Some`, points to a live node of the list (cursor invariant).
        // The returned reference is tied to the `&mut self` borrow, so it cannot
        // coexist with another reference obtained from this cursor.
        self.cur.map(|node| unsafe { &mut (*node.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        self.cur = match self.cur {
            // SAFETY: `node` is a live node of the list (cursor invariant).
            Some(node) => unsafe { (*node.as_ptr()).next },
            // From the ghost position, moving forward wraps to the front.
            None => self.list.front,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        self.cur = match self.cur {
            // SAFETY: `node` is a live node of the list (cursor invariant).
            Some(node) => unsafe { (*node.as_ptr()).prev },
            // From the ghost position, moving backward wraps to the back.
            None => self.list.back,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.cur?;
        // SAFETY: `node` is a live node owned by the list (cursor invariant). We
        // unlink it by fixing up its neighbors' pointers before reclaiming the Box, so
        // all remaining nodes keep valid links. The neighbors are distinct allocations
        // from `node`, so writing through their pointers is valid.
        unsafe {
            let Node { element, prev, next } = *Box::from_raw(node.as_ptr());

            match prev {
                Some(p) => (*p.as_ptr()).next = next,
                None => self.list.front = next,
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = prev,
                None => self.list.back = prev,
            }

            self.list.len -= 1;
            // Move to the neighbor closest to the back: prefer next, fall back to prev.
            self.cur = next.or(prev);
            Some(element)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        match self.cur {
            Some(cur) => {
                // SAFETY: `cur` is a live node of the list (cursor invariant). `next` is
                // either None or a live node adjacent to `cur`. The new node is linked
                // between `cur` and `next`, keeping the back-pointers consistent.
                unsafe {
                    let next = (*cur.as_ptr()).next;
                    let node = new_node(element, Some(cur), next);
                    (*cur.as_ptr()).next = Some(node);
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(node),
                        None => self.list.back = Some(node),
                    }
                }
            }
            None => {
                // Ghost position: inserting "after" it places the element at the front.
                let old_front = self.list.front;
                let node = new_node(element, None, old_front);
                match old_front {
                    // SAFETY: `f` is a live node of the list, so writing its `prev` is valid.
                    Some(f) => unsafe { (*f.as_ptr()).prev = Some(node) },
                    None => self.list.back = Some(node),
                }
                self.list.front = Some(node);
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        match self.cur {
            Some(cur) => {
                // SAFETY: `cur` is a live node of the list (cursor invariant). `prev` is
                // either None or a live node adjacent to `cur`. The new node is linked
                // between `prev` and `cur`, keeping the forward-pointers consistent.
                unsafe {
                    let prev = (*cur.as_ptr()).prev;
                    let node = new_node(element, prev, Some(cur));
                    (*cur.as_ptr()).prev = Some(node);
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(node),
                        None => self.list.front = Some(node),
                    }
                }
            }
            None => {
                // Ghost position: inserting "before" it places the element at the back.
                let old_back = self.list.back;
                let node = new_node(element, old_back, None);
                match old_back {
                    // SAFETY: `b` is a live node of the list, so writing its `next` is valid.
                    Some(b) => unsafe { (*b.as_ptr()).next = Some(node) },
                    None => self.list.front = Some(node),
                }
                self.list.back = Some(node);
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: `node` is a live node of the list, which is borrowed immutably for `'a`
        // and therefore cannot be modified or freed while this iterator exists.
        unsafe {
            let node_ref = &*node.as_ptr();
            self.next = node_ref.next;
            Some(&node_ref.element)
        }
    }
}

// SAFETY: The list owns its elements through heap nodes, so it can be sent to another
// thread exactly when its elements can be sent.
unsafe impl<T: Send> Send for LinkedList<T> {}

// SAFETY: Shared access only yields `&T` (via `iter`), so sharing the list is sound
// exactly when `T` can be shared.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: The iterator yields `&'a T`, which is equivalent to sending/sharing `&T`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}

// SAFETY: The iterator only yields shared references, so it is sound to share it
// exactly when `T` can be shared.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}
