// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // Safety: `current`, when `Some`, points to a live node owned by the list,
        // and we hold `&mut` access to the list through the cursor.
        unsafe { self.current.map(|mut p| &mut p.as_mut().element) }
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        // Safety: `current` is either `None` or a valid node in the list.
        self.current = match self.current {
            Some(p) => unsafe { p.as_ref().next },
            None => self.list.head,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        // Safety: `current` is either `None` or a valid node in the list.
        self.current = match self.current {
            Some(p) => unsafe { p.as_ref().prev },
            None => self.list.tail,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;
        // Safety: `node` is a valid node owned by the list; after unlinking it we
        // reclaim the box exactly once, so no dangling pointers remain.
        unsafe {
            let boxed = Box::from_raw(node.as_ptr());
            let prev = boxed.prev;
            let next = boxed.next;

            match prev {
                Some(mut p) => p.as_mut().next = next,
                None => self.list.head = next,
            }
            match next {
                Some(mut n) => n.as_mut().prev = prev,
                None => self.list.tail = prev,
            }

            self.list.len -= 1;
            // Move to the neighbor closest to the back.
            self.current = next.or(prev);
            Some(boxed.element)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let new = Box::into_raw(Box::new(Node {
            element,
            prev: None,
            next: None,
        }));
        // Safety: `new` is a freshly allocated, valid, uniquely owned node. We
        // only dereference `current` when it is `Some`, meaning it is a live node.
        unsafe {
            let new_ptr = NonNull::new_unchecked(new);
            match self.current {
                Some(mut cur) => {
                    let next = cur.as_ref().next;
                    (*new).prev = Some(cur);
                    (*new).next = next;
                    cur.as_mut().next = Some(new_ptr);
                    match next {
                        Some(mut n) => n.as_mut().prev = Some(new_ptr),
                        None => self.list.tail = Some(new_ptr),
                    }
                }
                None => {
                    // Ghost position: insert at the front of the list.
                    let old_head = self.list.head;
                    (*new).next = old_head;
                    match old_head {
                        Some(mut h) => h.as_mut().prev = Some(new_ptr),
                        None => self.list.tail = Some(new_ptr),
                    }
                    self.list.head = Some(new_ptr);
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = Box::into_raw(Box::new(Node {
            element,
            prev: None,
            next: None,
        }));
        // Safety: same reasoning as `insert_after`.
        unsafe {
            let new_ptr = NonNull::new_unchecked(new);
            match self.current {
                Some(mut cur) => {
                    let prev = cur.as_ref().prev;
                    (*new).next = Some(cur);
                    (*new).prev = prev;
                    cur.as_mut().prev = Some(new_ptr);
                    match prev {
                        Some(mut p) => p.as_mut().next = Some(new_ptr),
                        None => self.list.head = Some(new_ptr),
                    }
                }
                None => {
                    // Ghost position: insert at the back of the list.
                    let old_tail = self.list.tail;
                    (*new).prev = old_tail;
                    match old_tail {
                        Some(mut t) => t.as_mut().next = Some(new_ptr),
                        None => self.list.head = Some(new_ptr),
                    }
                    self.list.tail = Some(new_ptr);
                }
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // Safety: `node` is a live node of the list borrowed for `'a`, and the
        // list cannot be mutated while this iterator exists.
        unsafe {
            let node_ref = &*node.as_ptr();
            self.next = node_ref.next;
            self.remaining -= 1;
            Some(&node_ref.element)
        }
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cur = self.head;
        while let Some(node) = cur {
            // Safety: each node was allocated with `Box::into_raw` and is freed
            // exactly once here, walking the list via `next` before freeing.
            unsafe {
                let boxed = Box::from_raw(node.as_ptr());
                cur = boxed.next;
            }
        }
        self.head = None;
        self.tail = None;
        self.len = 0;
    }
}
