            None => self.back = Some(new),
        }
        (*at.as_ptr()).next = Some(new);
    }

    /// Link `new` directly before `at`.
    ///
    /// # Safety
    /// - `at` must be a live node owned by this list.
    /// - `new` must be a live, unlinked node.
    unsafe fn link_before(&mut self, at: NonNull<Node<T>>, new: NonNull<Node<T>>) {
        // SAFETY: `at` is live (caller contract).
        let prev = (*at.as_ptr()).prev;
        // SAFETY: `new` is live and unlinked (caller contract).
        (*new.as_ptr()).next = Some(at);
        (*new.as_ptr()).prev = prev;
        match prev {
            // SAFETY: `p` is a live node in the list by the list invariants.
            Some(p) => (*p.as_ptr()).next = Some(new),
            None => self.front = Some(new),
        }
        (*at.as_ptr()).prev = Some(new);
    }

    /// Link `new` as the new front of the list.
    ///
    /// # Safety
    /// `new` must be a live, unlinked node.
    unsafe fn link_front(&mut self, new: NonNull<Node<T>>) {
        match self.front {
            Some(f) => {
                // SAFETY: `new` is live and unlinked; `f` is live by invariants.
                (*new.as_ptr()).next = Some(f);
                (*f.as_ptr()).prev = Some(new);
            }
            None => {
                // SAFETY: `new` is live and unlinked.
                (*new.as_ptr()).next = None;
                self.back = Some(new);
            }
        }
        (*new.as_ptr()).prev = None;
        self.front = Some(new);
    }

    /// Link `new` as the new back of the list.
    ///
    /// # Safety
    /// `new` must be a live, unlinked node.
    unsafe fn link_back(&mut self, new: NonNull<Node<T>>) {
        match self.back {
            Some(b) => {
                // SAFETY: `new` is live and unlinked; `b` is live by invariants.
                (*new.as_ptr()).prev = Some(b);
                (*b.as_ptr()).next = Some(new);
            }
            None => {
                // SAFETY: `new` is live and unlinked.
                (*new.as_ptr()).prev = None;
                self.front = Some(new);
            }
        }
        (*new.as_ptr()).next = None;
        self.back = Some(new);
    }

    /// Unlink the node `at` from the list, free it and return its element.
    ///
    /// # Safety
    /// `at` must be a live node owned by this list. It must not be used afterwards.
    unsafe fn unlink(&mut self, at: NonNull<Node<T>>) -> T {
        // SAFETY: `at` was created via `Box::into_raw`/`Box::leak` and is live,
        // so reconstructing the box takes ownership exactly once.
        let Node {
            next,
            prev,
            element,
        } = *Box::from_raw(at.as_ptr());
        match prev {
            // SAFETY: `p` is a live node in the list.
            Some(p) => (*p.as_ptr()).next = next,
            None => self.front = next,
        }
        match next {
            // SAFETY: `n` is a live node in the list.
            Some(n) => (*n.as_ptr()).prev = prev,
            None => self.back = prev,
        }
        self.len -= 1;
        element
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is either `None` or a live node owned by the list.
        // We hold `&mut self`, so no other reference to the element exists.
        self.current.map(|n| unsafe { &mut (*n.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `cur` is a live node owned by the list.
            Some(cur) => unsafe { (*cur.as_ptr()).next },
            // Ghost position wraps around to the front.
            None => self.list.front,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `cur` is a live node owned by the list.
            Some(cur) => unsafe { (*cur.as_ptr()).prev },
            // Ghost position wraps around to the back.
            None => self.list.back,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let cur = self.current?;
        // SAFETY: `cur` is a live node owned by the list.
        let (next, prev) = unsafe { ((*cur.as_ptr()).next, (*cur.as_ptr()).prev) };
        self.current = next.or(prev);
        // SAFETY: `cur` is live and owned by the list; the cursor no longer
        // references it after this point because `current` was updated above.
        Some(unsafe { self.list.unlink(cur) })
    }

    pub fn insert_after(&mut self, element: T) {
        let new = NonNull::from(Box::leak(Box::new(Node {
            next: None,
            prev: None,
            element,
        })));
        match self.current {
            // SAFETY: `cur` is live; `new` is a freshly allocated, unlinked node.
            Some(cur) => unsafe { self.list.link_after(cur, new) },
            // Ghost position: "after" the ghost means the front.
            // SAFETY: `new` is a freshly allocated, unlinked node.
            None => unsafe { self.list.link_front(new) },
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = NonNull::from(Box::leak(Box::new(Node {
            next: None,
            prev: None,
            element,
        })));
        match self.current {
            // SAFETY: `cur` is live; `new` is a freshly allocated, unlinked node.
            Some(cur) => unsafe { self.list.link_before(cur, new) },
            // Ghost position: "before" the ghost means the back.
            // SAFETY: `new` is a freshly allocated, unlinked node.
            None => unsafe { self.list.link_back(new) },
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let cur = self.current?;
        // SAFETY: The iterator borrows the list immutably for `'a`, so nodes
        // are live and not mutated for the duration of the borrow.
        unsafe {
            self.current = (*cur.as_ptr()).next;
            Some(&(*cur.as_ptr()).element)
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Repeatedly remove the front element until the list is empty.
        while self.cursor_front().take().is_some() {}
    }
}
