// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

/// A node of the list. Nodes are allocated on the heap and linked to each other
/// with raw pointers.
struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

/// Allocates a new node holding `element`. The node is not linked into any list yet.
fn new_node<T>(element: T) -> NonNull<Node<T>> {
    NonNull::from(Box::leak(Box::new(Node {
        element,
        prev: None,
        next: None,
    })))
}

/// A doubly linked list.
///
/// Safety invariants (all `unsafe` code in this module relies on them):
/// 1. `front` and `back` are `None` if and only if the list is empty.
///    `len` is the number of nodes in the list.
/// 2. Every node was allocated by `new_node` and is owned exclusively by the list.
///    A node is freed exactly once: when it is unlinked (in `Cursor::take`),
///    or when the list is dropped.
/// 3. `front.prev` and `back.next` are `None`. For neighboring nodes `a` and `b`
///    (`a.next == Some(b)`) we have `b.prev == Some(a)`. Following `next` from
///    `front` visits all `len` nodes and ends at `back`.
pub struct LinkedList<T> {
    front: Option<NonNull<Node<T>>>,
    back: Option<NonNull<Node<T>>>,
    len: usize,
    // Tells the compiler that the list owns its nodes (for drop check and variance).
    marker: PhantomData<Box<Node<T>>>,
}

/// A cursor positioned on an element of the list.
///
/// The cursor always sits on an element, unless the list is empty. Moving past
/// the front or the back is not possible: `next` and `prev` then return `None`
/// and the cursor stays where it is.
///
/// Invariant: `current` is `None` if and only if the list is empty. Otherwise it
/// points to a node that is linked into `list`.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Option<NonNull<Node<T>>>,
}

/// An iterator over the elements of a list, from front to back.
///
/// Invariant: `current` is the next node to yield, or `None` once the iteration is over.
pub struct Iter<'a, T> {
    current: Option<NonNull<Node<T>>>,
    marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            front: None,
            back: None,
            len: 0,
            marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.front;
        Cursor { list: self, current }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.back;
        Cursor { list: self, current }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            current: self.front,
            marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Taking the front element until the list is empty frees every node exactly once.
        while self.cursor_front().take().is_some() {}
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: `current` is a node of the list (invariant of `Cursor`), so it is valid.
        // We hold `&mut self`, so no other reference to the element can exist while the
        // returned reference is alive.
        Some(unsafe { &mut (*current.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position.
    /// If the cursor is already on the back element, it stays there and `None` is returned.
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: `current` is a node of the list, so reading its `next` link is valid.
        let next = unsafe { (*current.as_ptr()).next }?;
        self.current = Some(next);
        // SAFETY: `next` is a node of the list. We hold `&mut self`, so no other reference
        // to the element can exist while the returned reference is alive.
        Some(unsafe { &mut (*next.as_ptr()).element })
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position.
    /// If the cursor is already on the front element, it stays there and `None` is returned.
    pub fn prev(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: `current` is a node of the list, so reading its `prev` link is valid.
        let prev = unsafe { (*current.as_ptr()).prev }?;
        self.current = Some(prev);
        // SAFETY: `prev` is a node of the list. We hold `&mut self`, so no other reference
        // to the element can exist while the returned reference is alive.
        Some(unsafe { &mut (*prev.as_ptr()).element })
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let current = self.current?;
        // SAFETY: `current` is a node of the list, so its links are valid to read.
        let (prev, next) = unsafe { ((*current.as_ptr()).prev, (*current.as_ptr()).next) };
        // Move the cursor away from the node before it is freed. If there is no neighbor,
        // the list becomes empty and so does the cursor.
        self.current = next.or(prev);
        // SAFETY: `current` is linked into the list. The cursor no longer refers to it,
        // so `unlink` takes ownership of it and frees it exactly once.
        Some(unsafe { self.unlink(current) })
    }

    /// Insert an element directly after the current element. The cursor stays on its element.
    /// If the list is empty, the new element becomes the cursor's element.
    pub fn insert_after(&mut self, element: T) {
        let node = new_node(element);
        let (prev, next) = match self.current {
            // SAFETY: `current` is a node of the list, so reading its `next` link is valid.
            Some(current) => (Some(current), unsafe { (*current.as_ptr()).next }),
            // The list is empty, so the new node has no neighbors.
            None => (None, None),
        };
        // SAFETY: `node` is a fresh node, and `prev`/`next` are its neighbors in the list
        // (both `None` if the list is empty). See the contract of `link_between`.
        unsafe { self.link_between(node, prev, next) };
        if self.current.is_none() {
            self.current = Some(node);
        }
    }

    /// Insert an element directly before the current element. The cursor stays on its element.
    /// If the list is empty, the new element becomes the cursor's element.
    pub fn insert_before(&mut self, element: T) {
        let node = new_node(element);
        let (prev, next) = match self.current {
            // SAFETY: `current` is a node of the list, so reading its `prev` link is valid.
            Some(current) => (unsafe { (*current.as_ptr()).prev }, Some(current)),
            // The list is empty, so the new node has no neighbors.
            None => (None, None),
        };
        // SAFETY: `node` is a fresh node, and `prev`/`next` are its neighbors in the list
        // (both `None` if the list is empty). See the contract of `link_between`.
        unsafe { self.link_between(node, prev, next) };
        if self.current.is_none() {
            self.current = Some(node);
        }
    }

    /// Links the fresh `node` into the list between `prev` and `next` and updates
    /// `front`, `back` and `len` accordingly.
    ///
    /// # Safety
    /// - `node` must be a fresh node: it is not linked into any list and not referenced elsewhere.
    /// - If `prev` is `Some(p)`, then `p` is a node of the list and `p.next == next`.
    ///   If `prev` is `None`, then `next` is the front of the list (`None` if the list is empty).
    /// - If `next` is `Some(n)`, then `n` is a node of the list and `n.prev == prev`.
    ///   If `next` is `None`, then `prev` is the back of the list (`None` if the list is empty).
    unsafe fn link_between(
        &mut self,
        node: NonNull<Node<T>>,
        prev: Option<NonNull<Node<T>>>,
        next: Option<NonNull<Node<T>>>,
    ) {
        // SAFETY: `node` is valid and not referenced elsewhere (see the contract).
        unsafe {
            (*node.as_ptr()).prev = prev;
            (*node.as_ptr()).next = next;
        }
        match prev {
            // SAFETY: `p` is a node of the list (see the contract).
            Some(p) => unsafe { (*p.as_ptr()).next = Some(node) },
            None => self.list.front = Some(node),
        }
        match next {
            // SAFETY: `n` is a node of the list (see the contract).
            Some(n) => unsafe { (*n.as_ptr()).prev = Some(node) },
            None => self.list.back = Some(node),
        }
        self.list.len += 1;
    }

    /// Unlinks `node` from the list, frees it, and returns its element.
    ///
    /// # Safety
    /// `node` must be a node that is currently linked into the list. After this call
    /// the node is deallocated and must not be used anymore.
    unsafe fn unlink(&mut self, node: NonNull<Node<T>>) -> T {
        // SAFETY: `node` is a node of the list (see the contract).
        let (prev, next) = unsafe { ((*node.as_ptr()).prev, (*node.as_ptr()).next) };
        match prev {
            // SAFETY: `p` is a neighbor of `node`, so it is a node of the list.
            Some(p) => unsafe { (*p.as_ptr()).next = next },
            None => self.list.front = next,
        }
        match next {
            // SAFETY: `n` is a neighbor of `node`, so it is a node of the list.
            Some(n) => unsafe { (*n.as_ptr()).prev = prev },
            None => self.list.back = prev,
        }
        self.list.len -= 1;
        // SAFETY: `node` was allocated as a `Box` by `new_node`. It is no longer linked into
        // the list, so we own it exclusively, and it is freed exactly once here.
        let node = unsafe { *Box::from_raw(node.as_ptr()) };
        node.element
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let current = self.current?;
        // SAFETY: `current` is a node of the list. The list is borrowed for `'a`, so the
        // node is neither freed nor mutated while the returned reference is alive.
        unsafe {
            self.current = (*current.as_ptr()).next;
            Some(&(*current.as_ptr()).element)
        }
    }
}

// SAFETY: `LinkedList<T>` owns its nodes exclusively, like a `Box<T>` would. Moving it to
// another thread is therefore sound whenever `T` can be sent.
unsafe impl<T: Send> Send for LinkedList<T> {}

// SAFETY: Through a shared reference the list only hands out `&T` (via `Iter`), so sharing
// it is sound whenever `T` can be shared.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: `Cursor` holds an exclusive borrow of the list, so it can be sent whenever `T`
// can be sent.
unsafe impl<T: Send> Send for Cursor<'_, T> {}

// SAFETY: All operations of `Cursor` take `&mut self`, so a shared reference to it cannot
// access the elements. Like `&mut LinkedList<T>`, it is shared soundly whenever `T: Sync`.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: `Iter` only yields shared references to the elements, so it can be sent
// whenever `T` can be shared.
unsafe impl<T: Sync> Send for Iter<'_, T> {}

// SAFETY: `Iter` only yields shared references to the elements, so it can be shared
// whenever `T` can be shared.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}
