// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

/// A node in the doubly linked list.
///
/// Invariants:
/// - `prev` points to the node before this one, or is `None` if this is the head.
/// - `next` points to the node after this one, or is `None` if this is the tail.
/// - Every node reachable from the list was allocated via `Box::into_raw`.
struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

pub struct LinkedList<T> {
    /// Front node, or `None` if the list is empty.
    head: Option<NonNull<Node<T>>>,
    /// Back node, or `None` if the list is empty.
    tail: Option<NonNull<Node<T>>>,
    /// Number of elements. Invariant: equals the number of linked nodes.
    len: usize,
    /// Marker making the list covariant in `T` and telling dropck that we own `T`s.
    marker: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    /// The current node, or `None` for the "ghost" position between the back and the front.
    current: Option<NonNull<Node<T>>>,
}

pub struct Iter<'a, T> {
    /// Next node to yield from the front.
    front: Option<NonNull<Node<T>>>,
    /// Number of remaining elements, used to stop iteration correctly.
    remaining: usize,
    marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.head.is_none()
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.head;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.tail;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            front: self.head,
            remaining: self.len,
            marker: PhantomData,
        }
    }
}

impl<T> Default for LinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is either `None` or points to a live node owned by the list.
        // We have `&mut self`, so no other reference to the node exists through this list.
        self.current.map(|node| unsafe { &mut (*node.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is a live node (or `None`); reading its `next` link is valid.
        self.current = match self.current {
            Some(node) => unsafe { (*node.as_ptr()).next },
            None => self.list.head,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is a live node (or `None`); reading its `prev` link is valid.
        self.current = match self.current {
            Some(node) => unsafe { (*node.as_ptr()).prev },
            None => self.list.tail,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;
        // SAFETY: `node` is a live node owned by the list. We unlink it, fix up
        // neighbor pointers and head/tail, decrement `len`, and reclaim the box exactly once.
        unsafe {
            let boxed = Box::from_raw(node.as_ptr());
            let prev = boxed.prev;
            let next = boxed.next;

            match prev {
                Some(p) => (*p.as_ptr()).next = next,
                None => self.list.head = next,
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = prev,
                None => self.list.tail = prev,
            }

            self.list.len -= 1;
            // Move to the neighbor closest to the back: next if it exists, else prev.
            self.current = next.or(prev);
            Some(boxed.element)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let new_node = NonNull::from(Box::leak(Box::new(Node {
            element,
            prev: None,
            next: None,
        })));

        match self.current {
            None => {
                // Ghost position or empty list: insert at the front.
                // SAFETY: `new_node` is a freshly allocated, valid node we exclusively own.
                // Head/tail are updated to keep the list invariants.
                unsafe {
                    match self.list.head {
                        None => {
                            self.list.head = Some(new_node);
                            self.list.tail = Some(new_node);
                        }
                        Some(old_head) => {
                            (*new_node.as_ptr()).next = Some(old_head);
                            (*old_head.as_ptr()).prev = Some(new_node);
                            self.list.head = Some(new_node);
                        }
                    }
                }
            }
            Some(cur) => {
                // SAFETY: `cur` is a live node. We splice `new_node` between `cur` and its
                // successor, updating the successor's `prev` or the list's `tail`.
                unsafe {
                    let next = (*cur.as_ptr()).next;
                    (*new_node.as_ptr()).prev = Some(cur);
                    (*new_node.as_ptr()).next = next;
                    (*cur.as_ptr()).next = Some(new_node);
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(new_node),
                        None => self.list.tail = Some(new_node),
                    }
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new_node = NonNull::from(Box::leak(Box::new(Node {
            element,
            prev: None,
            next: None,
        })));

        match self.current {
            None => {
                // Ghost position or empty list: insert at the back.
                // SAFETY: `new_node` is freshly allocated and exclusively owned.
                // Head/tail are updated to keep the list invariants.
                unsafe {
                    match self.list.tail {
                        None => {
                            self.list.head = Some(new_node);
                            self.list.tail = Some(new_node);
                        }
                        Some(old_tail) => {
                            (*new_node.as_ptr()).prev = Some(old_tail);
                            (*old_tail.as_ptr()).next = Some(new_node);
                            self.list.tail = Some(new_node);
                        }
                    }
                }
            }
            Some(cur) => {
                // SAFETY: `cur` is a live node. We splice `new_node` between its
                // predecessor and `cur`, updating the predecessor's `next` or the list's `head`.
                unsafe {
                    let prev = (*cur.as_ptr()).prev;
                    (*new_node.as_ptr()).next = Some(cur);
                    (*new_node.as_ptr()).prev = prev;
                    (*cur.as_ptr()).prev = Some(new_node);
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(new_node),
                        None => self.list.head = Some(new_node),
                    }
                }
            }
        }
        self.list.len += 1;
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Free every node exactly once by walking from the head.
        let mut cur = self.head;
        while let Some(node) = cur {
            // SAFETY: every node was allocated with `Box::leak`/`Box::new` and is
            // still owned by the list; we read `next` before reclaiming the box.
            unsafe {
                let boxed = Box::from_raw(node.as_ptr());
                cur = boxed.next;
            }
        }
        self.head = None;
        self.tail = None;
        self.len = 0;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        if self.remaining == 0 {
            return None;
        }
        let node = self.front?;
        // SAFETY: `node` is a live node of the list borrowed for `'a` (the list cannot be
        // mutated while `Iter` exists), so a shared reference with lifetime `'a` is valid.
        unsafe {
            let node_ref = &*node.as_ptr();
            self.front = node_ref.next;
            self.remaining -= 1;
            Some(&node_ref.element)
        }
    }
}

// SAFETY: `LinkedList<T>` owns its nodes exclusively, so it is `Send` whenever `T` is.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: Shared access only yields `&T` through `Iter`, so `Sync` holds when `T: Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}
