// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

/// A doubly linked list.
///
/// Invariants that every method must uphold (the `unsafe` code relies on them):
///
/// 1. `head` is `None` if and only if `tail` is `None`, and both are `None` if and only if `len == 0`.
/// 2. Following `next` from `head` visits exactly `len` nodes and ends at `tail`.
/// 3. `head.prev` and `tail.next` are `None`. For every adjacent pair `a`, `b`
///    (`a.next == Some(b)`) we also have `b.prev == Some(a)`.
/// 4. Every node is a live allocation created by `Node::new_ptr` and is owned exclusively by this list.
pub struct LinkedList<T> {
    head: Option<NonNull<Node<T>>>,
    tail: Option<NonNull<Node<T>>>,
    len: usize,
    // Models ownership of the heap-allocated nodes for variance and drop check.
    marker: PhantomData<Box<Node<T>>>,
}

struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

impl<T> Node<T> {
    /// Allocates a new, unlinked node on the heap and returns ownership of it as a raw pointer.
    fn new_ptr(element: T) -> NonNull<Self> {
        let boxed = Box::new(Node {
            element,
            prev: None,
            next: None,
        });
        // SAFETY: `Box::into_raw` never returns a null pointer.
        unsafe { NonNull::new_unchecked(Box::into_raw(boxed)) }
    }
}

/// A cursor over a `LinkedList`.
///
/// The cursor sits either on an element or on a "ghost" position between the back and the
/// front of the list. `current == None` denotes the ghost. Moving forward from the back element
/// (or backward from the front element) lands on the ghost, and moving from the ghost wraps
/// around to the other end. An empty list consists only of the ghost.
///
/// If `current` is `Some`, it points to a node linked into `list`. The cursor holds a unique
/// borrow of the list, so nothing else can modify the list while the cursor exists.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Option<NonNull<Node<T>>>,
}

/// An iterator over a `LinkedList`, from front to back.
///
/// `current` is the next node to yield, or `None` once the iterator is exhausted.
/// The list is borrowed immutably for `'a`, so its nodes stay alive and unmodified for `'a`.
pub struct Iter<'a, T> {
    current: Option<NonNull<Node<T>>>,
    marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.head;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.tail;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            current: self.head,
            marker: PhantomData,
        }
    }

    /// Links `node` into the list between `prev` and `next`.
    ///
    /// # Safety
    ///
    /// - `node` must come from `Node::new_ptr` and must not currently be linked into any list.
    ///   Ownership of the allocation is transferred to this list.
    /// - `prev` must be `None` or a node currently in this list, and `next` must be its successor.
    /// - If `prev` is `None`, then `next` must be `self.head`.
    /// - If `next` is `None`, then `prev` must be `self.tail`.
    unsafe fn link_node(
        &mut self,
        mut node: NonNull<Node<T>>,
        prev: Option<NonNull<Node<T>>>,
        next: Option<NonNull<Node<T>>>,
    ) {
        // SAFETY: `node` is a fresh node that we exclusively own (precondition),
        // so writing its links is valid.
        unsafe {
            node.as_mut().prev = prev;
            node.as_mut().next = next;
        }

        match prev {
            // SAFETY: `p` is a live node of this list (precondition), and we have `&mut self`,
            // so we have unique access to it.
            Some(mut p) => unsafe { p.as_mut().next = Some(node) },
            None => self.head = Some(node),
        }

        match next {
            // SAFETY: `n` is a live node of this list (precondition), and we have `&mut self`,
            // so we have unique access to it.
            Some(mut n) => unsafe { n.as_mut().prev = Some(node) },
            None => self.tail = Some(node),
        }

        self.len += 1;
    }

    /// Unlinks `node` from the list, frees it, and returns its element.
    ///
    /// # Safety
    ///
    /// `node` must be a node currently linked into this list. After this call the pointer
    /// is dangling and must not be used again.
    unsafe fn unlink_node(&mut self, node: NonNull<Node<T>>) -> T {
        // SAFETY: `node` is linked into this list (precondition), so it is a live node.
        let (prev, next) = unsafe {
            let node_ref = node.as_ref();
            (node_ref.prev, node_ref.next)
        };

        match prev {
            // SAFETY: `p` is a live node of this list (invariant 3/4), and we have `&mut self`.
            Some(mut p) => unsafe { p.as_mut().next = next },
            None => self.head = next,
        }

        match next {
            // SAFETY: `n` is a live node of this list (invariant 3/4), and we have `&mut self`.
            Some(mut n) => unsafe { n.as_mut().prev = prev },
            None => self.tail = prev,
        }

        self.len -= 1;

        // SAFETY: `node` was created by `Box::into_raw` in `Node::new_ptr`. Since it was linked
        // into this list, it has not been freed yet. Ownership is reclaimed here exactly once,
        // and the caller guarantees the pointer is not used afterwards.
        let Node { element, .. } = unsafe { *Box::from_raw(node.as_ptr()) };
        element
    }
}

// The cursor methods are the only place where the list is modified, which keeps the
// invariants in one place.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        let node = self.current?;
        // SAFETY: `node` is a live node of `self.list` (cursor invariant). We hold `&mut self`,
        // so no other reference into the list can exist while the returned `&mut T` is alive.
        Some(unsafe { &mut (*node.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `node` is a live node of `self.list` (cursor invariant), so reading its
            // `next` link is valid. From the back element this yields `None`, the ghost.
            Some(node) => unsafe { node.as_ref().next },
            // From the ghost we wrap around to the front (`None` again if the list is empty).
            None => self.list.head,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `node` is a live node of `self.list` (cursor invariant), so reading its
            // `prev` link is valid. From the front element this yields `None`, the ghost.
            Some(node) => unsafe { node.as_ref().prev },
            // From the ghost we wrap around to the back (`None` again if the list is empty).
            None => self.list.tail,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;

        // SAFETY: `node` is a live node linked into `self.list` (cursor invariant), so reading
        // its links is valid.
        let (prev, next) = unsafe {
            let node_ref = node.as_ref();
            (node_ref.prev, node_ref.next)
        };

        // Move the cursor off `node` *before* unlinking it, so it never refers to freed memory.
        // Prefer the next element (closer to the back), then the previous one, else the ghost.
        self.current = next.or(prev);

        // SAFETY: `node` is linked into `self.list` (cursor invariant), and it is unlinked and
        // freed exactly once here. The cursor no longer refers to it.
        Some(unsafe { self.list.unlink_node(node) })
    }

    /// Insert `element` directly after the current position. The cursor does not move.
    /// If the cursor is on the ghost, the element is inserted at the front of the list.
    pub fn insert_after(&mut self, element: T) {
        let node = Node::new_ptr(element);
        match self.current {
            Some(cur) => {
                // SAFETY: `cur` is a live node of `self.list` (cursor invariant).
                let next = unsafe { cur.as_ref().next };
                // SAFETY: `node` is a fresh, unlinked node. `cur` is in the list and `next` is
                // its successor, which satisfies the preconditions of `link_node`.
                unsafe { self.list.link_node(node, Some(cur), next) };
            }
            None => {
                let head = self.list.head;
                // SAFETY: `node` is a fresh, unlinked node. Inserting at the front means
                // `prev` is `None` and `next` is the current head, as `link_node` requires.
                unsafe { self.list.link_node(node, None, head) };
            }
        }
    }

    /// Insert `element` directly before the current position. The cursor does not move.
    /// If the cursor is on the ghost, the element is inserted at the back of the list.
    pub fn insert_before(&mut self, element: T) {
        let node = Node::new_ptr(element);
        match self.current {
            Some(cur) => {
                // SAFETY: `cur` is a live node of `self.list` (cursor invariant).
                let prev = unsafe { cur.as_ref().prev };
                // SAFETY: `node` is a fresh, unlinked node. `cur` is in the list and `prev` is
                // its predecessor, which satisfies the preconditions of `link_node`.
                unsafe { self.list.link_node(node, prev, Some(cur)) };
            }
            None => {
                let tail = self.list.tail;
                // SAFETY: `node` is a fresh, unlinked node. Inserting at the back means
                // `next` is `None` and `prev` is the current tail, as `link_node` requires.
                unsafe { self.list.link_node(node, tail, None) };
            }
        }
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.current?;
        // SAFETY: `node` is a live node of the list, which is immutably borrowed for `'a`.
        // It therefore cannot be freed or mutated while this iterator exists.
        let node_ref: &'a Node<T> = unsafe { node.as_ref() };
        self.current = node_ref.next;
        Some(&node_ref.element)
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
