/// The node must later be freed exactly once, e.g. via `Box::from_raw`.
fn allocate<T>(
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
) -> NonNull<Node<T>> {
    NonNull::from(Box::leak(Box::new(Node {
        element,
        prev,
        next,
    })))
