/// - `head` and `tail` are both `None` if and only if `len == 0`.
/// - Every node is a live heap allocation owned exclusively by the list.
/// - The `next` links form a chain from `head` to `tail`; `head.prev` and `tail.next` are `None`.
/// - For every pair of adjacent nodes `a`, `b`: `a.next == Some(b)` iff `b.prev == Some(a)`.
/// - `len` equals the number of nodes in the chain.
pub struct LinkedList<T> {
    head: Option<NonNull<Node<T>>>,
    tail: Option<NonNull<Node<T>>>,
    len: usize,
    marker: PhantomData<Box<Node<T>>>,
}

