/// Safety invariant: `current` is either `None` or points to a live node
/// owned by `list`.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Option<NonNull<Node<T>>>,
}

/// Safety invariant: `next` is either `None` or points to a live node of the
/// list borrowed for `'a`, so no mutation can happen while iterating.
pub struct Iter<'a, T> {
    next: Option<NonNull<Node<T>>>,
    marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
