    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is either `None` or a live node owned by the list
        // (cursor invariant). We hold `&mut self`, so no other reference to the
        // node's element can exist while the returned reference is alive.
        self.current
            .map(|node| unsafe { &mut (*node.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `node` is a live node of the list (cursor invariant),
            // so reading its `next` link is valid.
            Some(node) => unsafe { (*node.as_ptr()).next },
            // Ghost position: moving forward wraps around to the front.
            None => self.list.head,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `node` is a live node of the list (cursor invariant),
            // so reading its `prev` link is valid.
            Some(node) => unsafe { (*node.as_ptr()).prev },
            // Ghost position: moving backward wraps around to the back.
            None => self.list.tail,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;

        // SAFETY: `node` is a live node of the list (cursor invariant).
        let (prev, next) = unsafe { ((*node.as_ptr()).prev, (*node.as_ptr()).next) };

        // Unlink the node from its neighbors. We have exclusive access to the
        // list through `&mut self`, and `prev`/`next` are live neighbors
        // (list invariant).
        match prev {
            // SAFETY: `p` is a live node of the list.
            Some(p) => unsafe { (*p.as_ptr()).next = next },
            None => self.list.head = next,
        }
        match next {
            // SAFETY: `n` is a live node of the list.
            Some(n) => unsafe { (*n.as_ptr()).prev = prev },
            None => self.list.tail = prev,
        }
        self.list.len -= 1;

        // SAFETY: the node was allocated by `allocate` (via `Box::leak`) and is
        // now unlinked, so we uniquely own it. Turning it back into a `Box`
        // frees it exactly once after we move the element out.
        let boxed = unsafe { Box::from_raw(node.as_ptr()) };

        // Move to the neighbor closest to the back, preferring `next`.
        self.current = next.or(prev);
        Some(boxed.element)
    }

    pub fn insert_after(&mut self, element: T) {
        match self.current {
            Some(node) => {
                // SAFETY: `node` is a live node of the list (cursor invariant).
                let next = unsafe { (*node.as_ptr()).next };
                let new = allocate(element, Some(node), next);

                // SAFETY: `node` is live; we have exclusive access via `&mut self`.
                unsafe { (*node.as_ptr()).next = Some(new) };
                match next {
                    // SAFETY: `n` is a live node of the list.
                    Some(n) => unsafe { (*n.as_ptr()).prev = Some(new) },
                    None => self.list.tail = Some(new),
                }
                self.list.len += 1;
            }
            None => {
                // Ghost position: insert at the front of the list.
                let old_head = self.list.head;
                let new = allocate(element, None, old_head);
                match old_head {
                    // SAFETY: `h` is a live node of the list.
                    Some(h) => unsafe { (*h.as_ptr()).prev = Some(new) },
                    None => self.list.tail = Some(new),
                }
                self.list.head = Some(new);
                self.list.len += 1;
            }
        }
    }

    pub fn insert_before(&mut self, element: T) {
        match self.current {
            Some(node) => {
                // SAFETY: `node` is a live node of the list (cursor invariant).
                let prev = unsafe { (*node.as_ptr()).prev };
                let new = allocate(element, prev, Some(node));

                // SAFETY: `node` is live; we have exclusive access via `&mut self`.
                unsafe { (*node.as_ptr()).prev = Some(new) };
                match prev {
                    // SAFETY: `p` is a live node of the list.
                    Some(p) => unsafe { (*p.as_ptr()).next = Some(new) },
                    None => self.list.head = Some(new),
                }
                self.list.len += 1;
            }
            None => {
                // Ghost position: insert at the back of the list.
                let old_tail = self.list.tail;
                let new = allocate(element, old_tail, None);
                match old_tail {
                    // SAFETY: `t` is a live node of the list.
                    Some(t) => unsafe { (*t.as_ptr()).next = Some(new) },
                    None => self.list.head = Some(new),
                }
                self.list.tail = Some(new);
                self.list.len += 1;
            }
        }
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: `node` is a live node of the list, which is immutably borrowed
        // for `'a` (iterator invariant), so shared references to it are valid
        // for `'a`.
        unsafe {
            let node_ref = &*node.as_ptr();
            self.next = node_ref.next;
            Some(&node_ref.element)
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut current = self.head.take();
        while let Some(node) = current {
            // SAFETY: every node was allocated by `allocate` and is owned
            // exclusively by the list. Each node is visited once along the chain
            // and freed exactly once. We read `next` before the box is dropped.
            let boxed = unsafe { Box::from_raw(node.as_ptr()) };
            current = boxed.next;
        }
        self.tail = None;
        self.len = 0;
    }
}

// SAFETY: the list owns its nodes like a `Box<Node<T>>` would, so it can be
// sent to another thread whenever `T` can be sent.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: shared access only yields `&T`, so sharing the list is safe whenever
// `T` can be shared.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: the cursor behaves like `&mut LinkedList<T>`, so it is `Send` when
// `T: Send` and `Sync` when `T: Sync`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
// SAFETY: see above.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: the iterator behaves like `&LinkedList<T>`, so it is `Send` and
// `Sync` when `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
// SAFETY: see above.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}
