I'll implement the full doubly linked list in `src/lib.rs`, covering the node structure, cursor-based mutation, front/back push/pop via the cursor, `len`/`is_empty`, iteration, `Drop`, covariance, and `Send`/`Sync`. The `pre_implemented` module is referenced by `mod pre_implemented;`, so I keep that declaration unchanged. The `Iter` and `Cursor` types need to carry raw node pointers and lifetimes, so I restructure them accordingly while keeping the public names.

Key design points:
- `LinkedList<T>` holds `head`, `tail`, `len`, and a `PhantomData<Box<Node<T>>>` for covariance and correct drop-check.
- `Cursor` holds a `&mut LinkedList<T>` and an `Option<NonNull<Node<T>>>` current position (`None` means the "ghost" position past the back, which allows insertion into empty lists and at the ends).
- `Iter` holds front/back-agnostic raw pointers and a remaining count.
- Every `unsafe` block carries a justification comment.

```rust
// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

pub struct LinkedList<T> {
    head: Option<NonNull<Node<T>>>,
    tail: Option<NonNull<Node<T>>>,
    len: usize,
    // Marks that the list logically owns `Box<Node<T>>` values: this gives
    // covariance over `T` and makes the drop checker treat the list as owning `T`.
    marker: PhantomData<Box<Node<T>>>,
}

// Safety: the list owns all of its nodes uniquely, so sending it to another
// thread is sound whenever the elements themselves are `Send`.
unsafe impl<T: Send> Send for LinkedList<T> {}
// Safety: shared references only permit reading through `&self` (iteration),
// which is sound whenever the elements are `Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    // `None` is the "ghost" position between the back and the front of the list.
    // Otherwise, it points to a node that is owned by `list`.
    current: Option<NonNull<Node<T>>>,
}

pub struct Iter<'a, T> {
    front: Option<NonNull<Node<T>>>,
    remaining: usize,
    marker: PhantomData<&'a Node<T>>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.head;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.tail;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            front: self.head,
            remaining: self.len,
            marker: PhantomData,
        }
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // Safety: `current`, when `Some`, points to a live node owned by `self.list`,
        // and we hold `&mut self`, so no other reference to it can exist.
        unsafe { self.current.map(|node| &mut (*node.as_ptr()).element) }
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        // Safety: `current` is either `None` or a live node owned by the list.
        self.current = match self.current {
            Some(node) => unsafe { (*node.as_ptr()).next },
            None => self.list.head,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        // Safety: `current` is either `None` or a live node owned by the list.
        self.current = match self.current {
            Some(node) => unsafe { (*node.as_ptr()).prev },
            None => self.list.tail,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;
        // Safety: `node` is a live node owned by the list. We unlink it, fix up
        // the neighbours' pointers and head/tail, then reconstruct the box exactly
        // once from the raw pointer, which is no longer reachable from the list.
        unsafe {
            let prev = (*node.as_ptr()).prev;
            let next = (*node.as_ptr()).next;

            match prev {
                Some(p) => (*p.as_ptr()).next = next,
                None => self.list.head = next,
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = prev,
                None => self.list.tail = prev,
            }

            self.list.len -= 1;
            // Move the cursor to the neighbour closest to the back.
            self.current = if next.is_some() { next } else { prev };

            let boxed = Box::from_raw(node.as_ptr());
            Some(boxed.element)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let new_node = Box::into_raw(Box::new(Node {
            element,
            prev: None,
            next: None,
        }));
        // Safety: `new_node` was just created and is uniquely owned here. Every
        // pointer we dereference is either a live node owned by the list or is
        // the freshly allocated node. Head/tail are updated to keep the list consistent.
        unsafe {
            let new = NonNull::new_unchecked(new_node);
            match self.current {
                Some(cur) => {
                    let next = (*cur.as_ptr()).next;
                    (*new.as_ptr()).prev = Some(cur);
                    (*new.as_ptr()).next = next;
                    (*cur.as_ptr()).next = Some(new);
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(new),
                        None => self.list.tail = Some(new),
                    }
                }
                None => {
                    // Ghost position: insert at the front of the list.
                    let old_head = self.list.head;
                    (*new.as_ptr()).next = old_head;
                    match old_head {
                        Some(h) => (*h.as_ptr()).prev = Some(new),
                        None => self.list.tail = Some(new),
                    }
                    self.list.head = Some(new);
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new_node = Box::into_raw(Box::new(Node {
            element,
            prev: None,
            next: None,
        }));
        // Safety: same reasoning as `insert_after`.
        unsafe {
            let new = NonNull::new_unchecked(new_node);
            match self.current {
                Some(cur) => {
                    let prev = (*cur.as_ptr()).prev;
                    (*new.as_ptr()).next = Some(cur);
                    (*new.as_ptr()).prev = prev;
                    (*cur.as_ptr()).prev = Some(new);
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(new),
                        None => self.list.head = Some(new),
                    }
                }
                None => {
                    // Ghost position: insert at the back of the list.
                    let old_tail = self.list.tail;
                    (*new.as_ptr()).prev = old_tail;
                    match old_tail {
                        Some(t) => (*t.as_ptr()).next = Some(new),
                        None => self.list.head = Some(new),
                    }
                    self.list.tail = Some(new);
                }
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        if self.remaining == 0 {
            return None;
        }
        let node = self.front?;
        // Safety: `front` is a live node of the list borrowed for `'a` via `&LinkedList`,
        // so shared references to it are valid for `'a`. `remaining` ensures we never
        // walk past the tail.
        unsafe {
            let node_ref: &'a Node<T> = &*node.as_ptr();
            self.front = node_ref.next;
            self.remaining -= 1;
            Some(&node_ref.element)
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut current = self.head;
        while let Some(node) = current {
            // Safety: each node was allocated via `Box::into_raw` and is visited
            // exactly once while walking the owned chain, so reconstructing the box
            // here is sound and frees it exactly once.
            unsafe {
                let boxed = Box::from_raw(node.as_ptr());
                current = boxed.next;
            }
        }
        self.head = None;
        self.tail = None;
        self.len = 0;
    }
}
