#include "perfect_numbers.h"

#include <stdexcept>

namespace perfect_numbers {

namespace {

// Sum of all proper divisors of number (divisors excluding number itself).
long long aliquot_sum(int number) {
    const long long n = number;
    long long sum = 0;
    for (long long i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            const long long other = n / i;
            if (i != n) {
                sum += i;
            }
            if (other != i && other != n) {
                sum += other;
            }
        }
    }
    return sum;
}

}  // namespace

classification classify(int number) {
    if (number < 1) {
        throw std::domain_error(
            "Classification is only possible for positive integers.");
    }

    const long long sum = aliquot_sum(number);

    if (sum == number) {
        return classification::perfect;
    }
    if (sum > number) {
        return classification::abundant;
    }
    return classification::deficient;
}

}  // namespace perfect_numbers
