namespace perfect_numbers {

namespace {

// Sum of all proper divisors of n (excluding n itself).
long long aliquot_sum(long long n) {
    if (n == 1) {
        return 0;
    }

    long long sum = 1;  // 1 is always a proper divisor for n > 1
    for (long long i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            sum += i;
            long long other = n / i;
            if (other != i) {
                sum += other;
            }
        }
    }
    return sum;
}

}  // namespace

classification classify(int number) {
    if (number <= 0) {
        throw std::domain_error("Classification is only possible for positive integers");
    }

    long long sum = aliquot_sum(number);

    if (sum == number) {
        return classification::perfect;
    }
    if (sum > number) {
        return classification::abundant;
    }
    return classification::deficient;
}

}  // namespace perfect_numbers
