#include "perfect_numbers.h"

#include <stdexcept>

namespace perfect_numbers {

namespace {

// Returns the sum of the proper divisors of n (all divisors except n itself).
// Divisors come in pairs (i, n / i), so only candidates up to sqrt(n) are checked.
long long aliquot_sum(long long n) {
    long long sum = 0;
    for (long long i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            const long long partner = n / i;
            // Count each divisor once, and never count n itself.
            if (i != n) {
                sum += i;
            }
            if (partner != i && partner != n) {
                sum += partner;
            }
        }
    }
    return sum;
}

}  // namespace

classification classify(int number) {
    if (number <= 0) {
        throw std::domain_error("Classification is only possible for positive integers.");
    }

    const long long n = number;
    const long long sum = aliquot_sum(n);

    if (sum == n) {
        return classification::perfect;
    }
    if (sum > n) {
        return classification::abundant;
    }
    return classification::deficient;
}

}  // namespace perfect_numbers
