#define BANK_ACCOUNT_H

#include <mutex>
#include <stdexcept>

namespace Bankaccount {

// A bank account that can be used safely from multiple threads at once.
//
// Every operation holds the account's mutex for its entire duration, so a
// check followed by an update (such as verifying funds before a withdrawal)
// cannot interleave with another operation on the same account.
//
// Operations that cannot be performed throw std::runtime_error: opening an
// account that is already open, using an account that is not open (never
// opened or already closed), passing a negative amount, overdrawing the
// account, or depositing an amount that would overflow the balance.
class Bankaccount {
 public:
  Bankaccount() = default;

  // Copying would create a second, unrelated balance, so copies are disabled.
  Bankaccount(const Bankaccount&) = delete;
  Bankaccount& operator=(const Bankaccount&) = delete;

  // Opens the account with a zero balance.
  void open();

  // Closes the account and discards any remaining balance.
  void close();

  // Returns the current balance.
  long long balance() const;

  // Adds amount to the balance.
  void deposit(long long amount);

  // Subtracts amount from the balance.
  void withdraw(long long amount);

 private:
  mutable std::mutex mutex_;  // Guards open_ and balance_.
  bool open_ = false;
  long long balance_ = 0;
};

}  // namespace Bankaccount

#endif  // BANK_ACCOUNT_H
