package trinary

import "math"

// ParseTrinary converts a trinary number, given as a string of the digits
// '0', '1' and '2' (e.g. "102012"), to its decimal equivalent.
//
// The value is accumulated from left to right using value = value*3 + digit,
// which is equivalent to summing digit * 3^position for each place.
//
// Invalid input yields 0 and false. That covers the empty string, any
// character other than '0', '1' or '2', and values too large for an int64.
func ParseTrinary(arg string) (want int64, ok bool) {
	if len(arg) == 0 {
		return 0, false
	}

	var value int64
	for i := 0; i < len(arg); i++ {
		digit := int64(arg[i]) - '0'
		if digit < 0 || digit > 2 {
			return 0, false
		}

		// Stop before value*3 + digit can exceed the largest int64.
		if value > (math.MaxInt64-digit)/3 {
			return 0, false
		}

		value = value*3 + digit
	}

	return value, true
}
