package beer

import (
	"errors"
	"fmt"
	"strings"
)

// bottles returns the phrase "N bottle(s) of beer" with correct pluralization.
func bottles(n int) string {
	switch n {
	case 0:
		return "no more bottles of beer"
	case 1:
		return "1 bottle of beer"
	default:
		return fmt.Sprintf("%d bottles of beer", n)
	}
}

// Song returns the full lyrics of the 99 Bottles of Beer song.
func Song() string {
	verses, err := Verses(99, 0)
	if err != nil {
		panic(err)
	}
	return verses
}

// Verses returns the verses from start down to stop, inclusive, separated by blank lines.
func Verses(start, stop int) (string, error) {
	if start < stop || start > 99 || stop < 0 {
		return "", errors.New("invalid verse range")
	}

	parts := make([]string, 0, start-stop+1)
	for i := start; i >= stop; i-- {
		v, err := Verse(i)
		if err != nil {
			return "", err
		}
		parts = append(parts, v)
	}
	return strings.Join(parts, "\n"), nil
}

// Verse returns the lyrics for a single verse n.
func Verse(n int) (string, error) {
	if n < 0 || n > 99 {
		return "", errors.New("verse out of range")
	}

	switch n {
	case 0:
		return "No more bottles of beer on the wall, no more bottles of beer.\n" +
			"Go to the store and buy some more, 99 bottles of beer on the wall.\n", nil
	case 1:
		return "1 bottle of beer on the wall, 1 bottle of beer.\n" +
			"Take it down and pass it around, no more bottles of beer on the wall.\n", nil
	default:
		return fmt.Sprintf("%s on the wall, %s.\n", capitalize(bottles(n)), bottles(n)) +
			fmt.Sprintf("Take one down and pass it around, %s on the wall.\n", bottles(n-1)), nil
	}
}

// capitalize upper-cases the first letter of s.
func capitalize(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}
