package beer

import (
	"errors"
	"fmt"
	"strings"
)

// bottles describes a count of bottles in the lowercase phrase used mid-line.
func bottles(n int) string {
	switch n {
	case 0:
		return "no more bottles"
	case 1:
		return "1 bottle"
	default:
		return fmt.Sprintf("%d bottles", n)
	}
}

// Song returns the complete 99 Bottles of Beer song.
func Song() string {
	song, _ := Verses(99, 0)
	return song
}

// Verses returns verses from start down to stop, inclusive, separated by a blank line.
func Verses(start, stop int) (string, error) {
	if start < stop {
		return "", errors.New("start must be greater than or equal to stop")
	}

	verses := make([]string, 0, start-stop+1)
	for n := start; n >= stop; n-- {
		verse, err := Verse(n)
		if err != nil {
			return "", err
		}
		verses = append(verses, verse)
	}

	return strings.Join(verses, "\n"), nil
}

// Verse returns a single verse for n bottles of beer.
func Verse(n int) (string, error) {
	if n < 0 || n > 99 {
		return "", errors.New("verse number must be between 0 and 99")
	}

	if n == 0 {
		return "No more bottles of beer on the wall, no more bottles of beer.\n" +
			"Go to the store and buy some more, 99 bottles of beer on the wall.\n", nil
	}

	take := "Take one down"
	if n == 1 {
		take = "Take it down"
	}

	current := bottles(n)
	next := bottles(n - 1)

	return fmt.Sprintf("%s of beer on the wall, %s of beer.\n%s and pass it around, %s of beer on the wall.\n",
		strings.ToUpper(current[:1])+current[1:], current, take, next), nil
}
