		}
		parts = append(parts, v)
	}
	return strings.Join(parts, "\n"), nil
}

func Verse(n int) (string, error) {
	if n < 0 || n > 99 {
		return "", errors.New("verse out of range")
	}

	if n == 0 {
		return "No more bottles of beer on the wall, no more bottles of beer.\n" +
			"Go to the store and buy some more, 99 bottles of beer on the wall.\n", nil
	}

	var action, remaining string
	if n == 1 {
		action = "Take it down and pass it around"
	} else {
		action = "Take one down and pass it around"
	}
	remaining = bottles(n - 1)

	first := capitalize(bottles(n)) + " of beer on the wall, " + bottles(n) + " of beer.\n"
	second := action + ", " + remaining + " of beer on the wall.\n"
	return first + second, nil
}

func capitalize(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
