	line1 := fmt.Sprintf("%s on the wall, %s.", capitalize(bottles(n)), bottles(n))
	line2 := fmt.Sprintf("%s, %s on the wall.", action(n), bottles(next))
	return line1 + "\n" + line2 + "\n"
