namespace queen_attack {

// A square on the chessboard. Both row and column are zero-indexed and
// must be in the range 0 to 7 inclusive.
struct position {
    int row;
    int column;
};

// Returns true if queens placed on `white` and `black` can attack each other,
// i.e. they share a row, a column, or a diagonal.
//
// Throws std::domain_error if either position is not on the board, or if both
