#include "queen_attack.h"

#include <cstdlib>
#include <stdexcept>

namespace queen_attack {

namespace {

constexpr int board_size = 8;

void validate(const position& square) {
    if (square.row < 0 || square.row >= board_size) {
        throw std::domain_error("row not on board");
    }
    if (square.column < 0 || square.column >= board_size) {
        throw std::domain_error("column not on board");
    }
}

}  // namespace

bool can_attack(position white, position black) {
    validate(white);
    validate(black);

    if (white.row == black.row && white.column == black.column) {
        throw std::domain_error("queens must be placed on different squares");
    }

    const bool same_row = white.row == black.row;
    const bool same_column = white.column == black.column;
    const bool same_diagonal =
        std::abs(white.row - black.row) == std::abs(white.column - black.column);

    return same_row || same_column || same_diagonal;
}

}  // namespace queen_attack
```

