void Bankaccount::deposit(long amount) {
    std::lock_guard<std::mutex> lock(mutex_);
    check_open_locked();
    if (amount < 0) {
        throw std::runtime_error("deposit amount must not be negative");
    }
    balance_ += amount;
}

void Bankaccount::withdraw(long amount) {
    std::lock_guard<std::mutex> lock(mutex_);
    check_open_locked();
    if (amount < 0) {
        throw std::runtime_error("withdrawal amount must not be negative");
    }
    if (amount > balance_) {
        throw std::runtime_error("insufficient funds");
    }
    balance_ -= amount;
}

