#if !defined(BANK_ACCOUNT_H)
#define BANK_ACCOUNT_H

#include <mutex>
#include <stdexcept>

namespace Bankaccount {

// Thrown when an operation is not allowed (wrong account state, invalid
// amount, insufficient funds, ...).
struct bank_account_error : std::runtime_error {
  using std::runtime_error::runtime_error;
};

// A bank account that can be safely used from multiple threads concurrently.
//
// Every operation holds the account's mutex for its entire duration, so each
// check-then-act sequence (e.g. "is there enough money?" followed by
// "subtract it") is atomic. Concurrent calls are serialized and can never
// observe or produce an inconsistent balance.
class Bankaccount {  // class Bankaccount
 public:
  Bankaccount() = default;

  // An account owns a mutex and represents unique state, so it cannot be
  // copied or moved.
  Bankaccount(const Bankaccount&) = delete;
  Bankaccount& operator=(const Bankaccount&) = delete;
  Bankaccount(Bankaccount&&) = delete;
  Bankaccount& operator=(Bankaccount&&) = delete;

  // Opens the account with a zero balance.
  // Throws bank_account_error if the account is already open.
  void open();

  // Closes the account. Any remaining funds are paid out, so the balance is
  // zero and a later re-opening starts from scratch.
  // Throws bank_account_error if the account is not open.
  void close();

  // Returns the current balance.
  // Throws bank_account_error if the account is not open.
  long balance() const;

  // Adds amount (which must be positive) to the balance.
  // Throws bank_account_error if the account is not open, the amount is not
  // positive, or the balance would overflow.
  void deposit(long amount);

  // Removes amount (which must be positive) from the balance.
  // Throws bank_account_error if the account is not open, the amount is not
  // positive, or the balance is insufficient.
  void withdraw(long amount);

 private:
  // mutable so that const member functions can lock it.
  mutable std::mutex mutex_;
  bool is_open_{false};
  long balance_{0};
};

}  // namespace Bankaccount

#endif  // BANK_ACCOUNT_H
