    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];

const FLAT_NOTES: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

// Tonics whose scales are spelled with flats (case-insensitive name match,
// with the accidental included).
const FLAT_TONICS: [&str; 10] = [
    "F", "Bb", "Eb", "Ab", "Db", "Gb", "d", "g", "c", "f",
];

fn uses_flats(tonic: &str) -> bool {
    FLAT_TONICS.iter().any(|t| *t == tonic) || tonic.ends_with('b') && tonic.len() == 2
}

fn normalize(tonic: &str) -> Option<String> {
    let mut chars = tonic.chars();
    let letter = chars.next()?.to_ascii_uppercase();
    let rest: String = chars.collect();
    match rest.as_str() {
        "" => Some(letter.to_string()),
        "#" | "b" => Some(format!("{letter}{rest}")),
        _ => None,
    }
}

fn index_of(note: &str, flats: bool) -> Option<usize> {
    let table = if flats { &FLAT_NOTES } else { &SHARP_NOTES };
    table.iter().position(|n| *n == note).or_else(|| {
        // Accept the enharmonic spelling as well.
        let alt = if flats { &SHARP_NOTES } else { &FLAT_NOTES };
        alt.iter().position(|n| *n == note)
    })
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let norm = normalize(tonic).ok_or(Error)?;
        let flats = uses_flats(tonic) || norm.ends_with('b');
        let table = if flats { &FLAT_NOTES } else { &SHARP_NOTES };
        let start = index_of(&norm, flats).ok_or(Error)?;

        let mut notes = Vec::new();
        let mut idx = start;
        notes.push(table[idx].to_string());
        for c in intervals.chars() {
            let step = match c {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                _ => return Err(Error),
            };
            idx = (idx + step) % 12;
            notes.push(table[idx].to_string());
        }
        // The final interval returns to the tonic; drop it from the output.
        if notes.len() > 1 {
            notes.pop();
        }
        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        let norm = normalize(tonic).ok_or(Error)?;
        let flats = uses_flats(tonic) || norm.ends_with('b');
        let table = if flats { &FLAT_NOTES } else { &SHARP_NOTES };
        let start = index_of(&norm, flats).ok_or(Error)?;
        let notes = (0..12).map(|i| table[(start + i) % 12].to_string()).collect();
        Ok(Scale { notes })
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
