//! Generates musical scales from a tonic and a pattern of intervals.
//!
//! Errors are reported through the [`Error`] enum so that downstream code can
//! react appropriately to invalid input.

/// Errors that can occur when constructing a [`Scale`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Error {
    /// The tonic is not a valid note name such as `C`, `Bb`, or `f#`.
    InvalidTonic(String),
    /// An interval is not one of `m` (minor second), `M` (major second),
    /// or `A` (augmented second).
    InvalidInterval(char),
}

/// Note names using sharps, indexed by pitch class (0 = C).
const SHARP_NAMES: [&str; 12] = [
    "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B",
];

/// Note names using flats, indexed by pitch class (0 = C).
const FLAT_NAMES: [&str; 12] = [
    "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B",
];

/// Number of semitones in each supported interval.
const MINOR_SECOND: usize = 1;
const MAJOR_SECOND: usize = 2;
const AUGMENTED_SECOND: usize = 3;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Scale {
    notes: Vec<String>,
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let (start, uses_flats) = parse_tonic(tonic)?;
        let steps = parse_intervals(intervals)?;
        let names = if uses_flats { &FLAT_NAMES } else { &SHARP_NAMES };

        let mut position = start;
        let mut notes = vec![names[position].to_string()];

        // The final interval leads back to the octave of the tonic, which is
        // not included in the scale.
        for &step in steps.iter().take(steps.len().saturating_sub(1)) {
            position = (position + step) % 12;
            notes.push(names[position].to_string());
        }

        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, &"m".repeat(12))
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}

/// Parses a tonic such as `C`, `Bb`, `f#`, or `bb`.
///
/// Returns the pitch class (0 = C) and whether the scale should be spelled
/// with flats (`true`) or sharps (`false`).
fn parse_tonic(tonic: &str) -> Result<(usize, bool), Error> {
    let invalid = || Error::InvalidTonic(tonic.to_string());

    let chars: Vec<char> = tonic.chars().collect();
    let (letter, accidental) = match chars.as_slice() {
        [letter] => (*letter, None),
        [letter, accidental] => (*letter, Some(*accidental)),
        _ => return Err(invalid()),
    };

    let natural: i32 = match letter.to_ascii_uppercase() {
        'C' => 0,
        'D' => 2,
        'E' => 4,
        'F' => 5,
        'G' => 7,
        'A' => 9,
        'B' => 11,
        _ => return Err(invalid()),
    };

    // Lowercase letters denote minor tonics.
    let minor = letter.is_ascii_lowercase();

    let (offset, uses_flats): (i32, bool) = match accidental {
        None => {
            // Naturals use flats only for F major and c, d, f, g minor.
            let flats = if minor {
                matches!(letter, 'c' | 'd' | 'f' | 'g')
            } else {
                letter == 'F'
            };
            (0, flats)
        }
        Some('#') => (1, false),
        Some('b') => (-1, true),
        Some(_) => return Err(invalid()),
    };

    let pitch_class = (natural + offset).rem_euclid(12) as usize;
    Ok((pitch_class, uses_flats))
}

/// Converts an interval pattern such as `MMmMMMm` into semitone steps.
fn parse_intervals(intervals: &str) -> Result<Vec<usize>, Error> {
    intervals
        .chars()
        .map(|c| match c {
            'm' => Ok(MINOR_SECOND),
            'M' => Ok(MAJOR_SECOND),
            'A' => Ok(AUGMENTED_SECOND),
            other => Err(Error::InvalidInterval(other)),
        })
        .collect()
}
