// which does more or less the same thing but automatically.
#[derive(Debug)]
pub struct Error;

#[derive(Debug)]
pub struct Scale {
    notes: Vec<String>,
}

const LETTERS: [char; 7] = ['C', 'D', 'E', 'F', 'G', 'A', 'B'];
// Semitone offset of each natural letter from C.
const LETTER_PITCH: [i32; 7] = [0, 2, 4, 5, 7, 9, 11];

// Returns true if the tonic should be spelled with sharps.
fn uses_sharps(tonic: &str) -> bool {
    matches!(
        tonic,
        "C" | "G" | "D" | "A" | "E" | "B" | "F#"
            | "a" | "e" | "b" | "f#" | "c#" | "g#" | "d#"
    )
}

// Parse a note name like "C", "F#", "Bb" into (letter index, accidental).
fn parse_note(tonic: &str) -> Result<(usize, i32), Error> {
    let mut chars = tonic.chars();
    let letter = chars.next().ok_or(Error)?.to_ascii_uppercase();
    let letter_idx = LETTERS.iter().position(|&l| l == letter).ok_or(Error)?;
    let mut accidental = 0;
    for c in chars {
        match c {
            '#' => accidental += 1,
            'b' => accidental -= 1,
            _ => return Err(Error),
        }
    }
    Ok((letter_idx, accidental))
}

fn pitch_class(letter_idx: usize, accidental: i32) -> i32 {
    (LETTER_PITCH[letter_idx] + accidental).rem_euclid(12)
}

fn spell(letter_idx: usize, pc: i32, sharps: bool) -> String {
    let letter = LETTERS[letter_idx];
    let natural = LETTER_PITCH[letter_idx];
    let mut diff = (pc - natural).rem_euclid(12);
    if diff > 6 {
        diff -= 12;
    }
    let accidental = match diff {
        0 => String::new(),
        1 => "#".to_string(),
        -1 => "b".to_string(),
        2 => "##".to_string(),
        -2 => "bb".to_string(),
        _ => String::new(),
    };
    let _ = sharps;
    format!("{letter}{accidental}")
}

// Spell a pitch class for the chromatic scale, respecting the sharp/flat style.
fn chromatic_name(pc: i32, sharps: bool) -> String {
    const SHARP_NAMES: [&str; 12] = [
        "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B",
    ];
    const FLAT_NAMES: [&str; 12] = [
        "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B",
    ];
    if sharps {
        SHARP_NAMES[pc as usize].to_string()
    } else {
        FLAT_NAMES[pc as usize].to_string()
    }
