impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let (start_letter, start_acc) = parse_note(tonic)?;
        let sharps = uses_sharps(tonic);
        let mut letter_idx = start_letter;
        let mut pc = pitch_class(start_letter, start_acc);
        let mut notes = Vec::new();

        notes.push(spell(letter_idx, pc, sharps));
        for step in intervals.chars() {
            let (letter_steps, semitones) = match step {
                'm' => (1, 1),
                'M' => (1, 2),
                'A' => (2, 3),
                _ => return Err(Error),
            };
            letter_idx = (letter_idx + letter_steps) % 7;
            pc = (pc + semitones) % 12;
            notes.push(spell(letter_idx, pc, sharps));
        }
        // The final interval returns to the tonic; drop the duplicate octave
        // note only if the pattern closes on the tonic.
        if notes.len() > 1 && notes.last() == notes.first() {
            notes.pop();
        }
        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        let (letter_idx, accidental) = parse_note(tonic)?;
        let sharps = uses_sharps(tonic);
        let start = pitch_class(letter_idx, accidental);
        let notes = (0..12)
            .map(|i| chromatic_name((start + i) % 12, sharps))
            .collect();
        Ok(Scale { notes })
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
