/// Returns the index (0..12) of a note name within the chromatic scale.
/// Index 0 is A.
fn note_index(name: &str) -> Option<usize> {
    let mut chars = name.chars();
    let letter = chars.next()?.to_ascii_uppercase();
    let accidental = chars.next();
    let base: i32 = match letter {
        'A' => 0,
        'B' => 2,
        'C' => 3,
        'D' => 5,
        'E' => 7,
        'F' => 8,
        'G' => 10,
        _ => return None,
    };
    let offset: i32 = match accidental {
        None => 0,
        Some('#') => 1,
        Some('b') => -1,
        Some(_) => return None,
    };
    if chars.next().is_some() {
        return None;
    }
    Some((base + offset).rem_euclid(12) as usize)
}

