/// Normalizes a tonic so the note letter is uppercase, preserving any accidental.
fn normalize_tonic(tonic: &str) -> String {
    let mut chars = tonic.chars();
    match chars.next() {
        Some(first) => {
            let mut s = String::new();
            s.push(first.to_ascii_uppercase());
            s.extend(chars);
            s
        }
        None => String::new(),
    }
