#if !defined(PERFECT_NUMBERS_H)
#define PERFECT_NUMBERS_H

#include <stdexcept>

namespace perfect_numbers {

// Nicomachus' classification of natural numbers, based on the aliquot sum
// (the sum of a number's divisors, excluding the number itself).
enum class classification {
    deficient,  // aliquot sum is less than the number, e.g. 8 (1 + 2 + 4 = 7)
    perfect,    // aliquot sum equals the number, e.g. 6 (1 + 2 + 3 = 6)
    abundant    // aliquot sum is greater than the number, e.g. 12 (16)
};

// Classifies a natural number (1, 2, 3, ...).
// Throws std::domain_error if number is not a natural number (number < 1).
classification classify(int number);

}  // namespace perfect_numbers

#endif  // PERFECT_NUMBERS_H
