#include "perfect_numbers.h"

#include <cstdint>
#include <stdexcept>

namespace perfect_numbers {

namespace {

// Returns the aliquot sum of n: the sum of all divisors of n except n itself.
// Requires n >= 1.
std::int64_t aliquot_sum(std::int64_t n) {
    // 1 is a proper divisor of every n > 1; it has no proper divisors itself.
    std::int64_t sum = (n > 1) ? 1 : 0;

    // Divisors pair up as (i, n / i), so it is enough to search up to sqrt(n).
    for (std::int64_t i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            const std::int64_t partner = n / i;
            sum += i;
            if (partner != i) {  // a square root is only counted once
                sum += partner;
            }
        }
    }

    return sum;
}

}  // namespace

classification classify(int number) {
    if (number < 1) {
        throw std::domain_error(
            "Classification is only possible for natural numbers.");
    }

    const std::int64_t sum = aliquot_sum(number);
    if (sum == number) {
        return classification::perfect;
    }
    return (sum > number) ? classification::abundant : classification::deficient;
}

}  // namespace perfect_numbers
```

