package wordy

import (
	"strconv"
	"strings"
)

// operation applies a binary operator. It reports false if the operation
// cannot be performed (e.g. division by zero).
type operation func(a, b int) (int, bool)

// Answer evaluates a simple math word problem such as "What is 5 plus 13?".
// Operations are evaluated strictly from left to right, ignoring the usual
// order of operations. It returns the result and true on success, or 0 and
// false if the question is unsupported or malformed.
func Answer(question string) (int, bool) {
	words := strings.Fields(question)
	if len(words) < 3 || words[0] != "What" || words[1] != "is" {
		return 0, false
	}

	// The question must end with "?", which is not part of the expression.
	last := len(words) - 1
	if !strings.HasSuffix(words[last], "?") {
		return 0, false
	}
	words[last] = strings.TrimSuffix(words[last], "?")
	if words[last] == "" {
		words = words[:last]
	}

	expr := words[2:]
	if len(expr) == 0 {
		return 0, false
	}

	result, err := strconv.Atoi(expr[0])
	if err != nil {
		return 0, false
	}

	i := 1
	for i < len(expr) {
		op, width, valid := parseOperator(expr[i:])
		if !valid {
			return 0, false
		}
		i += width

		if i >= len(expr) {
			return 0, false // operator with no right-hand operand
		}
		operand, err := strconv.Atoi(expr[i])
		if err != nil {
			return 0, false
		}

		result, valid = op(result, operand)
		if !valid {
			return 0, false
		}
		i++
	}

	return result, true
}

// parseOperator reads the operator at the start of words. It returns the
// operation, the number of words the operator spans, and whether the
// operator is supported.
func parseOperator(words []string) (operation, int, bool) {
	switch words[0] {
	case "plus":
		return add, 1, true
	case "minus":
		return subtract, 1, true
	case "multiplied":
		if len(words) > 1 && words[1] == "by" {
			return multiply, 2, true
		}
	case "divided":
		if len(words) > 1 && words[1] == "by" {
			return divide, 2, true
		}
	}
	return nil, 0, false
}

func add(a, b int) (int, bool) {
	return a + b, true
}

func subtract(a, b int) (int, bool) {
	return a - b, true
}

func multiply(a, b int) (int, bool) {
	return a * b, true
}

func divide(a, b int) (int, bool) {
	if b == 0 {
		return 0, false
	}
	return a / b, true
}
