wordy.go
```
// Package wordy evaluates simple arithmetic word problems such as
// "What is 5 plus 13 minus 2?".
package wordy

import (
	"math"
	"strconv"
	"strings"
)

// operation applies a binary operator to a and b. The boolean result is false
// if the result cannot be represented as an int (overflow or division by zero).
type operation func(a, b int) (int, bool)

// Answer evaluates the word problem in question and returns its integer result.
// The boolean is false if the question is not a well-formed math problem, uses
// an unsupported operation, or has a result that cannot be computed as an int.
//
// Operations are evaluated strictly from left to right, ignoring the usual
// order of operations, so "What is 3 plus 2 multiplied by 3?" is 15.
func Answer(question string) (int, bool) {
	words, ok := splitQuestion(question)
	if !ok || len(words) == 0 {
		return 0, false
	}

	result, ok := parseNumber(words[0])
	if !ok {
		return 0, false
	}

	// Each operation must be followed by exactly one operand.
	for rest := words[1:]; len(rest) > 0; {
		op, consumed, ok := parseOperation(rest)
		if !ok {
			return 0, false
		}
		rest = rest[consumed:]

		if len(rest) == 0 {
			return 0, false // operation is missing its operand
		}
		operand, ok := parseNumber(rest[0])
		if !ok {
			return 0, false
		}
		rest = rest[1:]

		result, ok = op(result, operand)
		if !ok {
			return 0, false
		}
	}

	return result, true
}

// splitQuestion checks the "What is ... ?" framing of a question and returns
// the words between "what is" and the question mark.
func splitQuestion(question string) ([]string, bool) {
	question = strings.ToLower(strings.TrimSpace(question))
	if !strings.HasSuffix(question, "?") {
		return nil, false
	}

	words := strings.Fields(strings.TrimSuffix(question, "?"))
	if len(words) < 2 || words[0] != "what" || words[1] != "is" {
		return nil, false
	}

	return words[2:], true
}

// parseNumber parses a single operand. Negative numbers are accepted.
func parseNumber(word string) (int, bool) {
	n, err := strconv.Atoi(word)
	if err != nil {
		return 0, false
	}
	return n, true
}

// parseOperation recognises the operation at the start of words. It returns
// the operation and the number of words it spans: "plus" is a single word,
// whereas "multiplied by" and "divided by" span two.
func parseOperation(words []string) (operation, int, bool) {
	if len(words) == 0 {
		return nil, 0, false
	}

	switch words[0] {
	case "plus":
		return add, 1, true
	case "minus":
		return subtract, 1, true
	case "multiplied":
		if len(words) > 1 && words[1] == "by" {
			return multiply, 2, true
		}
	case "divided":
		if len(words) > 1 && words[1] == "by" {
			return divide, 2, true
		}
	}

	return nil, 0, false
}

func add(a, b int) (int, bool) {
	if (b > 0 && a > math.MaxInt-b) || (b < 0 && a < math.MinInt-b) {
		return 0, false
	}
	return a + b, true
}

func subtract(a, b int) (int, bool) {
	if (b > 0 && a < math.MinInt+b) || (b < 0 && a > math.MaxInt+b) {
		return 0, false
	}
	return a - b, true
}

func multiply(a, b int) (int, bool) {
	if a == 0 || b == 0 {
		return 0, true
	}
	product := a * b
	// If the product overflowed, dividing it back does not recover a. The one
	// exception is MinInt * -1, whose division overflows back to MinInt.
	if product/b != a || (a == math.MinInt && b == -1) {
		return 0, false
	}
	return product, true
}

func divide(a, b int) (int, bool) {
	if b == 0 || (a == math.MinInt && b == -1) {
		return 0, false
	}
	// Integer division truncates toward zero.
	return a / b, true
}
