wordy.go
```
package wordy

import (
	"strconv"
	"strings"
)

// Answer parses and evaluates a simple math word problem.
// It returns the integer result and true on success, or 0 and false if the
// question is not a valid math word problem.
func Answer(question string) (int, bool) {
	const prefix = "what is"

	q := strings.TrimSpace(strings.ToLower(question))
	if !strings.HasPrefix(q, prefix) {
		return 0, false
	}
	if !strings.HasSuffix(q, "?") {
		return 0, false
	}

	body := strings.TrimSpace(q[len(prefix) : len(q)-1])
	if body == "" {
		return 0, false
	}

	tokens := strings.Fields(body)
	if len(tokens) == 0 {
		return 0, false
	}

	// Expect: number (operator number)*
	result, ok := parseNumber(tokens[0])
	if !ok {
		return 0, false
	}

	i := 1
	for i < len(tokens) {
		op, consumed := parseOperator(tokens[i:])
		if consumed == 0 {
			return 0, false
		}
		i += consumed

		if i >= len(tokens) {
			return 0, false
		}

		operand, ok := parseNumber(tokens[i])
		if !ok {
			return 0, false
		}
		i++

		result, ok = apply(op, result, operand)
		if !ok {
			return 0, false
		}
	}

	return result, true
}

// parseNumber converts a token to an integer.
func parseNumber(token string) (int, bool) {
	n, err := strconv.Atoi(token)
	if err != nil {
		return 0, false
	}
	return n, true
}

// parseOperator recognizes an operator at the start of the token slice.
// It returns the operator name and the number of tokens it consumed.
func parseOperator(tokens []string) (string, int) {
	if len(tokens) == 0 {
		return "", 0
	}
	switch tokens[0] {
	case "plus":
		return "plus", 1
	case "minus":
		return "minus", 1
	case "multiplied":
		if len(tokens) >= 2 && tokens[1] == "by" {
			return "multiplied", 2
		}
	case "divided":
		if len(tokens) >= 2 && tokens[1] == "by" {
			return "divided", 2
		}
	}
	return "", 0
}

// apply performs a single binary operation. It fails on division by zero
// or when division does not produce an exact integer.
func apply(op string, a, b int) (int, bool) {
	switch op {
	case "plus":
		return a + b, true
	case "minus":
		return a - b, true
	case "multiplied":
		return a * b, true
	case "divided":
		if b == 0 {
			return 0, false
		}
		if a%b != 0 {
			return 0, false
		}
		return a / b, true
	}
	return 0, false
}
