package wordy

import (
	"strconv"
	"strings"
)

// Answer evaluates a simple math word problem such as "What is 5 plus 13?"
// and returns the integer result. Operations are evaluated left-to-right,
// ignoring the usual order of operations. The bool result is false if the
// question is not a valid math word problem.
func Answer(question string) (int, bool) {
	const prefix = "What is"

	if !strings.HasPrefix(question, prefix) || !strings.HasSuffix(question, "?") {
		return 0, false
	}

	body := strings.TrimSpace(question[len(prefix) : len(question)-1])
	tokens := strings.Fields(body)
	if len(tokens) == 0 {
		return 0, false
	}

	result, ok := parseNumber(tokens[0])
	if !ok {
		return 0, false
	}

	i := 1
	for i < len(tokens) {
		op, next, ok := parseOperator(tokens, i)
		if !ok {
			return 0, false
		}
		i = next

		if i >= len(tokens) {
			return 0, false
		}
		operand, ok := parseNumber(tokens[i])
		if !ok {
			return 0, false
		}
		i++

		result, ok = apply(op, result, operand)
		if !ok {
			return 0, false
		}
	}

	return result, true
}

// parseNumber converts a token into an int, rejecting anything that is not
// a valid (possibly negative) integer that fits in an int.
func parseNumber(token string) (int, bool) {
	n, err := strconv.Atoi(token)
	if err != nil {
		return 0, false
	}
	return n, true
}

// parseOperator reads the operator starting at tokens[i] and returns its
// canonical name along with the index of the token following the operator.
func parseOperator(tokens []string, i int) (string, int, bool) {
	switch tokens[i] {
	case "plus":
		return "plus", i + 1, true
	case "minus":
		return "minus", i + 1, true
	case "multiplied":
		if i+1 < len(tokens) && tokens[i+1] == "by" {
			return "multiplied", i + 2, true
		}
	case "divided":
		if i+1 < len(tokens) && tokens[i+1] == "by" {
			return "divided", i + 2, true
		}
	}
	return "", 0, false
}

// apply performs a single binary operation. It returns false for unknown
// operations or division by zero.
func apply(op string, a, b int) (int, bool) {
	switch op {
	case "plus":
		return a + b, true
	case "minus":
		return a - b, true
	case "multiplied":
		return a * b, true
	case "divided":
		if b == 0 {
			return 0, false
		}
		return a / b, true
	}
	return 0, false
}
