```
package wordy

import (
	"strconv"
	"strings"
)

const questionPrefix = "What is"

// Answer evaluates a simple math word problem, returning the result and
// whether the question was valid. Operations are evaluated strictly from
// left to right, ignoring the usual order of operations.
func Answer(question string) (int, bool) {
	s := strings.TrimSpace(question)

	if !strings.HasPrefix(s, questionPrefix) {
		return 0, false
	}
	rest := s[len(questionPrefix):]
	if rest == "" || rest[0] != ' ' {
		return 0, false
	}
	if !strings.HasSuffix(rest, "?") {
		return 0, false
	}
	body := strings.TrimSuffix(rest, "?")

	tokens := strings.Fields(body)
	if len(tokens) == 0 {
		return 0, false
	}

	result, ok := parseNumber(tokens[0])
	if !ok {
		return 0, false
	}

	i := 1
	for i < len(tokens) {
		op, consumed, ok := parseOperator(tokens[i:])
		if !ok {
			return 0, false
		}
		i += consumed

		if i >= len(tokens) {
			return 0, false
		}
		operand, ok := parseNumber(tokens[i])
		if !ok {
			return 0, false
		}
		i++

		result, ok = apply(op, result, operand)
		if !ok {
			return 0, false
		}
	}

	return result, true
}

// parseNumber converts a token into an integer, accepting an optional sign.
func parseNumber(token string) (int, bool) {
	n, err := strconv.Atoi(token)
	if err != nil {
		return 0, false
	}
	return n, true
}

// parseOperator recognizes an operator at the start of the given tokens.
// It returns the operator name, the number of tokens consumed, and whether
// an operator was found.
func parseOperator(tokens []string) (string, int, bool) {
	if len(tokens) == 0 {
		return "", 0, false
	}
	switch tokens[0] {
	case "plus":
		return "plus", 1, true
	case "minus":
		return "minus", 1, true
	case "multiplied":
		if len(tokens) >= 2 && tokens[1] == "by" {
			return "multiplied", 2, true
		}
	case "divided":
		if len(tokens) >= 2 && tokens[1] == "by" {
			return "divided", 2, true
		}
	}
	return "", 0, false
}

// apply performs a single binary operation. It returns false for unknown
// operators or division by zero.
func apply(op string, a, b int) (int, bool) {
	switch op {
	case "plus":
		return a + b, true
	case "minus":
		return a - b, true
	case "multiplied":
		return a * b, true
	case "divided":
		if b == 0 {
			return 0, false
		}
		return a / b, true
	}
	return 0, false
}
```

Approach: strip the "What is" prefix and trailing "?", tokenize on whitespace, then parse alternating number and operator tokens, evaluating strictly left-to-right. Any unsupported operation, non-numeric token, malformed sequence, or non-math question returns `(0, false)`. Numbers may be negative. Overflow isn't explicitly handled beyond Go's int behavior.

wordy.go
```
package wordy

import (
	"strconv"
	"strings"
)

func Answer(question string) (int, bool) {
	q := strings.TrimSpace(question)
	if !strings.HasPrefix(q, "What is") || !strings.HasSuffix(q, "?") {
		return 0, false
	}
	body := strings.TrimSpace(strings.TrimSuffix(strings.TrimPrefix(q, "What is"), "?"))
	if body == "" {
		return 0, false
	}

	tokens := strings.Fields(body)

	// First token must be a number.
	result, err := strconv.Atoi(tokens[0])
	if err != nil {
		return 0, false
	}

	i := 1
	for i < len(tokens) {
		op := tokens[i]
		if i+1 >= len(tokens) {
			return 0, false
		}
		operand, err := strconv.Atoi(tokens[i+1])
		if err != nil {
			return 0, false
		}

		switch op {
		case "plus":
			result += operand
		case "minus":
			result -= operand
		case "multiplied":
			// Expect "multiplied by"
			if i+2 >= len(tokens) || tokens[i+1] != "by" {
				return 0, false
			}
			operand, err = strconv.Atoi(tokens[i+2])
			if err != nil {
				return 0, false
			}
			result *= operand
			i += 3
			continue
		case "divided":
			// Expect "divided by"
			if i+2 >= len(tokens) || tokens[i+1] != "by" {
				return 0, false
			}
			operand, err = strconv.Atoi(tokens[i+2])
			if err != nil || operand == 0 {
				return 0, false
			}
			result /= operand
			i += 3
			continue
		default:
			return 0, false
		}
		i += 2
	}

	return result, true
}
