package trinary

import "math"

// ParseTrinary converts a trinary number, written as a string of the digits
// '0', '1' and '2' (e.g. "102012"), to its decimal equivalent.
//
// It returns the decimal value and true when arg is a valid trinary number.
// Anything that does not specify a valid trinary number, including the empty
// string and any value too large for an int64, yields 0 and false.
//
// The conversion is done from first principles. Each digit contributes
// digit * 3^position to the total, which is computed here by scanning the
// digits from left to right with result = result*3 + digit.
func ParseTrinary(arg string) (int64, bool) {
	if len(arg) == 0 {
		return 0, false
	}

	var result int64
	for i := 0; i < len(arg); i++ {
		c := arg[i]
		if c < '0' || c > '2' {
			return 0, false
		}
		digit := int64(c - '0')

		// Reject the input before result*3 + digit would exceed the int64 range.
		if result > (math.MaxInt64-digit)/3 {
			return 0, false
		}
		result = result*3 + digit
	}

	return result, true
}
