// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

/// A single element of the list. Every node is allocated separately on the heap
/// and linked to its neighbors with raw pointers.
struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

/// Moves `element` into a new, unlinked node on the heap and returns a pointer to it.
///
/// The pointer owns the allocation. It must be turned back into a `Box` with
/// `Box::from_raw` exactly once, which the list does when it unlinks or drops the node.
fn alloc_node<T>(element: T) -> NonNull<Node<T>> {
    let node = Box::new(Node {
        element,
        prev: None,
        next: None,
    });
    NonNull::from(Box::leak(node))
}

/// A doubly linked list.
///
/// # Invariants
///
/// - `head` is `None` if and only if `tail` is `None`, which is the case if and only if `len` is `0`.
/// - Following `next` pointers from `head` visits exactly `len` nodes and ends at `tail`.
/// - Following `prev` pointers from `tail` visits the same nodes in reverse order.
/// - The `prev` of `head` and the `next` of `tail` are `None`.
/// - Every node is a live allocation made by `alloc_node`. The list owns it, links it in
///   exactly once and frees it exactly once.
pub struct LinkedList<T> {
    head: Option<NonNull<Node<T>>>,
    tail: Option<NonNull<Node<T>>>,
    len: usize,
    // Tells the compiler that the list owns its nodes, which matters for drop check.
    // `Box` is covariant, so this also keeps `LinkedList<T>` covariant in `T`.
    _marker: PhantomData<Box<Node<T>>>,
}

/// A cursor that points at an element of a `LinkedList` and can move around the list
/// and modify it.
///
/// # Invariants
///
/// - `current` is `None` if and only if the list is empty.
/// - Otherwise, `current` points to a node that is linked into `list`.
///
/// The cursor holds the only reference to the list, so nothing else can change the
/// list while the cursor exists.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Option<NonNull<Node<T>>>,
}

/// An iterator over the elements of a `LinkedList`, from front to back.
///
/// # Invariants
///
/// - `front` points to the node that is yielded next. It is `None` once the iterator is exhausted.
/// - `remaining` is the number of nodes from `front` to the back. It is `0` exactly when `front`
///   is `None`.
/// - The shared borrow `'a` of the list keeps its nodes alive and unmodified.
pub struct Iter<'a, T> {
    front: Option<NonNull<Node<T>>>,
    remaining: usize,
    _marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    ///
    /// If the list is empty, the cursor has no element, but it can still insert.
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.head;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    ///
    /// If the list is empty, the cursor has no element, but it can still insert.
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.tail;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            front: self.head,
            remaining: self.len,
            _marker: PhantomData,
        }
    }

    /// Links `new`, a node that is not part of any list, between `prev` and `next`.
    ///
    /// `None` stands for the boundary of the list: `prev == None` means `next` is the front,
    /// `next == None` means `prev` is the back, and both being `None` means the list is empty.
    ///
    /// # Safety
    ///
    /// - If `prev` is `Some(p)`, then `p` must be linked into `self` and its successor must be `next`.
    /// - If `next` is `Some(n)`, then `n` must be linked into `self` and its predecessor must be `prev`.
    /// - If `prev` is `None`, then `next` must be `self.head`.
    /// - If `next` is `None`, then `prev` must be `self.tail`.
    /// - `new` must be a live node from `alloc_node` that is not linked into any list.
    unsafe fn link_between(
        &mut self,
        prev: Option<NonNull<Node<T>>>,
        next: Option<NonNull<Node<T>>>,
        new: NonNull<Node<T>>,
    ) {
        // SAFETY: `new` is live and not linked into any list (caller invariant), so nothing else
        // refers to it and we may write its links.
        unsafe {
            (*new.as_ptr()).prev = prev;
            (*new.as_ptr()).next = next;
        }

        match prev {
            // SAFETY: `p` is linked into `self` (caller invariant), so it is live. We only write
            // its `next` link.
            Some(p) => unsafe { (*p.as_ptr()).next = Some(new) },
            None => self.head = Some(new),
        }

        match next {
            // SAFETY: `n` is linked into `self` (caller invariant), so it is live. We only write
            // its `prev` link.
            Some(n) => unsafe { (*n.as_ptr()).prev = Some(new) },
            None => self.tail = Some(new),
        }

        self.len += 1;
    }

    /// Unlinks `node` from the list and returns the box that owned it.
    ///
    /// # Safety
    ///
    /// - `node` must be linked into `self`.
    /// - Afterwards, `node` and all copies of its pointer must not be used anymore, since the
    ///   returned box frees the allocation when it is dropped.
    unsafe fn unlink_node(&mut self, node: NonNull<Node<T>>) -> Box<Node<T>> {
        // SAFETY: `node` is linked into the list (caller invariant), so it is live.
        let (prev, next) = unsafe { ((*node.as_ptr()).prev, (*node.as_ptr()).next) };

        match prev {
            // SAFETY: `p` is linked into the list (list invariant), so it is live. We only write
            // its `next` link, which now skips over `node`.
            Some(p) => unsafe { (*p.as_ptr()).next = next },
            None => self.head = next,
        }

        match next {
            // SAFETY: `n` is linked into the list (list invariant), so it is live. We only write
            // its `prev` link, which now skips over `node`.
            Some(n) => unsafe { (*n.as_ptr()).prev = prev },
            None => self.tail = prev,
        }

        self.len -= 1;

        // SAFETY: `node` was created by `alloc_node` via `Box::leak`, so it can be turned back into
        // a `Box`. It is no longer linked, and the caller won't use it again, so the returned box is
        // the only owner and the allocation is freed exactly once.
        unsafe { Box::from_raw(node.as_ptr()) }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut current = self.head;
        while let Some(node) = current {
            // SAFETY: Every node reachable from `head` through `next` is a live allocation owned by
            // this list. Each is reached exactly once and reclaimed here, and nothing else can reach
            // them because the list is being dropped.
            let boxed = unsafe { Box::from_raw(node.as_ptr()) };
            // Read the successor before `boxed` is dropped at the end of this iteration.
            current = boxed.next;
        }
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    ///
    /// Returns `None` if the list is empty.
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: `current` is linked into the list (cursor invariant), so it is live. `&mut self`
        // means no other reference to the element can exist while the returned one is in use.
        Some(unsafe { &mut (*current.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    ///
    /// If the cursor is already on the back element, it stays there and `None` is returned.
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: `current` is linked into the list (cursor invariant), so it is live.
        let next = unsafe { (*current.as_ptr()).next }?;
        self.current = Some(next);
        // SAFETY: `next` is linked into the list, since `current` links to it. `&mut self` means
        // no other reference to the element can exist while the returned one is in use.
        Some(unsafe { &mut (*next.as_ptr()).element })
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    ///
    /// If the cursor is already on the front element, it stays there and `None` is returned.
    pub fn prev(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: `current` is linked into the list (cursor invariant), so it is live.
        let prev = unsafe { (*current.as_ptr()).prev }?;
        self.current = Some(prev);
        // SAFETY: `prev` is linked into the list, since `current` links to it. `&mut self` means
        // no other reference to the element can exist while the returned one is in use.
        Some(unsafe { &mut (*prev.as_ptr()).element })
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    ///
    /// Returns `None` if the list is empty.
    pub fn take(&mut self) -> Option<T> {
        let current = self.current?;
        // SAFETY: `current` is linked into the list (cursor invariant), so it is live.
        let (prev, next) = unsafe { ((*current.as_ptr()).prev, (*current.as_ptr()).next) };
        // Prefer the next element, which is closest to the back, and otherwise take the previous one.
        // If neither exists, the list becomes empty and the cursor has no current node.
        // Neither neighbor is `current`, so the new position stays valid after the unlink below.
        self.current = next.or(prev);
        // SAFETY: `current` is linked into `self.list` (cursor invariant). The cursor no longer refers
        // to it and it is not used after this call, so it can be unlinked and freed.
        let node = unsafe { self.list.unlink_node(current) };
        Some(node.element)
    }

    /// Insert `element` after the current position. The cursor stays on its current element.
    /// If the list is empty, `element` becomes the only element and the cursor moves onto it.
    pub fn insert_after(&mut self, element: T) {
        let new = alloc_node(element);
        let position = self.current;
        match position {
            Some(current) => {
                // SAFETY: `current` is linked into the list (cursor invariant), so it is live.
                let next = unsafe { (*current.as_ptr()).next };
                // SAFETY: `current` and `next` are adjacent in the list, and `new` is a fresh node
                // that is not linked anywhere yet.
                unsafe { self.list.link_between(Some(current), next, new) };
            }
            None => {
                // SAFETY: The cursor has no current node only if the list is empty (cursor invariant),
                // so `None` and `None` are the adjacent positions. `new` is a fresh node.
                unsafe { self.list.link_between(None, None, new) };
                self.current = Some(new);
            }
        }
    }

    /// Insert `element` before the current position. The cursor stays on its current element.
    /// If the list is empty, `element` becomes the only element and the cursor moves onto it.
    pub fn insert_before(&mut self, element: T) {
        let new = alloc_node(element);
        let position = self.current;
        match position {
            Some(current) => {
                // SAFETY: `current` is linked into the list (cursor invariant), so it is live.
                let prev = unsafe { (*current.as_ptr()).prev };
                // SAFETY: `prev` and `current` are adjacent in the list, and `new` is a fresh node
                // that is not linked anywhere yet.
                unsafe { self.list.link_between(prev, Some(current), new) };
            }
            None => {
                // SAFETY: The cursor has no current node only if the list is empty (cursor invariant),
                // so `None` and `None` are the adjacent positions. `new` is a fresh node.
                unsafe { self.list.link_between(None, None, new) };
                self.current = Some(new);
            }
        }
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.front?;
        // SAFETY: `node` is linked into the list, which is borrowed for `'a` and can't be modified
        // while this iterator exists (iterator invariant). So the node is live, and a shared
        // reference to its element is valid for `'a`.
        let (element, next) = unsafe { (&(*node.as_ptr()).element, (*node.as_ptr()).next) };
        self.front = next;
        self.remaining -= 1;
        Some(element)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

// SAFETY: A list owns its nodes exclusively (like a `Box<Node<T>>`), so it can be sent to another
// thread whenever its elements can be.
unsafe impl<T: Send> Send for LinkedList<T> {}

// SAFETY: Sharing a list only gives out `&T`s (through `iter`), so it is safe to share between
// threads whenever `T` can be shared between threads.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: A cursor holds an exclusive reference to the list and can mutate the elements through
// `peek_mut`, so it can be sent to another thread whenever `T` can be sent.
unsafe impl<T: Send> Send for Cursor<'_, T> {}

// SAFETY: `&Cursor` exposes no access to the elements, but the cursor wraps a `&mut LinkedList<T>`,
// so we use the same bound the auto trait rules would: `T` must be `Sync`.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: An iterator yields `&T`s and so behaves like a shared reference to the list, which can be
// sent to another thread whenever `T` can be shared between threads.
unsafe impl<T: Sync> Send for Iter<'_, T> {}

// SAFETY: An iterator only hands out shared references to the elements, so sharing it between
// threads is safe whenever `T` can be shared between threads.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}
