pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    // `None` is the "ghost" position between the back and the front of the list.
    // Invariant: if `Some(n)`, `n` is a live node belonging to `list`.
    current: Option<NonNull<Node<T>>>,
}

pub struct Iter<'a, T> {
    next: Option<NonNull<Node<T>>>,
    remaining: usize,
    marker: PhantomData<&'a T>,
}

// SAFETY: Iter yields shared references to T, so it is Send/Sync when T: Sync.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            marker: PhantomData,
        }
