// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is either None or a live node owned by the list;
        // we hold `&mut self` (and thus `&mut list`), so no aliasing exists.
        self.current.map(|n| unsafe { &mut (*n.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is either None or a live node of the list.
        self.current = match self.current {
            Some(n) => unsafe { (*n.as_ptr()).next },
            None => self.list.head,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is either None or a live node of the list.
        self.current = match self.current {
            Some(n) => unsafe { (*n.as_ptr()).prev },
            None => self.list.tail,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;
        // SAFETY: `node` is a live node owned by the list. We unlink it, fix up
        // the neighbors and head/tail, then reclaim the Box exactly once.
        unsafe {
            let boxed = Box::from_raw(node.as_ptr());
            let prev = boxed.prev;
            let next = boxed.next;

            match prev {
                Some(p) => (*p.as_ptr()).next = next,
                None => self.list.head = next,
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = prev,
                None => self.list.tail = prev,
            }

            self.list.len -= 1;
            // Move to the neighbor closest to the back.
            self.current = next.or(prev);
            Some(boxed.element)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let new = Box::new(Node {
            element,
            prev: None,
            next: None,
        });
        let new = NonNull::from(Box::leak(new));

        match self.current {
            None => {
                // Ghost position: insert at the front of the list.
                // SAFETY: `new` is a freshly leaked, valid, uniquely owned node.
                unsafe {
                    (*new.as_ptr()).next = self.list.head;
                    match self.list.head {
                        Some(h) => (*h.as_ptr()).prev = Some(new),
                        None => self.list.tail = Some(new),
                    }
                }
                self.list.head = Some(new);
            }
            Some(cur) => {
                // SAFETY: `cur` is a live node of the list; `new` is valid and unique.
                unsafe {
                    let after = (*cur.as_ptr()).next;
                    (*new.as_ptr()).prev = Some(cur);
                    (*new.as_ptr()).next = after;
                    (*cur.as_ptr()).next = Some(new);
                    match after {
                        Some(a) => (*a.as_ptr()).prev = Some(new),
                        None => self.list.tail = Some(new),
                    }
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = Box::new(Node {
            element,
            prev: None,
            next: None,
        });
        let new = NonNull::from(Box::leak(new));

        match self.current {
            None => {
                // Ghost position: insert at the back of the list.
                // SAFETY: `new` is a freshly leaked, valid, uniquely owned node.
                unsafe {
                    (*new.as_ptr()).prev = self.list.tail;
                    match self.list.tail {
                        Some(t) => (*t.as_ptr()).next = Some(new),
                        None => self.list.head = Some(new),
                    }
                }
                self.list.tail = Some(new);
            }
            Some(cur) => {
                // SAFETY: `cur` is a live node of the list; `new` is valid and unique.
                unsafe {
                    let before = (*cur.as_ptr()).prev;
                    (*new.as_ptr()).next = Some(cur);
                    (*new.as_ptr()).prev = before;
                    (*cur.as_ptr()).prev = Some(new);
                    match before {
                        Some(b) => (*b.as_ptr()).next = Some(new),
                        None => self.list.head = Some(new),
                    }
                }
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: `node` is a live node of the list borrowed for 'a via `&LinkedList`.
        // No mutation can occur while the iterator (which borrows the list) exists.
        unsafe {
            let r = &(*node.as_ptr()).element;
            self.next = (*node.as_ptr()).next;
            self.remaining -= 1;
            Some(r)
        }
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cur = self.head;
        while let Some(node) = cur {
            // SAFETY: every node was created via Box::leak and is owned solely by
            // the list; we free each exactly once while walking the chain.
            unsafe {
                let boxed = Box::from_raw(node.as_ptr());
                cur = boxed.next;
            }
        }
        self.head = None;
        self.tail = None;
        self.len = 0;
    }
}
