// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

/// A node of the doubly linked list. Nodes are heap-allocated and owned by the list.
///
/// Invariants (maintained by `LinkedList`, `Cursor` and `Iter`):
/// - `prev` is `None` only for the head node, and `next` is `None` only for the tail node.
/// - If `a.next == Some(b)` then `b.prev == Some(a)`, and vice versa.
struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

/// A doubly linked list.
///
/// Invariants:
/// - `head` and `tail` are both `None` if and only if the list is empty.
/// - `len` is the number of nodes reachable from `head` by following `next`.
/// - Every node pointer stored in the list was created with `Box::leak` and is owned
///   exclusively by this list until it is removed (and deallocated with `Box::from_raw`).
/// - The node links are consistent (see `Node`).
pub struct LinkedList<T> {
    head: Option<NonNull<Node<T>>>,
    tail: Option<NonNull<Node<T>>>,
    len: usize,
    // Marks that the list owns `Node<T>` values (for drop check) while keeping
    // the list covariant in `T`.
    marker: PhantomData<Box<Node<T>>>,
}

/// A cursor over a `LinkedList`. It can move back and forth, read and modify elements,
/// and insert or remove them.
///
/// The cursor is either positioned on an element, or on the "ghost" position that sits
/// between the back and the front of the list. The ghost is used for empty lists and
/// when the cursor moves past either end.
///
/// Invariant: `current` is either `None` (the ghost position) or points to a live node of `list`.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Option<NonNull<Node<T>>>,
}

/// An iterator over shared references to the elements of a `LinkedList`, from front to back.
///
/// Invariant: `next` is either `None` or points to a live node of the borrowed list.
pub struct Iter<'a, T> {
    next: Option<NonNull<Node<T>>>,
    marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.head;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.tail;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.head,
            marker: PhantomData,
        }
    }

    /// Allocates a new node holding `element` and links it between `prev` and `next`.
    ///
    /// # Safety
    /// - `prev` and `next` must each be `None` or point to a live node owned by `self`.
    /// - If both are `Some`, they must be adjacent: `prev.next == next` and `next.prev == prev`.
    /// - If `prev` is `None`, then `next` must be `self.head`.
    /// - If `next` is `None`, then `prev` must be `self.tail`.
    unsafe fn link_node(
        &mut self,
        prev: Option<NonNull<Node<T>>>,
        next: Option<NonNull<Node<T>>>,
        element: T,
    ) {
        // The new node is leaked into a raw pointer. From now on the list owns it, and it
        // is reclaimed either in `unlink_node` or in `Drop`.
        let node = NonNull::from(Box::leak(Box::new(Node { element, prev, next })));

        // SAFETY: `prev` and `next`, if `Some`, point to live nodes owned by `self`
        // (caller invariant). `node` was just allocated, so it differs from both.
        // We only write to the `prev`/`next` fields of those nodes, and never create
        // references to whole nodes.
        unsafe {
            match prev {
                Some(p) => (*p.as_ptr()).next = Some(node),
                // `next` is the old head (caller invariant), so the new node becomes the head.
                None => self.head = Some(node),
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = Some(node),
                // `prev` is the old tail (caller invariant), so the new node becomes the tail.
                None => self.tail = Some(node),
            }
        }
        self.len += 1;
    }

    /// Removes `node` from the list, deallocates it, and returns its element.
    ///
    /// # Safety
    /// `node` must point to a live node owned by `self`. After this call the pointer is
    /// dangling, so it must not be used again (for example, a cursor must not keep it as `current`).
    unsafe fn unlink_node(&mut self, node: NonNull<Node<T>>) -> T {
        // SAFETY: `node` was created by `Box::leak` in `link_node` and is owned exclusively
        // by this list (caller invariant), so reclaiming it with `Box::from_raw` is sound.
        // The whole node is moved out, so it is deallocated exactly once.
        let Node {
            element,
            prev,
            next,
        } = unsafe { *Box::from_raw(node.as_ptr()) };

        // SAFETY: `prev` and `next` are the neighbours of `node`, so they are live nodes owned
        // by this list (the links are consistent). We update their links to skip over `node`,
        // which is no longer reachable from the list.
        unsafe {
            match prev {
                Some(p) => (*p.as_ptr()).next = next,
                None => self.head = next,
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = prev,
                None => self.tail = prev,
            }
        }
        self.len -= 1;
        element
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        let node = self.current?;
        // SAFETY: `node` is a live node of the list (cursor invariant). The returned reference
        // is tied to the borrow of `self`, which holds the unique borrow of the list, so no other
        // reference to this element can exist while it is alive.
        unsafe { Some(&mut (*node.as_ptr()).element) }
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // The ghost position is followed by the front of the list.
            None => self.list.head,
            // SAFETY: `node` is a live node of the list (cursor invariant). We only read its `next` link.
            Some(node) => unsafe { (*node.as_ptr()).next },
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // The ghost position is preceded by the back of the list.
            None => self.list.tail,
            // SAFETY: `node` is a live node of the list (cursor invariant). We only read its `prev` link.
            Some(node) => unsafe { (*node.as_ptr()).prev },
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;
        // SAFETY: `node` is a live node of the list (cursor invariant). We only read its links.
        let (prev, next) = unsafe { ((*node.as_ptr()).prev, (*node.as_ptr()).next) };
        // Move the cursor away from `node` before it is removed. Prefer the neighbour closest
        // to the back. If there is no neighbour at all, the cursor ends up on the ghost position.
        self.current = next.or(prev);
        // SAFETY: `node` is a live node owned by the list. The cursor no longer refers to it,
        // so it cannot be used after removal.
        Some(unsafe { self.list.unlink_node(node) })
    }

    pub fn insert_after(&mut self, element: T) {
        let (prev, next) = match self.current {
            // The ghost position sits between the back and the front, so inserting "after"
            // it inserts at the front of the list.
            None => (None, self.list.head),
            // SAFETY: `node` is a live node of the list (cursor invariant). We only read its `next` link.
            Some(node) => (Some(node), unsafe { (*node.as_ptr()).next }),
        };
        // SAFETY: `prev` is `None` or a live node of the list, and `next` is its successor.
        // `None` on either side corresponds to the head or the tail, as `link_node` requires.
        unsafe { self.list.link_node(prev, next, element) };
    }

    pub fn insert_before(&mut self, element: T) {
        let (prev, next) = match self.current {
            // The ghost position sits between the back and the front, so inserting "before"
            // it inserts at the back of the list.
            None => (self.list.tail, None),
            // SAFETY: `node` is a live node of the list (cursor invariant). We only read its `prev` link.
            Some(node) => (unsafe { (*node.as_ptr()).prev }, Some(node)),
        };
        // SAFETY: `next` is `None` or a live node of the list, and `prev` is its predecessor.
        // `None` on either side corresponds to the head or the tail, as `link_node` requires.
        unsafe { self.list.link_node(prev, next, element) };
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: `node` is a live node of the borrowed list (iterator invariant). The list is
        // immutably borrowed for `'a`, so it is not modified while we hand out shared references.
        unsafe {
            let node = &*node.as_ptr();
            self.next = node.next;
            Some(&node.element)
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut current = self.head;
        while let Some(node) = current {
            // SAFETY: every node reachable from `head` by following `next` is live and owned
            // exclusively by this list. Each is visited exactly once. The `next` link is read
            // before the box is dropped, which deallocates the node.
            let boxed = unsafe { Box::from_raw(node.as_ptr()) };
            current = boxed.next;
        }
    }
}

// SAFETY: `LinkedList<T>` owns its nodes, like a `Box<Node<T>>` would, so it can be sent
// to another thread whenever `T` can.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: Shared access to the list only yields shared references to elements (via `Iter`),
// so it is safe to share across threads whenever `T` is `Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: The cursor has unique access to the list, so it can be sent whenever `T` can.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
// SAFETY: A shared cursor reference exposes no mutable access, so it can be shared whenever `T` is `Sync`.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: `Iter` behaves like a shared reference to the elements, so it can be sent whenever `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
// SAFETY: `Iter` behaves like a shared reference to the elements, so it can be shared whenever `T: Sync`.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}
