// sound if T itself is Send.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: Shared references only permit reading elements, which is sound if T is Sync.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    // `None` is the "ghost" position between the back and the front of the list.
    current: Option<NonNull<Node<T>>>,
}

pub struct Iter<'a, T> {
    front: Option<NonNull<Node<T>>>,
    back: Option<NonNull<Node<T>>>,
    len: usize,
    marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.head.is_none()
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.head;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.tail;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            front: self.head,
            back: self.tail,
            len: self.len,
            marker: PhantomData,
        }
    }
}

impl<T> Default for LinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cur = self.head;
        while let Some(ptr) = cur {
            // SAFETY: every non-null pointer in the list was created by Box::into_raw
            // and has not been freed yet; we free each node exactly once while walking.
            let boxed = unsafe { Box::from_raw(ptr.as_ptr()) };
            cur = boxed.next;
            drop(boxed);
        }
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is either None or points to a live node owned by the list;
        // the `&mut self` borrow guarantees exclusive access for the returned lifetime.
        self.current.map(|ptr| unsafe { &mut (*ptr.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        // SAFETY: current node (if any) is live; its `next` link is valid or None.
        self.current = match self.current {
            Some(ptr) => unsafe { (*ptr.as_ptr()).next },
            None => self.list.head,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        // SAFETY: current node (if any) is live; its `prev` link is valid or None.
        self.current = match self.current {
            Some(ptr) => unsafe { (*ptr.as_ptr()).prev },
            None => self.list.tail,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let ptr = self.current?;
        // SAFETY: `ptr` is a live node in this list. We unlink it, fix up neighbours
        // and head/tail, then reclaim the box exactly once.
        unsafe {
            let node = ptr.as_ptr();
            let prev = (*node).prev;
            let next = (*node).next;

            match prev {
                Some(p) => (*p.as_ptr()).next = next,
                None => self.list.head = next,
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = prev,
                None => self.list.tail = prev,
            }

            self.list.len -= 1;
            // Move cursor to the neighbour closest to the back.
            self.current = next.or(prev);

            let boxed = Box::from_raw(node);
            Some(boxed.element)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let new = Box::into_raw(Box::new(Node {
            element,
            prev: None,
            next: None,
        }));
        // SAFETY: `new` is a freshly allocated, valid pointer we now exclusively own.
        // Neighbour pointers we touch are live nodes of this list.
        unsafe {
            let new_ptr = NonNull::new_unchecked(new);
            match self.current {
                None => {
                    // Ghost position: insert at the front.
                    let old_head = self.list.head;
                    (*new).next = old_head;
                    match old_head {
                        Some(h) => (*h.as_ptr()).prev = Some(new_ptr),
                        None => self.list.tail = Some(new_ptr),
                    }
                    self.list.head = Some(new_ptr);
                }
                Some(cur) => {
                    let cur_node = cur.as_ptr();
                    let after = (*cur_node).next;
                    (*new).prev = Some(cur);
                    (*new).next = after;
                    (*cur_node).next = Some(new_ptr);
                    match after {
                        Some(a) => (*a.as_ptr()).prev = Some(new_ptr),
                        None => self.list.tail = Some(new_ptr),
                    }
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = Box::into_raw(Box::new(Node {
            element,
            prev: None,
            next: None,
        }));
        // SAFETY: same reasoning as `insert_after`.
        unsafe {
            let new_ptr = NonNull::new_unchecked(new);
            match self.current {
                None => {
                    // Ghost position: insert at the back.
                    let old_tail = self.list.tail;
                    (*new).prev = old_tail;
                    match old_tail {
                        Some(t) => (*t.as_ptr()).next = Some(new_ptr),
                        None => self.list.head = Some(new_ptr),
                    }
                    self.list.tail = Some(new_ptr);
                }
                Some(cur) => {
                    let cur_node = cur.as_ptr();
                    let before = (*cur_node).prev;
                    (*new).next = Some(cur);
                    (*new).prev = before;
                    (*cur_node).prev = Some(new_ptr);
                    match before {
                        Some(b) => (*b.as_ptr()).next = Some(new_ptr),
                        None => self.list.head = Some(new_ptr),
                    }
                }
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        if self.len == 0 {
            return None;
        }
        let ptr = self.front?;
        // SAFETY: `front` points to a live node that outlives `'a` because the
        // iterator borrows the list immutably for `'a`.
        unsafe {
            let node = &*ptr.as_ptr();
            self.front = node.next;
            self.len -= 1;
            Some(&node.element)
        }
    }
}
