// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

/// A node in the doubly linked list.
///
/// Invariants:
/// - `prev` and `next` are either `None` (no neighbor) or point to a live node
///   owned by the same list.
/// - The first node's `prev` is `None`, the last node's `next` is `None`.
struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

/// Allocates a new node on the heap and returns ownership as a raw pointer.
/// The caller is responsible for linking it in and eventually freeing it.
fn new_node<T>(
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
) -> NonNull<Node<T>> {
    let boxed = Box::new(Node { element, prev, next });
    NonNull::from(Box::leak(boxed))
}

/// Invariants:
/// - `head` is the first node and `tail` the last node; both are `None` iff the list is empty.
/// - Every node reachable from `head` via `next` is a live allocation owned by this list,
///   and the `prev` links are the exact reverse of the `next` links.
/// - `len` equals the number of nodes in the list.
pub struct LinkedList<T> {
    head: Option<NonNull<Node<T>>>,
    tail: Option<NonNull<Node<T>>>,
    len: usize,
    // Tells the drop checker and variance checker that we own `Node<T>` values.
    marker: PhantomData<Box<Node<T>>>,
}

/// A cursor over the list. `cur == None` denotes the "ghost" position between
/// the back and the front of the list (this is also the position on an empty list).
///
/// Invariants:
/// - If `cur` is `Some`, it points to a live node owned by `list`.
/// - The cursor holds `&mut` to the list, so no other access to the nodes can happen
///   while the cursor exists.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    cur: Option<NonNull<Node<T>>>,
}

/// Invariants:
/// - `next` is `None` or points to a live node that is still owned by the borrowed list.
/// - The list cannot be mutated while the iterator exists (it holds `&'a`).
pub struct Iter<'a, T> {
    next: Option<NonNull<Node<T>>>,
    marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let cur = self.head;
        Cursor { list: self, cur }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let cur = self.tail;
        Cursor { list: self, cur }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.head,
            marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cur = self.head;
        while let Some(node) = cur {
            // SAFETY: `node` is a live allocation owned by this list (list invariant).
            // We reclaim each node exactly once, because we walk the list forward and
            // copy out `next` before the box is dropped.
            let boxed = unsafe { Box::from_raw(node.as_ptr()) };
            cur = boxed.next;
            // `boxed` is dropped here, dropping the element and freeing the node.
        }
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        let node = self.cur?;
        // SAFETY: `node` is live (cursor invariant). We have `&mut self`, which holds
        // `&mut` to the list, so no other reference to this element exists. The
        // returned reference is tied to the borrow of `self`.
        unsafe { Some(&mut (*node.as_ptr()).element) }
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        self.cur = match self.cur {
            // SAFETY: `node` is live (cursor invariant).
            Some(node) => unsafe { (*node.as_ptr()).next },
            None => self.list.head,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        self.cur = match self.cur {
            // SAFETY: `node` is live (cursor invariant).
            Some(node) => unsafe { (*node.as_ptr()).prev },
            None => self.list.tail,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.cur?;
        // SAFETY: `node` is live (cursor invariant). We unlink it from its neighbors,
        // fixing up head/tail, then reclaim the allocation exactly once with
        // `Box::from_raw`. After unlinking nothing else in the list refers to `node`,
        // so no dangling pointers remain.
        let node_box = unsafe {
            let prev = (*node.as_ptr()).prev;
            let next = (*node.as_ptr()).next;

            match prev {
                Some(p) => (*p.as_ptr()).next = next,
                None => {}
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = prev,
                None => {}
            }

            // Fix up list ends (these fields are safe to touch).
            if prev.is_none() {
                self.list.head = next;
            }
            if next.is_none() {
                self.list.tail = prev;
            }

            self.cur = next.or(prev);
            Box::from_raw(node.as_ptr())
        };
        self.list.len -= 1;
        let node = *node_box;
        Some(node.element)
    }

    pub fn insert_after(&mut self, element: T) {
        match self.cur {
            Some(cur) => {
                // SAFETY: `cur` is live (cursor invariant).
                let next = unsafe { (*cur.as_ptr()).next };
                let new = new_node(element, Some(cur), next);
                // SAFETY: `cur` is live, and `next` (if any) is live. We are only
                // rewiring pointers, and `new` is a freshly allocated node we own.
                unsafe {
                    (*cur.as_ptr()).next = Some(new);
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(new),
                        None => {}
                    }
                }
                if next.is_none() {
                    self.list.tail = Some(new);
                }
            }
            None => {
                // Ghost position: insert at the front of the list.
                let head = self.list.head;
                let new = new_node(element, None, head);
                // SAFETY: `head` (if any) is live, and `new` is freshly allocated.
                unsafe {
                    match head {
                        Some(h) => (*h.as_ptr()).prev = Some(new),
                        None => {}
                    }
                }
                if head.is_none() {
                    self.list.tail = Some(new);
                }
                self.list.head = Some(new);
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        match self.cur {
            Some(cur) => {
                // SAFETY: `cur` is live (cursor invariant).
                let prev = unsafe { (*cur.as_ptr()).prev };
                let new = new_node(element, prev, Some(cur));
                // SAFETY: `cur` is live, and `prev` (if any) is live. We are only
                // rewiring pointers, and `new` is a freshly allocated node we own.
                unsafe {
                    (*cur.as_ptr()).prev = Some(new);
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(new),
                        None => {}
                    }
                }
                if prev.is_none() {
                    self.list.head = Some(new);
                }
            }
            None => {
                // Ghost position: insert at the back of the list.
                let tail = self.list.tail;
                let new = new_node(element, tail, None);
                // SAFETY: `tail` (if any) is live, and `new` is freshly allocated.
                unsafe {
                    match tail {
                        Some(t) => (*t.as_ptr()).next = Some(new),
                        None => {}
                    }
                }
                if tail.is_none() {
                    self.list.head = Some(new);
                }
                self.list.tail = Some(new);
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: `node` is live and owned by the borrowed list (iterator invariant).
        // The list cannot be mutated while `'a` is alive, so the shared reference is valid.
        unsafe {
            self.next = (*node.as_ptr()).next;
            Some(&(*node.as_ptr()).element)
        }
    }
}

