// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

/// A node of the doubly linked list.
///
/// Invariants:
/// - `prev` and `next` are either `None` or point to live nodes owned by the same list.
/// - For every node `a` with `a.next == Some(b)`, `b.prev == Some(a)` holds, and vice versa.
struct Node<T> {
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
    element: T,
}

pub struct LinkedList<T> {
    /// Pointer to the first node, `None` if the list is empty.
    head: Option<NonNull<Node<T>>>,
    /// Pointer to the last node, `None` if the list is empty.
    tail: Option<NonNull<Node<T>>>,
    /// Number of nodes in the list.
    len: usize,
    /// Marker telling the compiler that the list owns `Node<T>` values
    /// (needed for drop check and keeps the type covariant in `T`).
    marker: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    /// The list this cursor operates on. Holding `&mut` ensures exclusive access.
    list: &'a mut LinkedList<T>,
    /// The current node, or `None` for the "ghost" position before the front
    /// and after the back (which is also the position of an empty list).
    current: Option<NonNull<Node<T>>>,
}

pub struct Iter<'a, T> {
    /// The node that will be yielded next, `None` when exhausted.
    current: Option<NonNull<Node<T>>>,
    marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.head;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.tail;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            current: self.head,
            marker: PhantomData,
        }
    }

    /// Allocate a new node holding `element` and link it between `prev` and `next`.
    /// Updates `head`, `tail` and `len` accordingly. Returns a pointer to the new node.
    ///
    /// # Safety
    /// - `prev` must be `None` or a live node of `self`, and it must be the node
    ///   directly before `next` in the list (`prev.next == next`).
    /// - `next` must be `None` or a live node of `self`, and `next.prev == prev`.
    /// - If `prev` is `None`, `next` must be `self.head` (or `None` if the list is empty).
    /// - If `next` is `None`, `prev` must be `self.tail` (or `None` if the list is empty).
    unsafe fn insert_node(
        &mut self,
        prev: Option<NonNull<Node<T>>>,
        next: Option<NonNull<Node<T>>>,
        element: T,
    ) -> NonNull<Node<T>> {
        let node = Box::new(Node {
            prev,
            next,
            element,
        });
        // SAFETY: Box::leak returns a valid, unique, non-null pointer to a freshly
        // allocated node that now lives until we free it in `remove_node` or `drop`.
        let ptr = NonNull::from(Box::leak(node));

        match prev {
            // SAFETY: caller guarantees `p` is a live node of this list, so we may
            // mutate it through a raw pointer while holding `&mut self`.
            Some(p) => unsafe { (*p.as_ptr()).next = Some(ptr) },
            None => self.head = Some(ptr),
        }
        match next {
            // SAFETY: caller guarantees `n` is a live node of this list.
            Some(n) => unsafe { (*n.as_ptr()).prev = Some(ptr) },
            None => self.tail = Some(ptr),
        }
        self.len += 1;
        ptr
    }

    /// Unlink the node `node` from the list, free it and return its element.
    ///
    /// # Safety
    /// - `node` must be a live node owned by `self`.
    /// - After this call, `node` and any copies of its pointer are dangling and
    ///   must not be used again.
    unsafe fn remove_node(&mut self, node: NonNull<Node<T>>) -> T {
        // SAFETY: caller guarantees `node` came from `Box::leak` in `insert_node`
        // and is still live, so reconstructing the Box and freeing it is sound.
        let boxed = unsafe { Box::from_raw(node.as_ptr()) };
        let Node {
            prev,
            next,
            element,
        } = *boxed;

        match prev {
            // SAFETY: `p` is a live node of this list (invariant of the links).
            Some(p) => unsafe { (*p.as_ptr()).next = next },
            None => self.head = next,
        }
        match next {
            // SAFETY: `n` is a live node of this list (invariant of the links).
            Some(n) => unsafe { (*n.as_ptr()).prev = prev },
            None => self.tail = prev,
        }
        self.len -= 1;
        element
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is either `None` or a live node of `self.list`.
        // We have `&mut self`, so no other reference to the element exists.
        self.current
            .map(|n| unsafe { &mut (*n.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `n` is a live node of the list, so reading its `next` link is valid.
            Some(n) => unsafe { (*n.as_ptr()).next },
            // From the ghost position, moving forward wraps to the front.
            None => self.list.head,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `n` is a live node of the list, so reading its `prev` link is valid.
            Some(n) => unsafe { (*n.as_ptr()).prev },
            // From the ghost position, moving backward wraps to the back.
            None => self.list.tail,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;
        // SAFETY: `node` is a live node of the list, so its links are readable.
        let (prev, next) = unsafe { ((*node.as_ptr()).prev, (*node.as_ptr()).next) };
        // Prefer the next element (closer to the back); fall back to the previous one.
        self.current = next.or(prev);
        // SAFETY: `node` is a live node of `self.list`, and after this call we no
        // longer use it: the cursor was just moved to `next` or `prev`.
        Some(unsafe { self.list.remove_node(node) })
    }

    pub fn insert_after(&mut self, element: T) {
        match self.current {
            Some(n) => {
                // SAFETY: `n` is a live node of the list.
                let next = unsafe { (*n.as_ptr()).next };
                // SAFETY: `n` is the node directly before `next`, and both are
                // live nodes of the list (or `next` is None, meaning `n` is the tail).
                unsafe {
                    self.list.insert_node(Some(n), next, element);
                }
            }
            None => {
                // Ghost position: inserting "after" it means at the front.
                let head = self.list.head;
                // SAFETY: `head` is `self.list.head`, which is what the precondition
                // requires when `prev` is `None`.
                unsafe {
                    self.list.insert_node(None, head, element);
                }
            }
        }
    }

    pub fn insert_before(&mut self, element: T) {
        match self.current {
            Some(n) => {
                // SAFETY: `n` is a live node of the list.
                let prev = unsafe { (*n.as_ptr()).prev };
                // SAFETY: `prev` is the node directly before `n` (or None if `n` is
                // the head), and `n` is a live node of the list.
                unsafe {
                    self.list.insert_node(prev, Some(n), element);
                }
            }
            None => {
                // Ghost position: inserting "before" it means at the back.
                let tail = self.list.tail;
                // SAFETY: `tail` is `self.list.tail`, which is what the precondition
                // requires when `next` is `None`.
                unsafe {
                    self.list.insert_node(tail, None, element);
                }
            }
        }
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.current?;
        // SAFETY: `node` is a live node of the list. The list is borrowed immutably
        // for `'a` (through `iter(&self)`), so the node will not be freed or mutated
        // while this iterator exists.
        unsafe {
            let n = &*node.as_ptr();
            self.current = n.next;
            Some(&n.element)
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cur = self.head.take();
        while let Some(node) = cur {
            // SAFETY: every node in the list was allocated with Box::leak and is
            // owned by the list, so reconstructing and dropping each Box exactly once
            // is sound. We read `next` before the Box is dropped.
            unsafe {
                let boxed = Box::from_raw(node.as_ptr());
                cur = boxed.next;
            }
        }
        self.tail = None;
        self.len = 0;
    }
}

// SAFETY: The list owns its nodes exclusively, just like a `Box<Node<T>>` would,
// so it is safe to send it to another thread if `T` itself can be sent.
unsafe impl<T: Send> Send for LinkedList<T> {}

// SAFETY: Shared references to the list only allow shared access to the elements
// (`Iter` yields `&T`), so sharing is safe if `T` is `Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: The cursor has exclusive access to the list through `&mut`, so it can be
// sent across threads if `T` can be sent.
unsafe impl<T: Send> Send for Cursor<'_, T> {}

// SAFETY: A shared reference to the cursor only exposes `&T`-like access through
// methods that take `&self`, so sharing is safe if `T` is `Sync`.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: `Iter` behaves like a `&T` iterator, so it is `Send` when `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}

// SAFETY: `Iter` behaves like a `&T` iterator, so it is `Sync` when `T: Sync`.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}
