mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

/// A node of the doubly linked list.
///
/// Invariants (maintained by `LinkedList` and `Cursor`):
/// - `prev` is `None` iff this node is the front of the list; otherwise it points
///   to the node directly before this one.
/// - `next` is `None` iff this node is the back of the list; otherwise it points
///   to the node directly after this one.
/// - Every node is owned by exactly one list and was allocated via `Box`.
struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

/// Allocates a new, unlinked node and returns a pointer that owns it.
/// The node must eventually be freed with `Box::from_raw`, which only happens in `Cursor::take`.
fn new_node<T>(element: T) -> NonNull<Node<T>> {
    NonNull::from(Box::leak(Box::new(Node {
        element,
        prev: None,
        next: None,
    })))
}

pub struct LinkedList<T> {
    // Invariants:
    // - `head` is `None` iff the list is empty, otherwise it points to the front node.
    // - `tail` is `None` iff the list is empty, otherwise it points to the back node.
    // - `len` is the exact number of nodes reachable from `head` via `next`.
    head: Option<NonNull<Node<T>>>,
    tail: Option<NonNull<Node<T>>>,
    len: usize,
    // Tells the drop checker that the list owns `T` values through nodes.
    marker: PhantomData<Box<Node<T>>>,
}

/// A cursor over a `LinkedList`. It is either positioned on an element, or on the
/// "ghost" position between the back and the front of the list (`current == None`).
///
/// Invariant: `current` is either `None` or points to a node currently linked into `list`.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Option<NonNull<Node<T>>>,
}

/// An iterator over shared references to the elements of a `LinkedList`.
///
/// Invariant: `current` is either `None` or points to a node in the list that
/// cannot be modified or freed while `'a` is alive (the list is borrowed for `'a`).
pub struct Iter<'a, T> {
    current: Option<NonNull<Node<T>>>,
    marker: PhantomData<&'a T>,
}

// SAFETY: The list uniquely owns its nodes, so sending it to another thread is
// sound as long as the elements themselves can be sent.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: Shared access to the list only yields `&T`, so sharing it across threads
// is sound as long as the elements are `Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: A `Cursor` has exclusive access to the list it borrows, so it behaves like `&mut LinkedList<T>`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
// SAFETY: A `Cursor` behaves like `&mut LinkedList<T>`, which is `Sync` when `T: Sync`.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: `Iter` behaves like `&'a LinkedList<T>`, which is `Send` when `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
// SAFETY: `Iter` behaves like `&'a LinkedList<T>`, which is `Sync` when `T: Sync`.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            marker: PhantomData,
        }
    }

