    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.head;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.tail;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            current: self.head,
            marker: PhantomData,
        }
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        let node = self.current?;
        // SAFETY: `node` is linked into `self.list` (cursor invariant), and the list is
        // exclusively borrowed by this cursor. The returned reference is bounded by
        // `&mut self`, so no other reference to the element can coexist with it.
        unsafe { Some(&mut (*node.as_ptr()).element) }
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `node` is a live node of the list (cursor invariant), so reading its `next` link is valid.
            Some(node) => unsafe { (*node.as_ptr()).next },
            // Ghost position: wrap around to the front (stays `None` if the list is empty).
            None => self.list.head,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `node` is a live node of the list (cursor invariant), so reading its `prev` link is valid.
            Some(node) => unsafe { (*node.as_ptr()).prev },
            // Ghost position: wrap around to the back (stays `None` if the list is empty).
            None => self.list.tail,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;
        let node_ptr = node.as_ptr();

        // SAFETY: `node` is a live node linked into `self.list` (cursor invariant).
        // We read its links, relink its neighbours around it, and then reclaim the
        // allocation exactly once with `Box::from_raw`. The node is no longer reachable
        // from the list after the relinking, so no dangling pointers remain.
        unsafe {
            let prev = (*node_ptr).prev;
            let next = (*node_ptr).next;

            match prev {
                Some(p) => (*p.as_ptr()).next = next,
                None => self.list.head = next,
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = prev,
                None => self.list.tail = prev,
            }

            self.list.len -= 1;
            // Move towards the back if possible, otherwise towards the front.
            self.current = next.or(prev);

            let boxed = *Box::from_raw(node_ptr);
            Some(boxed.element)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let new = new_node(element);
        let new_ptr = new.as_ptr();

        match self.current {
            Some(cur) => {
                let cur_ptr = cur.as_ptr();
                // SAFETY: `cur` is a live node of the list (cursor invariant), and `new`
                // is a freshly allocated, unlinked node that we exclusively own.
                // We splice `new` between `cur` and its old successor, updating every
                // link that changes so the list invariants are preserved.
                unsafe {
                    let next = (*cur_ptr).next;
                    (*new_ptr).prev = Some(cur);
                    (*new_ptr).next = next;
                    (*cur_ptr).next = Some(new);
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(new),
                        None => self.list.tail = Some(new),
                    }
                }
            }
            None => {
                // Ghost position: the element goes after the ghost, i.e. at the front.
                let old_head = self.list.head;
                // SAFETY: `new` is exclusively owned and unlinked. `old_head`, if present,
                // is a live node of the list, so we may update its `prev` link.
                unsafe {
                    (*new_ptr).next = old_head;
                    match old_head {
                        Some(h) => (*h.as_ptr()).prev = Some(new),
                        None => self.list.tail = Some(new),
                    }
                }
                self.list.head = Some(new);
            }
        }

        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = new_node(element);
        let new_ptr = new.as_ptr();

        match self.current {
            Some(cur) => {
                let cur_ptr = cur.as_ptr();
                // SAFETY: `cur` is a live node of the list (cursor invariant), and `new`
                // is a freshly allocated, unlinked node that we exclusively own.
                // We splice `new` between `cur`'s old predecessor and `cur`, updating every
                // link that changes so the list invariants are preserved.
                unsafe {
                    let prev = (*cur_ptr).prev;
                    (*new_ptr).prev = prev;
                    (*new_ptr).next = Some(cur);
                    (*cur_ptr).prev = Some(new);
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(new),
                        None => self.list.head = Some(new),
                    }
                }
            }
            None => {
                // Ghost position: the element goes before the ghost, i.e. at the back.
                let old_tail = self.list.tail;
                // SAFETY: `new` is exclusively owned and unlinked. `old_tail`, if present,
                // is a live node of the list, so we may update its `next` link.
                unsafe {
                    (*new_ptr).prev = old_tail;
                    match old_tail {
                        Some(t) => (*t.as_ptr()).next = Some(new),
                        None => self.list.head = Some(new),
                    }
                }
                self.list.tail = Some(new);
            }
        }

        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.current?;
        // SAFETY: `node` is a live node of the list. The list is immutably borrowed for `'a`
        // (via `LinkedList::iter`), so the node cannot be modified or freed while `'a` is alive.
        unsafe {
            let node_ref: &'a Node<T> = &*node.as_ptr();
            self.current = node_ref.next;
            Some(&node_ref.element)
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Repeatedly remove the front element through a cursor; each `take` frees one node,
        // so every node is freed exactly once.
        while self.cursor_front().take().is_some() {}
    }
}
