const isPalindrome = (number) => {
  const digits = String(number);
  return digits === [...digits].reverse().join('');
};

const byFirstFactor = ([a], [b]) => a - b;

// Smallest palindromic product of two factors within [minFactor, maxFactor],
// along with every factor pair (a <= b) that produces it.
const findSmallest = (minFactor, maxFactor) => {
  let best = null;
  let factors = [];

  for (let a = minFactor; a <= maxFactor; a++) {
    // Every product in this row is at least a * a, so once that exceeds the
    // best palindrome, no later row can help.
    if (best !== null && a * a > best) {
      break;
    }

    for (let b = a; b <= maxFactor; b++) {
      const product = a * b;

      // Products only grow as b grows, so the rest of this row cannot help.
      if (best !== null && product > best) {
        break;
      }

      if (isPalindrome(product)) {
        if (best === null || product < best) {
          best = product;
          factors = [[a, b]];
        } else if (product === best) {
          factors.push([a, b]);
        }
      }
    }
  }

  return { value: best, factors: factors.sort(byFirstFactor) };
};

// Largest palindromic product of two factors within [minFactor, maxFactor],
// along with every factor pair (a <= b) that produces it.
const findLargest = (minFactor, maxFactor) => {
  let best = null;
  let factors = [];

  for (let a = maxFactor; a >= minFactor; a--) {
    // Products in this row and in all following rows (which have smaller a)
    // are at most a * maxFactor. Once that is below the best palindrome, stop.
    if (best !== null && a * maxFactor < best) {
      break;
    }

    for (let b = maxFactor; b >= a; b--) {
      const product = a * b;

      // Products only shrink as b shrinks, so the rest of this row cannot help.
      if (best !== null && product < best) {
        break;
      }

      if (isPalindrome(product)) {
        if (best === null || product > best) {
          best = product;
          factors = [[a, b]];
        } else if (product === best) {
          factors.push([a, b]);
        }
      }
    }
  }

  return { value: best, factors: factors.sort(byFirstFactor) };
};

// Finds the smallest and largest palindromic products of factors in
// the inclusive range [minFactor, maxFactor].
export class Palindromes {
  static generate({ minFactor, maxFactor }) {
    if (minFactor > maxFactor) {
      throw new Error('min must be <= max');
    }

    return {
      smallest: findSmallest(minFactor, maxFactor),
      largest: findLargest(minFactor, maxFactor),
    };
  }
}
