    if (value !== null && a * a > value) break;

    for (let b = a; b <= maxFactor; b++) {
      const product = a * b;
      // Products only grow as `b` grows, so no later `b` can match the current value.
      if (value !== null && product > value) break;
      if (!isPalindrome(product)) continue;

      if (value === null || product < value) {
        value = product;
        factors = [[a, b]];
      } else if (product === value) {
        factors.push([a, b]);
      }
    }
  }

  return { value, factors: sortFactors(factors) };
};

