The stub needs a real implementation. Treating each stone as an edge between its two dot values turns the problem into finding an Eulerian circuit. A valid chain exists only if every dot value appears an even number of times (a double counts twice) and all stones are connected. I check both conditions, then use Hierholzer's algorithm to build the chain. If any stone is left unused, the stones are disconnected and `ChainNotFoundException` is thrown. An empty input returns an empty chain.

I couldn't see the `Domino` and `ChainNotFoundException` sources, so the code assumes `Domino(int, int)`, `getLeft()`, `getRight()`, and a `ChainNotFoundException(String)` constructor. If your versions use different names, only those call sites need to change.

src/main/java/Dominoes.java
```
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Dominoes {

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        List<Domino> chain = new ArrayList<>();
        if (inputDominoes == null || inputDominoes.isEmpty()) {
            return chain;
        }

        int count = inputDominoes.size();
        Map<Integer, Integer> degrees = new HashMap<>();
        Map<Integer, Deque<Integer>> adjacency = new HashMap<>();

        for (int i = 0; i < count; i++) {
            Domino domino = inputDominoes.get(i);
            int left = domino.getLeft();
            int right = domino.getRight();
            degrees.merge(left, 1, Integer::sum);
            degrees.merge(right, 1, Integer::sum);
            adjacency.computeIfAbsent(left, k -> new ArrayDeque<>()).add(i);
            adjacency.computeIfAbsent(right, k -> new ArrayDeque<>()).add(i);
        }

        for (int degree : degrees.values()) {
            if (degree % 2 != 0) {
                throw new ChainNotFoundException("no closed chain: a dot value appears an odd number of times");
            }
        }

        boolean[] used = new boolean[count];
        Deque<Step> stack = new ArrayDeque<>();
        List<Domino> reversedChain = new ArrayList<>(count);
        stack.push(new Step(inputDominoes.get(0).getLeft(), null));

        while (!stack.isEmpty()) {
            Step current = stack.peek();
            Deque<Integer> edges = adjacency.get(current.vertex);

            while (!edges.isEmpty() && used[edges.peek()]) {
                edges.pop();
            }

            if (edges.isEmpty()) {
                stack.pop();
                if (current.edge != null) {
                    reversedChain.add(current.edge);
                }
            } else {
                int index = edges.pop();
                used[index] = true;
                Domino original = inputDominoes.get(index);
                boolean forward = original.getLeft() == current.vertex;
                int next = forward ? original.getRight() : original.getLeft();
                Domino traversed = forward ? original : new Domino(current.vertex, next);
                stack.push(new Step(next, traversed));
            }
        }

        if (reversedChain.size() != count) {
            throw new ChainNotFoundException("no chain: dominoes are not all connected");
        }

        Collections.reverse(reversedChain);
        return reversedChain;
    }

    private static final class Step {
        private final int vertex;
        private final Domino edge;

        Step(int vertex, Domino edge) {
            this.vertex = vertex;
            this.edge = edge;
        }
    }

