import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Dominoes {

    /*
     * Treat each stone as an edge between its two dot values. A chain is then a closed walk
     * that uses every edge exactly once (an Eulerian circuit), which exists only if every dot
     * value occurs an even number of times and all stones are connected. Hierholzer's
     * algorithm builds that walk.
     */
    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        if (inputDominoes.isEmpty()) {
            return new ArrayList<>();
        }

        int stoneCount = inputDominoes.size();
        int[][] stoneDots = new int[stoneCount][];
        Map<Integer, Deque<Integer>> stonesByDot = new HashMap<>();
        for (int i = 0; i < stoneCount; i++) {
            Domino stone = inputDominoes.get(i);
            stoneDots[i] = new int[] {stone.getLeft(), stone.getRight()};
            for (int dot : stoneDots[i]) {
                stonesByDot.computeIfAbsent(dot, key -> new ArrayDeque<>()).add(i);
            }
        }

        // Each dot half is one entry in its dot's list (a double adds two), so an odd size means no closed chain.
        for (Deque<Integer> stones : stonesByDot.values()) {
            if (stones.size() % 2 != 0) {
                throw new ChainNotFoundException("every dot value must occur an even number of times");
            }
        }

        // Walk from dot to dot using unused stones. When stuck, backtrack and record the stone
        // that led to each dead end; the recorded stones in reverse order form the chain.
        boolean[] used = new boolean[stoneCount];
        Deque<Visit> walk = new ArrayDeque<>();
        Deque<Domino> chain = new ArrayDeque<>();
        walk.push(new Visit(stoneDots[0][0], null));

        while (!walk.isEmpty()) {
            Visit current = walk.peek();
            int index = nextUnusedStone(stonesByDot.get(current.dot), used);
            if (index >= 0) {
                used[index] = true;
                boolean flipped = stoneDots[index][0] != current.dot;
                int nextDot = flipped ? stoneDots[index][0] : stoneDots[index][1];
                Domino oriented = flipped
                        ? new Domino(current.dot, nextDot)
                        : inputDominoes.get(index);
                walk.push(new Visit(nextDot, oriented));
            } else {
                walk.pop();
                if (current.arrivedBy != null) {
                    chain.push(current.arrivedBy);
                }
            }
        }

        // Any stone not reached from the walk is in a separate group and cannot be chained.
        if (chain.size() != stoneCount) {
            throw new ChainNotFoundException("the stones do not form a single connected chain");
        }
        return new ArrayList<>(chain);
    }

    // Returns the index of the first unused stone in the candidates, discarding used ones, or -1 if none.
    private static int nextUnusedStone(Deque<Integer> candidates, boolean[] used) {
        while (!candidates.isEmpty()) {
            int index = candidates.peek();
            if (!used[index]) {
                return index;
            }
            candidates.pop();
        }
        return -1;
    }

    // A dot reached during the walk, and the stone that reached it, oriented in the direction walked.
    // The starting dot has no stone.
    private static final class Visit {
        final int dot;
        final Domino arrivedBy;

        Visit(int dot, Domino arrivedBy) {
            this.dot = dot;
            this.arrivedBy = arrivedBy;
        }
    }

}
