            Domino start = inputDominoes.get(i);

            List<Domino> remaining = new ArrayList<>(inputDominoes);
            remaining.remove(i);

            Domino forward = start;
            Domino backward = new Domino(start.getLow(), start.getHigh());

            Domino[] orientations = {forward, backward};
            for (Domino first : orientations) {
                List<Domino> chain = new ArrayList<>();
                chain.add(first);
                if (extend(chain, remaining)) {
                    return chain;
                }
            }
        }

        throw new ChainNotFoundException("No valid domino chain could be formed from the given dominoes");
    }

    /**
     * Recursively attempts to extend the chain with the remaining dominoes.
     * On success the chain list contains the full solution.
     */
    private boolean extend(List<Domino> chain, List<Domino> remaining) {
        if (remaining.isEmpty()) {
            Domino firstDomino = chain.get(0);
            Domino lastDomino = chain.get(chain.size() - 1);
            return firstDomino.getHigh() == lastDomino.getLow();
        }

        int end = chain.get(chain.size() - 1).getLow();

        for (int i = 0; i < remaining.size(); i++) {
            Domino candidate = remaining.get(i);

            if (candidate.getHigh() != end && candidate.getLow() != end) {
                continue;
            }

            if (isDuplicateOfEarlier(remaining, i)) {
                continue;
            }

            Domino oriented = (candidate.getHigh() == end)
                    ? candidate
                    : new Domino(candidate.getLow(), candidate.getHigh());

            List<Domino> next = new ArrayList<>(remaining);
            next.remove(i);

            chain.add(oriented);
            if (extend(chain, next)) {
                return true;
            }
            chain.remove(chain.size() - 1);
        }

        return false;
    }

    /**
     * Returns true if an earlier stone in the list is the same tile as the one at
     * the given index (in either orientation). Such a stone would lead to an
     * identical search branch, so it can be skipped.
     */
    private boolean isDuplicateOfEarlier(List<Domino> dominoes, int index) {
        Domino d = dominoes.get(index);
        for (int j = 0; j < index; j++) {
            Domino e = dominoes.get(j);
            boolean sameOrientation = e.getHigh() == d.getHigh() && e.getLow() == d.getLow();
            boolean reversed = e.getHigh() == d.getLow() && e.getLow() == d.getHigh();
            if (sameOrientation || reversed) {
                return true;
            }
        }
        return false;
