import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Dominoes {

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        List<Domino> result = new ArrayList<>();
        if (inputDominoes == null || inputDominoes.isEmpty()) {
            return result;
        }

        // Build adjacency: value -> list of edge indices
        Map<Integer, List<Integer>> adj = new HashMap<>();
        Map<Integer, Integer> degree = new HashMap<>();
        int n = inputDominoes.size();
        for (int i = 0; i < n; i++) {
            Domino d = inputDominoes.get(i);
            int a = d.getLeft();
            int b = d.getRight();
            adj.computeIfAbsent(a, k -> new ArrayList<>()).add(i);
            adj.computeIfAbsent(b, k -> new ArrayList<>()).add(i);
            degree.merge(a, 1, Integer::sum);
            degree.merge(b, 1, Integer::sum);
        }

        // Every vertex must have even degree for an Eulerian circuit
        for (int deg : degree.values()) {
            if (deg % 2 != 0) {
                throw new ChainNotFoundException("No valid chain: odd vertex degree");
            }
        }

        // Hierholzer's algorithm, starting at the first domino's left value
        boolean[] used = new boolean[n];
        Map<Integer, Integer> pointer = new HashMap<>();
        int start = inputDominoes.get(0).getLeft();
        List<int[]> circuit = new ArrayList<>(); // each entry: {edgeIndex, fromVertex, toVertex}
        java.util.Deque<Object[]> stack = new java.util.ArrayDeque<>();
        stack.push(new Object[]{start, -1, -1}); // vertex, edge index, from vertex

        while (!stack.isEmpty()) {
            Object[] top = stack.peek();
            int v = (Integer) top[0];
            List<Integer> edges = adj.getOrDefault(v, new ArrayList<>());
            int p = pointer.getOrDefault(v, 0);
            while (p < edges.size() && used[edges.get(p)]) {
                p++;
            }
            pointer.put(v, p);
            if (p < edges.size()) {
                int e = edges.get(p);
                used[e] = true;
                Domino d = inputDominoes.get(e);
                int other = (d.getLeft() == v) ? d.getRight() : d.getLeft();
                stack.push(new Object[]{other, e, v});
            } else {
                stack.pop();
                if ((Integer) top[1] != -1) {
                    circuit.add(new int[]{(Integer) top[1], (Integer) top[2], v});
                }
            }
        }

        // Check all edges were used (connectivity)
        if (circuit.size() != n) {
            throw new ChainNotFoundException("No valid chain: dominoes are not connected");
        }

        // circuit was built in reverse order; reverse it and orient each domino
        java.util.Collections.reverse(circuit);
        for (int[] step : circuit) {
            Domino original = inputDominoes.get(step[0]);
            int from = step[1];
            int to = step[2];
            if (original.getLeft() == from && original.getRight() == to) {
                result.add(new Domino(from, to));
            } else {
                result.add(new Domino(to, from));
            }
        }
        return result;
    }

}
