import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Stack;

class Dominoes {

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        List<Domino> result = new ArrayList<>();
        if (inputDominoes == null || inputDominoes.isEmpty()) {
            return result;
        }

        int n = inputDominoes.size();

        // Build adjacency: vertex (dot value) -> indexes of dominoes touching it
        Map<Integer, List<Integer>> adjacency = new HashMap<>();
        for (int i = 0; i < n; i++) {
            Domino d = inputDominoes.get(i);
            adjacency.computeIfAbsent(d.getLeft(), k -> new ArrayList<>()).add(i);
            adjacency.computeIfAbsent(d.getRight(), k -> new ArrayList<>()).add(i);
        }

        // Hierholzer's algorithm for an Eulerian circuit
        int start = inputDominoes.get(0).getLeft();
        boolean[] used = new boolean[n];
        Map<Integer, Integer> pointer = new HashMap<>();
        Stack<Frame> stack = new Stack<>();
        stack.push(new Frame(start, null));
        List<Domino> reversed = new ArrayList<>();

        while (!stack.isEmpty()) {
            int vertex = stack.peek().vertex;
            List<Integer> edges = adjacency.get(vertex);
            int p = pointer.getOrDefault(vertex, 0);
            while (p < edges.size() && used[edges.get(p)]) {
                p++;
            }
            if (p < edges.size()) {
                int idx = edges.get(p);
                pointer.put(vertex, p + 1);
                used[idx] = true;
                Domino d = inputDominoes.get(idx);
                if (d.getLeft() == vertex) {
                    stack.push(new Frame(d.getRight(), d));
                } else {
                    stack.push(new Frame(d.getLeft(), new Domino(d.getRight(), d.getLeft())));
                }
            } else {
                Frame finished = stack.pop();
                if (finished.edge != null) {
                    reversed.add(finished.edge);
                }
            }
        }

        Collections.reverse(reversed);
        result = reversed;

        // Validate the resulting chain
        if (result.size() != n) {
            throw new ChainNotFoundException("No chain can be formed with all dominoes");
        }
        for (int i = 1; i < n; i++) {
            if (result.get(i - 1).getRight() != result.get(i).getLeft()) {
                throw new ChainNotFoundException("Dominoes do not connect");
            }
        }
        if (result.get(0).getLeft() != result.get(n - 1).getRight()) {
            throw new ChainNotFoundException("First and last dots do not match");
        }

        return result;
    }

    private static final class Frame {
        final int vertex;
        final Domino edge;

        Frame(int vertex, Domino edge) {
            this.vertex = vertex;
            this.edge = edge;
        }
    }

