import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

class PythagoreanTriplet {

    private final int a;
    private final int b;
    private final int c;

    PythagoreanTriplet(int a, int b, int c) {
        this.a = a;
        this.b = b;
        this.c = c;
    }

    static TripletListBuilder makeTripletsList() {
        return new TripletListBuilder();
    }

    int getA() {
        return a;
    }

    int getB() {
        return b;
    }

    int getC() {
        return c;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) {
            return true;
        }
        if (!(obj instanceof PythagoreanTriplet)) {
            return false;
        }
        PythagoreanTriplet other = (PythagoreanTriplet) obj;
        return a == other.a && b == other.b && c == other.c;
    }

    @Override
    public int hashCode() {
        return Objects.hash(a, b, c);
    }

    @Override
    public String toString() {
        return String.format("{%d, %d, %d}", a, b, c);
    }

    static class TripletListBuilder {

        // null means the corresponding constraint has not been set
        private Integer sum;
        private Integer maxFactor;

        TripletListBuilder thatSumTo(int sum) {
            this.sum = sum;
            return this;
        }

        TripletListBuilder withFactorsLessThanOrEqualTo(int maxFactor) {
            this.maxFactor = maxFactor;
            return this;
        }

        List<PythagoreanTriplet> build() {
            if (sum != null) {
                return tripletsWithSum(sum);
            }
            if (maxFactor != null) {
                return tripletsWithFactorsUpTo(maxFactor);
            }
            throw new IllegalStateException(
                    "Specify thatSumTo and/or withFactorsLessThanOrEqualTo: "
                            + "without a bound there are infinitely many triplets.");
        }

        // Since a < b < c and a + b + c = targetSum, 3a < targetSum.
        // Substituting c = targetSum - a - b into a² + b² = c² and solving for b gives
        // b = targetSum * (targetSum - 2a) / (2 * (targetSum - a)), so each a needs
        // only a single division to find its matching b.
        private List<PythagoreanTriplet> tripletsWithSum(long targetSum) {
            List<PythagoreanTriplet> triplets = new ArrayList<>();
            for (long a = 1; 3 * a < targetSum; a++) {
                long numerator = targetSum * (targetSum - 2 * a);
                long denominator = 2 * (targetSum - a);
                if (numerator % denominator != 0) {
                    continue;
                }
                long b = numerator / denominator;
                long c = targetSum - a - b;
                if (a < b && b < c && a * a + b * b == c * c && fitsFactorLimit(c)) {
                    triplets.add(new PythagoreanTriplet((int) a, (int) b, (int) c));
                }
            }
            return triplets;
        }

        // Without a sum, the factor limit is the only bound: test every pair a < b and
        // keep those where a² + b² is a perfect square whose root c is within the limit.
        private static List<PythagoreanTriplet> tripletsWithFactorsUpTo(long limit) {
            List<PythagoreanTriplet> triplets = new ArrayList<>();
            long limitSquared = limit * limit;
            for (long a = 1; a <= limit; a++) {
                for (long b = a + 1; b <= limit; b++) {
                    long cSquared = a * a + b * b;
                    if (cSquared > limitSquared) {
                        break; // a larger b only makes c bigger, so stop for this a
                    }
                    long c = integerSquareRoot(cSquared);
                    if (c * c == cSquared) {
                        triplets.add(new PythagoreanTriplet((int) a, (int) b, (int) c));
                    }
                }
            }
            return triplets;
        }

        // Floor of the square root of n >= 0, corrected for floating-point rounding
        private static long integerSquareRoot(long n) {
            long root = (long) Math.sqrt(n);
            while (root * root > n) {
                root--;
            }
            while ((root + 1) * (root + 1) <= n) {
                root++;
            }
            return root;
        }

        // c is the longest side, so checking it also covers a and b
        private boolean fitsFactorLimit(long c) {
            return maxFactor == null || c <= maxFactor;
        }

    }

}
