```
//! An internal DSL for describing graphs, modeled on Graphviz's DOT language.
//!
//! DOT source such as
//!
//! ```text
//! graph { graph [bgcolor="yellow"] a [color="red"] b [color="blue"] a -- b [color="green"] }
//! ```
//!
//! is written in Rust as chained builder calls:
//!
//! ```text
//! Graph::new()
//!     .with_attrs(&[("bgcolor", "yellow")])
//!     .with_nodes(&[
//!         Node::new("a").with_attrs(&[("color", "red")]),
//!         Node::new("b").with_attrs(&[("color", "blue")]),
//!     ])
//!     .with_edges(&[Edge::new("a", "b").with_attrs(&[("color", "green")])])
//! ```

/// The entry point of the DSL: `Graph`, plus re-exports of `Node` and `Edge`.
pub mod graph {
    use std::collections::HashMap;

    use crate::graph_items::attrs_from_pairs;
    pub use crate::graph_items::{edge::Edge, node::Node};

    /// An undirected graph with optional graph-level attributes.
    ///
    /// Start with `Graph::new()` and chain any of the `with_*` builder methods.
    #[derive(Debug, Clone, Default, PartialEq, Eq)]
    pub struct Graph {
        pub nodes: Vec<Node>,
        pub edges: Vec<Edge>,
        pub attrs: HashMap<String, String>,
    }

    impl Graph {
        /// Creates an empty graph.
        pub fn new() -> Self {
            Self::default()
        }

        /// Adds nodes to the graph. A node whose name is already present has
        /// the new attributes merged into it rather than being duplicated.
        pub fn with_nodes(mut self, nodes: &[Node]) -> Self {
            for node in nodes {
                match self.node_index(&node.name) {
                    Some(index) => self.nodes[index].attrs.extend(node.attrs.clone()),
                    None => self.nodes.push(node.clone()),
                }
            }
            self
        }

        /// Adds edges to the graph. Endpoints that are not yet nodes are created
        /// implicitly, just as Graphviz does.
        pub fn with_edges(mut self, edges: &[Edge]) -> Self {
            for edge in edges {
                self.ensure_node(&edge.from);
                self.ensure_node(&edge.to);
                self.edges.push(edge.clone());
            }
            self
        }

        /// Sets graph-level attributes such as `bgcolor`. Existing keys are overwritten.
        pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
            self.attrs.extend(attrs_from_pairs(attrs));
            self
        }

        /// Returns the node with the given name, if it exists.
        pub fn get_node(&self, name: &str) -> Option<&Node> {
            self.nodes.iter().find(|node| node.name == name)
        }

        /// Returns the value of a graph-level attribute, if set.
        pub fn get_attr(&self, key: &str) -> Option<&str> {
            self.attrs.get(key).map(String::as_str)
        }

        fn node_index(&self, name: &str) -> Option<usize> {
            self.nodes.iter().position(|node| node.name == name)
        }

        fn ensure_node(&mut self, name: &str) {
            if self.node_index(name).is_none() {
                self.nodes.push(Node::new(name));
            }
        }
    }
}

/// The building blocks of a graph: `Node` and `Edge`, each with its own attributes.
pub mod graph_items {
    use std::collections::HashMap;

    /// Converts `(key, value)` pairs into an owned attribute map.
    /// Later pairs overwrite earlier ones with the same key.
    pub(crate) fn attrs_from_pairs(pairs: &[(&str, &str)]) -> HashMap<String, String> {
        pairs
            .iter()
            .map(|&(key, value)| (key.to_string(), value.to_string()))
            .collect()
    }

    pub mod node {
        use std::collections::HashMap;

        use super::attrs_from_pairs;

        /// A named node, like `a [color="red"]` in DOT.
        #[derive(Debug, Clone, PartialEq, Eq)]
        pub struct Node {
            pub name: String,
            pub attrs: HashMap<String, String>,
        }

        impl Node {
            /// Creates a node with the given name and no attributes.
            pub fn new(name: &str) -> Self {
                Node {
                    name: name.to_string(),
                    attrs: HashMap::new(),
                }
            }

            /// Adds attributes to the node. Existing keys are overwritten.
            pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                self.attrs.extend(attrs_from_pairs(attrs));
                self
            }

            /// Returns the value of an attribute, if set.
            pub fn get_attr(&self, key: &str) -> Option<&str> {
                self.attrs.get(key).map(String::as_str)
            }
        }
    }

    pub mod edge {
        use std::collections::HashMap;

        use super::attrs_from_pairs;

        /// An edge between two nodes, like `a -- b [color="green"]` in DOT.
        #[derive(Debug, Clone, PartialEq, Eq)]
        pub struct Edge {
            pub from: String,
            pub to: String,
            pub attrs: HashMap<String, String>,
        }

        impl Edge {
            /// Creates an edge between `from` and `to` with no attributes.
            pub fn new(from: &str, to: &str) -> Self {
                Edge {
                    from: from.to_string(),
                    to: to.to_string(),
                    attrs: HashMap::new(),
                }
            }

            /// Adds attributes to the edge. Existing keys are overwritten.
            pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                self.attrs.extend(attrs_from_pairs(attrs));
                self
            }

            /// Returns the value of an attribute, if set.
            pub fn get_attr(&self, key: &str) -> Option<&str> {
                self.attrs.get(key).map(String::as_str)
            }
        }
    }
}

