mod tests {
    use crate::graph::{Edge, Graph, Node};

    #[test]
    fn new_graph_is_empty() {
        let graph = Graph::new();

        assert_eq!(graph, Graph::default());
        assert!(graph.nodes.is_empty());
        assert!(graph.edges.is_empty());
        assert!(graph.attrs.is_empty());
    }

    #[test]
    fn builds_the_graphviz_example() {
        let graph = Graph::new()
            .with_attrs(&[("bgcolor", "yellow")])
            .with_nodes(&[
                Node::new("a").with_attrs(&[("color", "red")]),
                Node::new("b").with_attrs(&[("color", "blue")]),
            ])
            .with_edges(&[Edge::new("a", "b").with_attrs(&[("color", "green")])]);

        assert_eq!(graph.get_attr("bgcolor"), Some("yellow"));
        assert_eq!(graph.nodes.len(), 2);
        assert_eq!(
            graph.get_node("a").and_then(|node| node.get_attr("color")),
            Some("red")
        );
        assert_eq!(
            graph.get_node("b").and_then(|node| node.get_attr("color")),
            Some("blue")
        );
        assert_eq!(graph.edges.len(), 1);
        assert_eq!(graph.edges[0].get_attr("color"), Some("green"));
    }

    #[test]
    fn edges_create_missing_nodes() {
        let graph = Graph::new().with_edges(&[Edge::new("x", "y")]);

        assert_eq!(graph.nodes.len(), 2);
        assert!(graph.get_node("x").is_some());
        assert!(graph.get_node("y").is_some());
    }

    #[test]
    fn edges_reuse_existing_nodes() {
        let graph = Graph::new()
