src/main/java/House.java
```
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

class House {

    // The item introduced by each verse, indexed by verse number - 1.
    // Entry 0 is the house itself, which closes every verse.
    private static final String[] ITEMS = {
        "house that Jack built",
        "malt",
        "rat",
        "cat",
        "dog",
        "cow with the crumpled horn",
        "maiden all forlorn",
        "man all tattered and torn",
        "priest all shaven and shorn",
        "rooster that crowed in the morn",
        "farmer sowing his corn",
        "horse and the hound and the horn"
    };

    // The action each item performs on the item before it, indexed the same way as ITEMS.
    // The house performs no action, so entry 0 is unused.
    private static final String[] ACTIONS = {
        "",
        "lay in",
        "ate",
        "killed",
        "worried",
        "tossed",
        "milked",
        "kissed",
        "married",
        "woke",
        "kept",
        "belonged to"
    };

    private static final int VERSE_COUNT = ITEMS.length;

    String verse(int verse) {
        checkVerse(verse);

        List<String> lines = new ArrayList<>();
        lines.add("This is the " + ITEMS[verse - 1]);
        for (int item = verse - 1; item > 0; item--) {
            lines.add("that " + ACTIONS[item] + " the " + ITEMS[item - 1]);
        }
        return String.join("\n", lines) + ".\n";
    }

    String verses(int startVerse, int endVerse) {
        if (startVerse > endVerse) {
            throw new IllegalArgumentException(
                    "startVerse (" + startVerse + ") must not be after endVerse (" + endVerse + ")");
        }
        return IntStream.rangeClosed(startVerse, endVerse)
                .mapToObj(this::verse)
                .collect(Collectors.joining("\n"));
    }

    String sing() {
        return verses(1, VERSE_COUNT);
    }

    private static void checkVerse(int verse) {
        if (verse < 1 || verse > VERSE_COUNT) {
            throw new IllegalArgumentException(
                    "verse must be between 1 and " + VERSE_COUNT + ", but was " + verse);
        }
    }

}
