package wordy

import (
	"strconv"
	"strings"
)

// Answer evaluates a simple math word problem such as "What is 5 plus 13?".
// Operations are evaluated strictly from left to right, ignoring the usual
// order of operations. It returns the result and true on success, or 0 and
// false if the question is not a valid math word problem.
func Answer(question string) (int, bool) {
	const prefix = "What is "

	q := strings.TrimSpace(question)
	if !strings.HasPrefix(q, prefix) || !strings.HasSuffix(q, "?") {
		return 0, false
	}

	body := q[len(prefix) : len(q)-1]
	words := strings.Fields(body)
	if len(words) == 0 {
		return 0, false
	}

	result, err := strconv.Atoi(words[0])
	if err != nil {
		return 0, false
	}

	i := 1
	for i < len(words) {
		var op string

		switch words[i] {
		case "plus", "minus":
			op = words[i]
			i++
		case "multiplied", "divided":
			if i+1 >= len(words) || words[i+1] != "by" {
				return 0, false
			}
			op = words[i]
			i += 2
		default:
			// Unsupported operation or invalid syntax.
			return 0, false
		}

		if i >= len(words) {
			// Operator without a following operand.
			return 0, false
		}

		n, err := strconv.Atoi(words[i])
		if err != nil {
			return 0, false
		}
		i++

		switch op {
		case "plus":
			result += n
		case "minus":
			result -= n
		case "multiplied":
			result *= n
		case "divided":
			if n == 0 {
				return 0, false
			}
			result /= n
		}
	}

	return result, true
}
