// Answer evaluates a simple math word problem from left to right,
// ignoring the usual order of operations. It returns the result and
// true on success, or 0 and false if the question is not a valid
// supported math word problem.
func Answer(question string) (int, bool) {
	const prefix = "What is"

	q := strings.TrimSpace(question)
	if !strings.HasPrefix(q, prefix) {
		return 0, false
	}
	q = strings.TrimPrefix(q, prefix)

	if !strings.HasSuffix(q, "?") {
		return 0, false
	}
	q = strings.TrimSuffix(q, "?")

	tokens := strings.Fields(q)
	if len(tokens) == 0 {
		return 0, false
	}

	result, err := strconv.Atoi(tokens[0])
	if err != nil {
		return 0, false
	}

	i := 1
	for i < len(tokens) {
		var op string

		switch tokens[i] {
		case "plus":
			op = "+"
			i++
		case "minus":
			op = "-"
			i++
		case "multiplied":
			if i+1 >= len(tokens) || tokens[i+1] != "by" {
				return 0, false
			}
			op = "*"
			i += 2
		case "divided":
			if i+1 >= len(tokens) || tokens[i+1] != "by" {
				return 0, false
			}
			op = "/"
			i += 2
		default:
			return 0, false
		}

		if i >= len(tokens) {
			return 0, false
		}
		operand, err := strconv.Atoi(tokens[i])
		if err != nil {
			return 0, false
		}
		i++

		switch op {
		case "+":
			result += operand
		case "-":
			result -= operand
		case "*":
			result *= operand
		case "/":
			if operand == 0 {
				return 0, false
			}
			result /= operand
		}
	}

	return result, true
