- **Framing:** The question must start with `What is` and end with `?`. Matching is case-insensitive and tolerant of extra whitespace.
- **Syntax:** Tokens must alternate number, operation, number, and so on. Two-word operators (`multiplied by`, `divided by`) are matched as a unit. Unknown operations, missing operands, consecutive operators or numbers, prefix/postfix forms, and non-math questions all return `(0, false)`.
- **Evaluation:** Operations apply strictly left to right, so `3 plus 2 multiplied by 3` gives 15.
- **Integer safety:** Overflow is detected rather than silently wrapping. Division by zero and non-whole quotients (e.g. `5 divided by 2`) are rejected because the answer must be an `int`. If you'd rather truncate those, only the check in `divide` needs to change.

Only `math`, `strconv`, and `strings` from the standard library are used, and the `Answer` signature is unchanged.

wordy.go
```
package wordy

import (
	"math"
	"strconv"
	"strings"
)

// operation applies a binary operator. It reports false if the result cannot
// be represented as an int, such as on overflow or division by zero.
type operation func(a, b int) (int, bool)

// operations maps each supported operator phrase to its implementation.
var operations = map[string]operation{
	"plus":          add,
	"minus":         subtract,
	"multiplied by": multiply,
	"divided by":    divide,
}

// Answer evaluates a simple math word problem such as "What is 5 plus 13?".
// Operations are applied strictly from left to right, ignoring the usual order
// of operations. It returns false if the question is malformed, uses an
// unsupported operation, or has an answer that cannot be represented as an int.
func Answer(question string) (int, bool) {
	q := strings.ToLower(strings.TrimSpace(question))
	if !strings.HasSuffix(q, "?") {
		return 0, false
	}

	words := strings.Fields(strings.TrimSuffix(q, "?"))
	if len(words) < 2 || words[0] != "what" || words[1] != "is" {
		return 0, false
	}
	tokens := words[2:]

	if len(tokens) == 0 {
		return 0, false
	}
	result, ok := parseNumber(tokens[0])
	if !ok {
		return 0, false
	}
	tokens = tokens[1:]

	// The problem must alternate between operations and numbers:
	// number, operation, number, operation, number, ...
	for len(tokens) > 0 {
		op, width, ok := operationAt(tokens)
		if !ok {
			return 0, false
		}
		tokens = tokens[width:]

		if len(tokens) == 0 {
			return 0, false // operation is missing its right-hand operand
		}
		operand, ok := parseNumber(tokens[0])
		if !ok {
			return 0, false
		}
		tokens = tokens[1:]

		result, ok = op(result, operand)
		if !ok {
			return 0, false
		}
	}

	return result, true
}

// parseNumber converts a token such as "42" or "-7" into an int.
func parseNumber(token string) (int, bool) {
	n, err := strconv.Atoi(token)
	return n, err == nil
}

// operationAt returns the operation at the start of tokens and the number of
// tokens it spans. Two-word operators such as "multiplied by" are checked first
// so that both words are consumed together.
func operationAt(tokens []string) (operation, int, bool) {
	if len(tokens) > 1 {
		if op, ok := operations[tokens[0]+" "+tokens[1]]; ok {
			return op, 2, true
		}
	}
	if op, ok := operations[tokens[0]]; ok {
		return op, 1, true
	}
	return nil, 0, false
}

func add(a, b int) (int, bool) {
	sum := a + b
	// Adding a positive number must not decrease the value, and adding a
	// negative one must not increase it. Otherwise the sum has wrapped around.
	if (b > 0 && sum < a) || (b < 0 && sum > a) {
		return 0, false
	}
	return sum, true
}

func subtract(a, b int) (int, bool) {
	diff := a - b
	// Subtracting a positive number must not increase the value, and
	// subtracting a negative one must not decrease it.
	if (b > 0 && diff > a) || (b < 0 && diff < a) {
		return 0, false
	}
	return diff, true
}

func multiply(a, b int) (int, bool) {
	if a == 0 || b == 0 {
		return 0, true
	}
	product := a * b
	// If no overflow occurred, dividing back recovers both operands exactly.
	if product/b != a || product/a != b {
		return 0, false
	}
	return product, true
}

func divide(a, b int) (int, bool) {
	// Reject division by zero, math.MinInt / -1 (which overflows), and results
	// that are not whole numbers, since the answer must be an integer.
	if b == 0 || (a == math.MinInt && b == -1) || a%b != 0 {
		return 0, false
	}
	return a / b, true
}
