```go
package wordy

import (
	"strconv"
	"strings"
)

const questionPrefix = "What is"

// Answer evaluates a simple math word problem, evaluating operations
// strictly from left to right (ignoring conventional operator precedence).
// It returns the result and true on success, or 0 and false if the question
// is not a valid math word problem.
func Answer(question string) (int, bool) {
	q := strings.TrimSpace(question)

	if !strings.HasPrefix(q, questionPrefix) || !strings.HasSuffix(q, "?") {
		return 0, false
	}

	rest := q[len(questionPrefix) : len(q)-1]
	if rest != "" && rest[0] != ' ' {
		// e.g. "What is5?" is not a valid question
		return 0, false
	}

	tokens := strings.Fields(rest)
	if len(tokens) == 0 {
		return 0, false
	}

	result, ok := parseNumber(tokens[0])
	if !ok {
		return 0, false
	}

	i := 1
	for i < len(tokens) {
		var op string

		switch {
		case tokens[i] == "plus":
			op = "plus"
			i++
		case tokens[i] == "minus":
			op = "minus"
			i++
		case tokens[i] == "multiplied" && i+1 < len(tokens) && tokens[i+1] == "by":
			op = "multiplied by"
			i += 2
		case tokens[i] == "divided" && i+1 < len(tokens) && tokens[i+1] == "by":
			op = "divided by"
			i += 2
		default:
			// Unsupported operation or unexpected token
			return 0, false
		}

		if i >= len(tokens) {
			// Operator without an operand
			return 0, false
		}

		operand, ok := parseNumber(tokens[i])
		if !ok {
			return 0, false
		}
		i++

		switch op {
		case "plus":
			result += operand
		case "minus":
			result -= operand
		case "multiplied by":
			result *= operand
		case "divided by":
			if operand == 0 {
				return 0, false
			}
			result /= operand
		default:
			return 0, false
		}
	}

	return result, true
}

// parseNumber converts a token to an integer, returning false if it is not a number.
func parseNumber(token string) (int, bool) {
	n, err := strconv.Atoi(token)
	if err != nil {
		return 0, false
	}
	return n, true
}
