#include <stdexcept>

namespace queen_attack {

namespace {

constexpr int board_size = 8;

bool is_on_board(int value) {
    return value >= 0 && value < board_size;
}

}  // namespace

queen::queen(int row, int column) : row_{row}, column_{column} {
    if (!is_on_board(row)) {
        throw std::domain_error("row not on board");
    }
    if (!is_on_board(column)) {
        throw std::domain_error("column not on board");
    }
}

int queen::row() const noexcept {
    return row_;
}

int queen::column() const noexcept {
    return column_;
}

bool can_attack(const queen& first, const queen& second) {
    const int row_diff = first.row() - second.row();
    const int column_diff = first.column() - second.column();

    if (row_diff == 0 && column_diff == 0) {
        throw std::domain_error("Queens cannot share the same space");
    }

    const bool same_row = row_diff == 0;
    const bool same_column = column_diff == 0;
    const bool same_diagonal = std::abs(row_diff) == std::abs(column_diff);

    return same_row || same_column || same_diagonal;
}

}  // namespace queen_attack
