The skeleton functions all throw, so each one needs an implementation:

- **`promisify`** wraps a callback-style function. It returns a function that calls the original with an extra node-style callback, rejecting on a truthy `error` and resolving otherwise. It preserves `this` and forwards all arguments.
- **`all`** stores each resolved value at its original index and resolves once every promise has resolved. It rejects on the first rejection. An empty input resolves to `[]`.
- **`allSettled`** works like `all`, but records `{ status, value }` or `{ status, reason }` for each entry and resolves once every promise has settled.
- **`race`** forwards the first settlement, whether fulfilled or rejected. An empty input never settles, matching the built-in.
- **`any`** resolves with the first fulfilled value. If every promise rejects, or the input is empty, it rejects with an `AggregateError` that holds the collected reasons, matching the built-in.

Non-promise values are handled by wrapping each item in `Promise.resolve`. The four combinators are implemented directly with `new Promise` and do not call `Promise.all`, `Promise.allSettled`, `Promise.race`, or `Promise.any`.

promises.js
```
export const promisify = (fn) =>
  function (...args) {
    return new Promise((resolve, reject) => {
      fn.call(this, ...args, (error, data) => {
        if (error) {
          reject(error);
        } else {
          resolve(data);
        }
      });
    });
  };

export const all = (promises) =>
  new Promise((resolve, reject) => {
    const items = Array.from(promises);
    const results = new Array(items.length);
    let pending = items.length;

    if (pending === 0) {
      resolve(results);
      return;
    }

    items.forEach((item, index) => {
      Promise.resolve(item).then((value) => {
        results[index] = value;
        pending -= 1;
        if (pending === 0) {
          resolve(results);
        }
      }, reject);
    });
  });

export const allSettled = (promises) =>
  new Promise((resolve) => {
    const items = Array.from(promises);
    const results = new Array(items.length);
    let pending = items.length;

    if (pending === 0) {
      resolve(results);
      return;
    }

    const settle = (index, result) => {
      results[index] = result;
      pending -= 1;
      if (pending === 0) {
        resolve(results);
      }
    };

    items.forEach((item, index) => {
      Promise.resolve(item).then(
        (value) => settle(index, { status: 'fulfilled', value }),
        (reason) => settle(index, { status: 'rejected', reason }),
      );
    });
  });

export const race = (promises) =>
  new Promise((resolve, reject) => {
    Array.from(promises).forEach((item) => {
      Promise.resolve(item).then(resolve, reject);
    });
  });

export const any = (promises) =>
  new Promise((resolve, reject) => {
    const items = Array.from(promises);
    const errors = new Array(items.length);
    let pending = items.length;

    if (pending === 0) {
      reject(new AggregateError(errors, 'All promises were rejected'));
      return;
    }

    items.forEach((item, index) => {
      Promise.resolve(item).then(resolve, (reason) => {
        errors[index] = reason;
        pending -= 1;
        if (pending === 0) {
          reject(new AggregateError(errors, 'All promises were rejected'));
        }
      });
    });
  });
