pub mod graph {
    use std::collections::HashMap;

    /// Copies borrowed `(key, value)` pairs into an owned attribute map.
    fn to_attr_map(attrs: &[(&str, &str)]) -> HashMap<String, String> {
        attrs
            .iter()
            .map(|&(key, value)| (key.to_string(), value.to_string()))
            .collect()
    }

    pub mod graph_items {
        pub mod node {
            use std::collections::HashMap;
            use super::super::to_attr_map;

            /// A named node of a graph, optionally carrying attributes.
            #[derive(Debug, Clone, PartialEq, Eq)]
            pub struct Node {
                pub name: String,
                pub attrs: HashMap<String, String>,
            }

            impl Node {
                /// Creates a node with the given name and no attributes.
                pub fn new(name: &str) -> Self {
                    Self {
                        name: name.to_string(),
                        attrs: HashMap::new(),
                    }
                }

                /// Adds the given attributes to the node.
                pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                    self.attrs.extend(to_attr_map(attrs));
                    self
                }

                /// Returns the value of the attribute `key`, if it is set.
                pub fn get_attr(&self, key: &str) -> Option<&str> {
                    self.attrs.get(key).map(String::as_str)
                }
            }
        }

        pub mod edge {
            use std::collections::HashMap;
            use super::super::to_attr_map;

            /// A connection from one named node to another, optionally carrying attributes.
            #[derive(Debug, Clone, PartialEq, Eq)]
            pub struct Edge {
                pub start: String,
                pub end: String,
                pub attrs: HashMap<String, String>,
            }

            impl Edge {
                /// Creates an edge from `start` to `end` with no attributes.
                pub fn new(start: &str, end: &str) -> Self {
                    Self {
                        start: start.to_string(),
                        end: end.to_string(),
                        attrs: HashMap::new(),
                    }
                }

                /// Adds the given attributes to the edge.
                pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                    self.attrs.extend(to_attr_map(attrs));
                    self
                }

                /// Returns the value of the attribute `key`, if it is set.
                pub fn get_attr(&self, key: &str) -> Option<&str> {
                    self.attrs.get(key).map(String::as_str)
                }
            }
        }
    }

    pub use self::graph_items::edge::Edge;
    pub use self::graph_items::node::Node;

    /// A graph made of nodes, edges and graph-wide attributes.
    #[derive(Debug, Default, Clone, PartialEq, Eq)]
    pub struct Graph {
        pub nodes: Vec<Node>,
        pub edges: Vec<Edge>,
        pub attrs: HashMap<String, String>,
    }

    impl Graph {
        /// Creates an empty graph.
        pub fn new() -> Self {
            Self::default()
        }

        /// Adds the given nodes to the graph.
        pub fn with_nodes(mut self, nodes: &[Node]) -> Self {
            self.nodes.extend_from_slice(nodes);
            self
        }

        /// Adds the given edges to the graph.
        pub fn with_edges(mut self, edges: &[Edge]) -> Self {
            self.edges.extend_from_slice(edges);
            self
        }

        /// Adds the given attributes to the graph.
        pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
            self.attrs.extend(to_attr_map(attrs));
            self
        }

        /// Returns the node with the given name, if the graph contains it.
        pub fn get_node(&self, name: &str) -> Option<&Node> {
            self.nodes.iter().find(|node| node.name == name)
        }

        /// Returns the edge from `start` to `end`, if the graph contains it.
        pub fn get_edge(&self, start: &str, end: &str) -> Option<&Edge> {
            self.edges
                .iter()
                .find(|edge| edge.start == start && edge.end == end)
        }

        /// Returns the value of the graph attribute `key`, if it is set.
        pub fn get_attr(&self, key: &str) -> Option<&str> {
            self.attrs.get(key).map(String::as_str)
        }
    }
}
