        let current = self.head;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.tail;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            current: self.head,
            remaining: self.len,
            marker: PhantomData,
        }
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is either None or points to a live node owned by
        // the list, and the `&mut self` borrow guarantees exclusive access.
        unsafe { self.current.map(|mut p| &mut p.as_mut().element) }
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is a live node or None; advancing follows the
        // `next` link, which is valid for nodes owned by the list.
        unsafe {
            self.current = self.current.and_then(|p| p.as_ref().next);
            self.peek_mut()
        }
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        // SAFETY: as in `next`, but following the `prev` link.
        unsafe {
            self.current = self.current.and_then(|p| p.as_ref().prev);
            self.peek_mut()
        }
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node_ptr = self.current?;
        // SAFETY: `node_ptr` is a live node owned by the list. We unlink it,
        // fix neighbor pointers and head/tail, then reclaim the Box exactly once.
        unsafe {
            let node = node_ptr.as_ptr();
            let prev = (*node).prev;
            let next = (*node).next;

            match prev {
                Some(mut p) => p.as_mut().next = next,
                None => self.list.head = next,
            }
            match next {
                Some(mut n) => n.as_mut().prev = prev,
                None => self.list.tail = prev,
            }

            self.list.len -= 1;
            // Move cursor to the neighbor closest to the back.
            self.current = if next.is_some() { next } else { prev };

            let boxed = Box::from_raw(node);
            Some(boxed.element)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let new_node = Box::into_raw(Box::new(Node {
            element,
            prev: None,
            next: None,
        }));
        // SAFETY: `new_node` was just allocated and is uniquely owned here.
        // Neighbor pointers we touch are live nodes owned by the list.
        unsafe {
            let new_ptr = NonNull::new_unchecked(new_node);
            match self.current {
                None => {
                    // Empty list: becomes the sole element.
                    self.list.head = Some(new_ptr);
                    self.list.tail = Some(new_ptr);
                    self.current = Some(new_ptr);
                }
                Some(mut cur) => {
                    let old_next = cur.as_ref().next;
                    (*new_node).prev = Some(cur);
                    (*new_node).next = old_next;
                    match old_next {
                        Some(mut n) => n.as_mut().prev = Some(new_ptr),
                        None => self.list.tail = Some(new_ptr),
                    }
                    cur.as_mut().next = Some(new_ptr);
                }
            }
            self.list.len += 1;
        }
    }

    pub fn insert_before(&mut self, element: T) {
        let new_node = Box::into_raw(Box::new(Node {
            element,
            prev: None,
            next: None,
        }));
        // SAFETY: as in `insert_after`.
        unsafe {
            let new_ptr = NonNull::new_unchecked(new_node);
            match self.current {
                None => {
                    self.list.head = Some(new_ptr);
                    self.list.tail = Some(new_ptr);
                    self.current = Some(new_ptr);
                }
                Some(mut cur) => {
                    let old_prev = cur.as_ref().prev;
                    (*new_node).next = Some(cur);
                    (*new_node).prev = old_prev;
                    match old_prev {
                        Some(mut p) => p.as_mut().next = Some(new_ptr),
                        None => self.list.head = Some(new_ptr),
                    }
                    cur.as_mut().prev = Some(new_ptr);
                }
            }
            self.list.len += 1;
        }
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node_ptr = self.current?;
        // SAFETY: `node_ptr` is a live node; the iterator borrows the list
        // immutably for 'a, so the node is not mutated or freed while iterating.
        unsafe {
            let node = &*node_ptr.as_ptr();
            self.current = node.next;
            self.remaining = self.remaining.saturating_sub(1);
            Some(&node.element)
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cur = self.head;
        while let Some(p) = cur {
            // SAFETY: each node was allocated via Box::into_raw and is freed
            // exactly once here, after reading its `next` link.
            unsafe {
                let boxed = Box::from_raw(p.as_ptr());
                cur = boxed.next;
            }
        }
        self.head = None;
        self.tail = None;
        self.len = 0;
    }
}
