// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

// A single node of the list. Nodes are heap allocated and owned by the list.
// Invariant: `prev` and `next` either are `None` or point to valid nodes that
// are currently linked in the same list, and they are mutually consistent
// (a.next == b  <=> b.prev == a).
struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

pub struct LinkedList<T> {
    // Invariants:
    // - `head` is `None` iff the list is empty, and then `tail` is `None` too.
    // - `head` and `tail` point to valid nodes of this list, with `head.prev == None`
    //   and `tail.next == None`.
    // - `len` is the number of nodes reachable from `head` via `next`.
    head: Option<NonNull<Node<T>>>,
    tail: Option<NonNull<Node<T>>>,
    len: usize,
    // Owns the nodes (for drop check and covariance) without making the list invariant.
    marker: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    // Invariant: `current` is either `None` (the ghost position between back and front)
    // or a valid node currently linked in `list`.
    list: &'a mut LinkedList<T>,
    current: Option<NonNull<Node<T>>>,
}

pub struct Iter<'a, T> {
    // Invariant: `current` is either `None` or a valid node of the list that is
    // borrowed for `'a`, so no mutation can happen while the iterator exists.
    current: Option<NonNull<Node<T>>>,
    marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.head;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.tail;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            current: self.head,
            marker: PhantomData,
        }
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        match self.current {
            // SAFETY: `current` is a valid node of `self.list` (cursor invariant),
            // and we hold `&mut self`, so no other reference to this node exists
            // for the returned lifetime.
            Some(node) => unsafe { Some(&mut (*node.as_ptr()).element) },
            None => None,
        }
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `node` is a valid node of the list (cursor invariant).
            Some(node) => unsafe { (*node.as_ptr()).next },
            // Ghost position: moving forward goes to the front.
            None => self.list.head,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `node` is a valid node of the list (cursor invariant).
            Some(node) => unsafe { (*node.as_ptr()).prev },
            // Ghost position: moving backward goes to the back.
            None => self.list.tail,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node_ptr = self.current?;
        // SAFETY: `node_ptr` is a valid node owned by the list (cursor invariant).
        // We reconstruct the Box that was created in `insert_between`, so it is
        // freed exactly once, and we unlink it before the list is used again.
        unsafe {
            let boxed = Box::from_raw(node_ptr.as_ptr());
            let Node { element, prev, next } = *boxed;

            // Relink the neighbors around the removed node.
            match prev {
                Some(p) => (*p.as_ptr()).next = next,
                None => self.list.head = next,
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = prev,
                None => self.list.tail = prev,
            }

            self.list.len -= 1;
            // Move to the neighbor closest to the back: next if it exists, else prev.
            self.current = next.or(prev);
            Some(element)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let (prev, next) = match self.current {
            // SAFETY: `node` is a valid node of the list (cursor invariant).
            Some(node) => (Some(node), unsafe { (*node.as_ptr()).next }),
            // Ghost position: the "after" position is the front of the list.
            None => (None, self.list.head),
        };
        // SAFETY: `prev` and `next` are either `None` or valid nodes of this list,
        // and they are adjacent (prev.next == next) as read above.
        unsafe {
            self.insert_between(element, prev, next);
        }
    }

    pub fn insert_before(&mut self, element: T) {
        let (prev, next) = match self.current {
            // SAFETY: `node` is a valid node of the list (cursor invariant).
            Some(node) => (unsafe { (*node.as_ptr()).prev }, Some(node)),
            // Ghost position: the "before" position is the back of the list.
            None => (self.list.tail, None),
        };
        // SAFETY: `prev` and `next` are either `None` or valid nodes of this list,
        // and they are adjacent (prev.next == next) as read above.
        unsafe {
            self.insert_between(element, prev, next);
        }
    }

    /// Insert a new node holding `element` between `prev` and `next`.
    ///
    /// # Safety
    /// - `prev` and `next` must each be `None` or a valid node of `self.list`.
    /// - If both are `Some`, `prev` must be directly before `next` in the list
    ///   (`prev.next == next` and `next.prev == prev`).
    /// - If `prev` is `None`, `next` must be the current head (or `None` if empty).
    /// - If `next` is `None`, `prev` must be the current tail (or `None` if empty).
    unsafe fn insert_between(
        &mut self,
        element: T,
        prev: Option<NonNull<Node<T>>>,
        next: Option<NonNull<Node<T>>>,
    ) {
        let node = NonNull::from(Box::leak(Box::new(Node {
            element,
            prev,
            next,
        })));

        // SAFETY: the caller guarantees `prev` and `next` are valid nodes of this list
        // (or `None`), so writing through them is sound and we have exclusive access
        // through `&mut self`.
        unsafe {
            match prev {
                Some(p) => (*p.as_ptr()).next = Some(node),
                None => self.list.head = Some(node),
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = Some(node),
                None => self.list.tail = Some(node),
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.current?;
        // SAFETY: `node` is a valid node of the list, which is immutably borrowed
        // for `'a` (iterator invariant), so shared references to it are sound.
        unsafe {
            let node_ref: &'a Node<T> = &*node.as_ptr();
            self.current = node_ref.next;
            Some(&node_ref.element)
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Repeatedly remove the front element via the cursor; each removal frees one node.
        while self.cursor_front().take().is_some() {}
    }
}

// SAFETY: The list owns its nodes exclusively, so it can be sent to another
// thread if its elements can be.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: Shared access to the list only allows shared access to the elements,
// so it can be shared across threads if the elements can be.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: The cursor has exclusive access to the list, mirroring `&mut LinkedList<T>`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
// SAFETY: A shared reference to the cursor only permits shared access to the list.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: The iterator behaves like a `&T` over the list's elements.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
// SAFETY: The iterator behaves like a `&T` over the list's elements.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}
