// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

/// A node in the doubly linked list.
///
/// Invariants:
/// - `prev`/`next` are either `None` (no neighbor) or point to a live node that
///   is owned by the same list.
/// - For adjacent nodes `a` and `b` (a.next == Some(b)), we have b.prev == Some(a).
struct Node<T> {
    elem: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

pub struct LinkedList<T> {
    head: Option<NonNull<Node<T>>>,
    tail: Option<NonNull<Node<T>>>,
    len: usize,
    // Logically owns boxed nodes; `Box<Node<T>>` keeps covariance and drop-check correct.
    marker: PhantomData<Box<Node<T>>>,
}

/// A cursor over the list. Its position is either on an element (`Some(node)`)
/// or on the "ghost" position between the back and the front (`None`).
///
/// Invariant: `current`, if `Some`, points to a live node of `list`.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Option<NonNull<Node<T>>>,
}

pub struct Iter<'a, T> {
    next: Option<NonNull<Node<T>>>,
    marker: PhantomData<&'a Node<T>>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.head;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.tail;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.head,
            marker: PhantomData,
        }
    }

    /// Allocate a new node with `elem` and link it between `prev` and `next`.
    /// The new node becomes the new head/tail if `prev`/`next` is `None`.
    ///
    /// # Safety
    /// - `prev` and `next`, if `Some`, must be live nodes owned by `self`.
    /// - If both are `Some`, they must be adjacent (`prev.next == next`).
    unsafe fn link_node(
        &mut self,
        prev: Option<NonNull<Node<T>>>,
        next: Option<NonNull<Node<T>>>,
        elem: T,
    ) -> NonNull<Node<T>> {
        let node = NonNull::from(Box::leak(Box::new(Node { elem, prev, next })));

        // SAFETY: caller guarantees `prev`/`next` are live nodes owned by `self`,
        // so dereferencing them to update their links is valid and unaliased
        // (we hold `&mut self`).
        match prev {
            Some(p) => (*p.as_ptr()).next = Some(node),
            None => self.head = Some(node),
        }
        match next {
            Some(n) => (*n.as_ptr()).prev = Some(node),
            None => self.tail = Some(node),
        }
        self.len += 1;
        node
    }

    /// Remove `node` from the list and take ownership of its box.
    ///
    /// # Safety
    /// `node` must be a live node owned by `self`. After this call it must not be used again.
    unsafe fn unlink_node(&mut self, node: NonNull<Node<T>>) -> Box<Node<T>> {
        // SAFETY: `node` is live (caller guarantee), so reading its links is valid.
        let prev = (*node.as_ptr()).prev;
        let next = (*node.as_ptr()).next;

        // SAFETY: neighbors of a live node are live nodes owned by `self`.
        match prev {
            Some(p) => (*p.as_ptr()).next = next,
            None => self.head = next,
        }
        match next {
            Some(n) => (*n.as_ptr()).prev = prev,
            None => self.tail = prev,
        }
        self.len -= 1;

        // SAFETY: the node was allocated via `Box::leak` and is now unlinked, so
        // reconstructing the box gives unique ownership exactly once.
        Box::from_raw(node.as_ptr())
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cur = self.head;
        while let Some(node) = cur {
            // SAFETY: every node was allocated via `Box::leak` and is freed exactly once
            // here, as we walk the list and never revisit a node.
            let boxed = unsafe { Box::from_raw(node.as_ptr()) };
            cur = boxed.next;
        }
        self.head = None;
        self.tail = None;
        self.len = 0;
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is a live node owned by the list (invariant), and we
        // hold `&mut` to the list, so no other reference to the element exists.
        self.current.map(|node| unsafe { &mut (*node.as_ptr()).elem })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `node` is live (invariant), so reading its `next` link is valid.
            Some(node) => unsafe { (*node.as_ptr()).next },
            // From the ghost position, moving forward goes to the front.
            None => self.list.head,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `node` is live (invariant), so reading its `prev` link is valid.
            Some(node) => unsafe { (*node.as_ptr()).prev },
            // From the ghost position, moving backward goes to the back.
            None => self.list.tail,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;

        // SAFETY: `node` is live (invariant). Reading its links is valid. We then
        // unlink it and reclaim the box exactly once; we update `current` to a
        // node that remains live (the next or previous neighbor).
        unsafe {
            let next = (*node.as_ptr()).next;
            let prev = (*node.as_ptr()).prev;
            self.current = next.or(prev);

            let boxed = self.list.unlink_node(node);
            Some(boxed.elem)
        }
    }

    pub fn insert_after(&mut self, _element: T) {
        match self.current {
            Some(cur) => {
                // SAFETY: `cur` is live and owned by the list; its `next` is the
                // adjacent node, so the two are adjacent as required.
                let next = unsafe { (*cur.as_ptr()).next };
                unsafe {
                    self.list.link_node(Some(cur), next, _element);
                }
            }
            None => {
                // Ghost position: inserting "after" it means at the front.
                let head = self.list.head;
                // SAFETY: `head` is either None or a live node owned by the list.
                unsafe {
                    self.list.link_node(None, head, _element);
                }
            }
        }
    }

    pub fn insert_before(&mut self, _element: T) {
        match self.current {
            Some(cur) => {
                // SAFETY: `cur` is live and owned by the list; its `prev` is the
                // adjacent node, so the two are adjacent as required.
                let prev = unsafe { (*cur.as_ptr()).prev };
                unsafe {
                    self.list.link_node(prev, Some(cur), _element);
                }
            }
            None => {
                // Ghost position: inserting "before" it means at the back.
                let tail = self.list.tail;
                // SAFETY: `tail` is either None or a live node owned by the list.
                unsafe {
                    self.list.link_node(tail, None, _element);
                }
            }
        }
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        match self.next {
            Some(node) => unsafe {
                // SAFETY: the iterator borrows the list immutably for `'a`, so all
                // nodes are live and not mutated while iterating.
                let node_ref: &'a Node<T> = &*node.as_ptr();
                self.next = node_ref.next;
                Some(&node_ref.elem)
            },
            None => None,
        }
    }
}

// SAFETY: the list owns its elements exclusively, so it can be sent to another
// thread if `T` can be sent.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: shared access to the list only yields shared references to `T`, so
// sharing is sound if `T` is `Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: the cursor holds an exclusive borrow of the list, mirroring `&mut LinkedList<T>`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
// SAFETY: a shared reference to the cursor only allows reading `T` through `&`-methods.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: the iterator behaves like `&'a LinkedList<T>`, so it is Send iff `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
// SAFETY: the iterator behaves like `&'a LinkedList<T>`, so it is Sync iff `T: Sync`.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}
