// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is either None or points to a live node owned by `list`.
        // We hold `&mut self`, so no other reference to the node exists.
        self.current.map(|ptr| unsafe { &mut (*ptr.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        // SAFETY: `current` points to a live node of `list` (or is None).
        self.current = match self.current {
            Some(ptr) => unsafe { (*ptr.as_ptr()).next },
            None => self.list.head,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        // SAFETY: `current` points to a live node of `list` (or is None).
        self.current = match self.current {
            Some(ptr) => unsafe { (*ptr.as_ptr()).prev },
            None => self.list.tail,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let ptr = self.current?;
        // SAFETY: `ptr` is a live node owned by the list. We unlink it, fix up
        // neighbor pointers and head/tail, then reclaim the box exactly once.
        unsafe {
            let node = ptr.as_ptr();
            let prev = (*node).prev;
            let next = (*node).next;

            match prev {
                Some(p) => (*p.as_ptr()).next = next,
                None => self.list.head = next,
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = prev,
                None => self.list.tail = prev,
            }

            self.list.len -= 1;
            // Move the cursor to the neighbor closest to the back.
            self.current = next.or(prev);

            let boxed = Box::from_raw(node);
            Some(boxed.element)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let new_ptr = Box::into_raw(Box::new(Node {
            element,
            prev: None,
            next: None,
        }));
        // SAFETY: new_ptr is a fresh non-null allocation we exclusively own.
        let new = unsafe { NonNull::new_unchecked(new_ptr) };

        match self.current {
            None => {
                // Ghost position: insert at the front.
                let old_head = self.list.head;
                unsafe {
                    (*new_ptr).next = old_head;
                }
                match old_head {
                    Some(h) => unsafe { (*h.as_ptr()).prev = Some(new) },
                    None => self.list.tail = Some(new),
                }
                self.list.head = Some(new);
            }
            Some(cur) => unsafe {
                // SAFETY: `cur` is a live node of the list.
                let cur_ptr = cur.as_ptr();
                let after = (*cur_ptr).next;
                (*new_ptr).prev = Some(cur);
                (*new_ptr).next = after;
                (*cur_ptr).next = Some(new);
                match after {
                    Some(a) => (*a.as_ptr()).prev = Some(new),
                    None => self.list.tail = Some(new),
                }
            },
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new_ptr = Box::into_raw(Box::new(Node {
            element,
            prev: None,
            next: None,
        }));
        // SAFETY: new_ptr is a fresh non-null allocation we exclusively own.
        let new = unsafe { NonNull::new_unchecked(new_ptr) };

        match self.current {
            None => {
                // Ghost position: insert at the back.
                let old_tail = self.list.tail;
                unsafe {
                    (*new_ptr).prev = old_tail;
                }
                match old_tail {
                    Some(t) => unsafe { (*t.as_ptr()).next = Some(new) },
                    None => self.list.head = Some(new),
                }
                self.list.tail = Some(new);
            }
            Some(cur) => unsafe {
                // SAFETY: `cur` is a live node of the list.
                let cur_ptr = cur.as_ptr();
                let before = (*cur_ptr).prev;
                (*new_ptr).next = Some(cur);
                (*new_ptr).prev = before;
                (*cur_ptr).prev = Some(new);
                match before {
                    Some(b) => (*b.as_ptr()).next = Some(new),
                    None => self.list.head = Some(new),
                }
            },
        }
        self.list.len += 1;
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cur = self.head;
        while let Some(ptr) = cur {
            // SAFETY: each node was allocated with Box::into_raw and is freed exactly once here.
            unsafe {
                let boxed = Box::from_raw(ptr.as_ptr());
                cur = boxed.next;
            }
        }
        self.head = None;
        self.tail = None;
        self.len = 0;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let ptr = self.next?;
        // SAFETY: `ptr` is a live node of the borrowed list; the iterator holds a shared
        // borrow so the node is not mutated or freed while iterating.
        unsafe {
            let node = &*ptr.as_ptr();
            self.next = node.next;
            self.remaining = self.remaining.saturating_sub(1);
            Some(&node.element)
        }
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}
