// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

/// A link to a node. `None` means "there is no node on this side".
type Link<T> = Option<NonNull<Node<T>>>;

/// A single list node. Nodes are heap allocated and owned by the list.
struct Node<T> {
    element: T,
    prev: Link<T>,
    next: Link<T>,
}

/// A doubly linked list.
///
/// Safety invariants, which every method must maintain and which all `unsafe` code relies on:
/// 1. `head` and `tail` are both `None` if and only if the list is empty, and then `len == 0`.
/// 2. `head`'s `prev` and `tail`'s `next` are `None`.
/// 3. For every node `a` with `a.next == Some(b)` we have `b.prev == Some(a)`, and vice versa.
/// 4. Walking `next` from `head` visits exactly `len` nodes, ending at `tail`.
/// 5. Every node was allocated with `Box::leak` and is owned by the list. It is freed exactly once,
///    in `unlink`, and is not reachable from the list after that.
pub struct LinkedList<T> {
    head: Link<T>,
    tail: Link<T>,
    len: usize,
    // Keeps `LinkedList` covariant in `T` (a raw pointer alone would make it invariant),
    // and tells the drop checker that the list owns `Node<T>`s.
    marker: PhantomData<Box<Node<T>>>,
}

/// A cursor that can move through the list and mutate it in place.
///
/// The cursor is either positioned on an element (`current == Some(node)`) or on the "ghost"
/// position (`current == None`), which sits logically between the back and the front of the list.
/// Moving forward from the back, or backward from the front, lands on the ghost. `insert_after`
/// on the ghost inserts at the front, and `insert_before` on the ghost inserts at the back.
/// This is what allows a cursor to work with an empty list.
///
/// Invariant: `current` is `None` or a node owned by `list`.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Link<T>,
}

/// An immutable front-to-back iterator.
///
/// Invariant: `next` is `None` or a node owned by the list borrowed for `'a`.
pub struct Iter<'a, T> {
    next: Link<T>,
    marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.head;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.tail;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.head,
            marker: PhantomData,
        }
    }
}

impl<T> LinkedList<T> {
    /// Allocates a node holding `element` and links it between `prev` and `next`.
    /// A `None` on one side makes the new node the head (no `prev`) or the tail (no `next`).
    ///
    /// # Safety
    /// - `prev` and `next`, if `Some`, must point to live nodes owned by `self`.
    /// - `prev` and `next` must be adjacent, i.e. `prev.next == next` and `next.prev == prev`,
    ///   where a `None` on one side means the list ends there. If both are `None`, the list
    ///   must be empty.
    unsafe fn insert_between(&mut self, prev: Link<T>, next: Link<T>, element: T) {
        let node = NonNull::from(Box::leak(Box::new(Node { element, prev, next })));

        // SAFETY: `prev` and `next` are live nodes owned by this list (caller contract), and we
        // hold `&mut self`, so we have exclusive access to their links. `node` was just allocated
        // and is only reachable through the links we set here, so writing them is sound.
        unsafe {
            match prev {
                Some(p) => (*p.as_ptr()).next = Some(node),
                None => self.head = Some(node),
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = Some(node),
                None => self.tail = Some(node),
            }
        }
        self.len += 1;
    }

    /// Unlinks `node` from the list, frees it, and returns its element.
    ///
    /// # Safety
    /// - `node` must point to a live node owned by `self`.
    /// - After this call `node` is freed. The caller must ensure that no cursor or other pointer
    ///   still refers to it.
    unsafe fn unlink(&mut self, node: NonNull<Node<T>>) -> T {
        // SAFETY: `node` was allocated by `Box::leak` in `insert_between` and is still owned by
        // the list (caller contract), so reclaiming it as a `Box` is valid. It is freed exactly
        // once, because it is removed from the list here and never reached again.
        let Node { element, prev, next } = unsafe { *Box::from_raw(node.as_ptr()) };

        // SAFETY: `prev` and `next` are the live neighbours of `node` (list invariant), so their
        // links may be updated. `node` itself is no longer accessed.
        unsafe {
            match prev {
                Some(p) => (*p.as_ptr()).next = next,
                None => self.head = next,
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = prev,
                None => self.tail = prev,
            }
        }
        self.len -= 1;
        element
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Remove the front element until the list is empty. Each `take` unlinks and frees
        // exactly one node, so every node is freed exactly once.
        while self.cursor_front().take().is_some() {}
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is `None` or a live node of `self.list` (cursor invariant).
        // We hold `&mut self`, so no other reference to the node exists, and the returned borrow
        // is tied to `&mut self`, so it cannot outlive the cursor.
        self.current
            .map(|node| unsafe { &mut (*node.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let next = match self.current {
            // SAFETY: `current` is `Some`, so it points to a live node of `self.list`.
            Some(node) => unsafe { (*node.as_ptr()).next },
            // The ghost position wraps around to the front of the list.
            None => self.list.head,
        };
        self.current = next;
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let prev = match self.current {
            // SAFETY: `current` is `Some`, so it points to a live node of `self.list`.
            Some(node) => unsafe { (*node.as_ptr()).prev },
            // The ghost position wraps around to the back of the list.
            None => self.list.tail,
        };
        self.current = prev;
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;

        // SAFETY: `node` is a live node of `self.list` (cursor invariant), so reading its links is valid.
        let (prev, next) = unsafe { ((*node.as_ptr()).prev, (*node.as_ptr()).next) };

        // Move to the neighbour closest to the back: `next` if there is one, otherwise `prev`.
        // The cursor only ends on the ghost if the list becomes empty.
        self.current = next.or(prev);

        // SAFETY: `node` is live and owned by the list. `self.current` no longer refers to it
        // (it was just updated above), and we hold `&mut self`, so nothing else can reach it.
        Some(unsafe { self.list.unlink(node) })
    }

    pub fn insert_after(&mut self, element: T) {
        let (prev, next) = match self.current {
            // Insert between the current node and its successor.
            Some(node) => {
                // SAFETY: `node` is a live node of `self.list` (cursor invariant).
                (Some(node), unsafe { (*node.as_ptr()).next })
            }
            // On the ghost position, "after" means the front of the list.
            None => (None, self.list.head),
        };
        // SAFETY: `prev` and `next` are live nodes of `self.list` or `None`, and they are adjacent.
        // In the first case `next` was read from `prev`'s link. In the second, `head` has no `prev`.
        unsafe { self.list.insert_between(prev, next, element) };
    }

    pub fn insert_before(&mut self, element: T) {
        let (prev, next) = match self.current {
            // Insert between the current node and its predecessor.
            Some(node) => {
                // SAFETY: `node` is a live node of `self.list` (cursor invariant).
                (unsafe { (*node.as_ptr()).prev }, Some(node))
            }
            // On the ghost position, "before" means the back of the list.
            None => (self.list.tail, None),
        };
        // SAFETY: `prev` and `next` are live nodes of `self.list` or `None`, and they are adjacent.
        // In the first case `prev` was read from `next`'s link. In the second, `tail` has no `next`.
        unsafe { self.list.insert_between(prev, next, element) };
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: `node` is a live node of the list (iterator invariant). The list is borrowed
        // immutably for `'a` while this iterator exists, so the node is neither freed nor mutated
        // during `'a`, and handing out a shared reference to it is sound.
        let node: &'a Node<T> = unsafe { &*node.as_ptr() };
        self.next = node.next;
        Some(&node.element)
    }
}

// SAFETY: The list owns its nodes exclusively, like a `Box<Node<T>>` would, so moving it to
// another thread is sound whenever its elements may be sent there.
unsafe impl<T: Send> Send for LinkedList<T> {}

// SAFETY: A shared `&LinkedList<T>` only allows reading nodes (`Iter` yields `&T`, and no
// method takes `&self` and mutates), so sharing is sound whenever `T` may be shared between threads.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: A `Cursor` is an exclusive borrow of the list, so it can be sent like `&mut LinkedList<T>`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}

// SAFETY: A shared reference to a cursor allows no access to the list, since every cursor method
// takes `&mut self`, so sharing is sound whenever `T` may be shared between threads.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: `Iter` behaves like `&'a LinkedList<T>` (yielding `&'a T`), so it may be sent when `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}

// SAFETY: `Iter` behaves like `&'a LinkedList<T>`, so it may be shared when `T: Sync`.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}
