// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` always points to a live node owned by `self.list`,
        // and we hold an exclusive borrow of the list, so no aliasing occurs.
        unsafe { self.current.map(|node| &mut (*node.as_ptr()).element) }
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        // SAFETY: `current` (if `Some`) points to a live node of `self.list`.
        // Reading its `next` link is valid.
        self.current = match self.current {
            Some(node) => unsafe { (*node.as_ptr()).next },
            // Ghost position: moving forward wraps to the front.
            None => self.list.front,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        // SAFETY: `current` (if `Some`) points to a live node of `self.list`.
        self.current = match self.current {
            Some(node) => unsafe { (*node.as_ptr()).prev },
            // Ghost position: moving backward wraps to the back.
            None => self.list.back,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;
        // SAFETY: `node` is a live node owned by `self.list`. After we unlink it
        // from the list and reclaim the box exactly once, we never touch it again.
        unsafe {
            let boxed = Box::from_raw(node.as_ptr());
            let prev = boxed.prev;
            let next = boxed.next;

            match prev {
                Some(p) => (*p.as_ptr()).next = next,
                None => self.list.front = next,
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = prev,
                None => self.list.back = prev,
            }

            self.list.len -= 1;
            // Move to the neighbor closest to the back: the next node if it exists,
            // otherwise the previous one.
            self.current = next.or(prev);

            Some(boxed.element)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let new_node = Box::into_raw(Box::new(Node {
            element,
            prev: None,
            next: None,
        }));
        // SAFETY: `new_node` was just allocated and is uniquely owned here.
        // All other pointers we dereference are live nodes of `self.list`.
        unsafe {
            let new = NonNull::new_unchecked(new_node);
            match self.current {
                Some(cur) => {
                    let next = (*cur.as_ptr()).next;
                    (*new_node).prev = Some(cur);
                    (*new_node).next = next;
                    (*cur.as_ptr()).next = Some(new);
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(new),
                        None => self.list.back = Some(new),
                    }
                }
                // Ghost position: insert at the front.
                None => {
                    let old_front = self.list.front;
                    (*new_node).next = old_front;
                    match old_front {
                        Some(f) => (*f.as_ptr()).prev = Some(new),
                        None => self.list.back = Some(new),
                    }
                    self.list.front = Some(new);
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new_node = Box::into_raw(Box::new(Node {
            element,
            prev: None,
            next: None,
        }));
        // SAFETY: `new_node` was just allocated and is uniquely owned here.
        // All other pointers we dereference are live nodes of `self.list`.
        unsafe {
            let new = NonNull::new_unchecked(new_node);
            match self.current {
                Some(cur) => {
                    let prev = (*cur.as_ptr()).prev;
                    (*new_node).next = Some(cur);
                    (*new_node).prev = prev;
                    (*cur.as_ptr()).prev = Some(new);
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(new),
                        None => self.list.front = Some(new),
                    }
                }
                // Ghost position: insert at the back.
                None => {
                    let old_back = self.list.back;
                    (*new_node).prev = old_back;
                    match old_back {
                        Some(b) => (*b.as_ptr()).next = Some(new),
                        None => self.list.front = Some(new),
                    }
                    self.list.back = Some(new);
                }
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: `node` is a live node of the list borrowed for `'a`; the list
        // cannot be mutated while the iterator (which borrows it) exists, so a
        // shared reference with lifetime `'a` is valid.
        unsafe {
            let node_ref = &*node.as_ptr();
            self.next = node_ref.next;
            self.remaining -= 1;
            Some(&node_ref.element)
        }
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Pop every element so each node is freed exactly once.
        while let Some(node) = self.front {
            // SAFETY: `front` is a live node owned by the list. We unlink and free it
            // exactly once, and update `front` before dropping the box.
            unsafe {
                let boxed = Box::from_raw(node.as_ptr());
                self.front = boxed.next;
                match self.front {
                    Some(f) => (*f.as_ptr()).prev = None,
                    None => self.back = None,
                }
                self.len -= 1;
                drop(boxed);
            }
        }
    }
}
