// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

/// A single node of the list. Nodes are heap allocated and linked by raw pointers.
struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

// Invariants of `LinkedList`:
// - `head` is `None` if and only if `tail` is `None` and `len == 0`.
// - Every node reachable from `head` through `next` is live, owned by the list,
//   and has its `prev` pointing to the node before it (`None` for the head).
// - `tail` is the last node reached by following `next`, `None` for the empty list.
// - `len` is the number of nodes in the chain.
pub struct LinkedList<T> {
    head: Option<NonNull<Node<T>>>,
    tail: Option<NonNull<Node<T>>>,
    len: usize,
    // Tells dropck and auto traits that the list owns its nodes, like a `Box<Node<T>>`.
    marker: PhantomData<Box<Node<T>>>,
}

// The cursor has a current position which is either a node of the list or the
// "ghost" position (`None`). The ghost sits logically between the back and the front
// of the list, so moving forward from the back reaches the ghost and moving forward
// from the ghost reaches the front (and symmetrically for `prev`).
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Option<NonNull<Node<T>>>,
}

pub struct Iter<'a, T> {
    next: Option<NonNull<Node<T>>>,
    marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.head;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.tail;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.head,
            marker: PhantomData,
        }
    }

    /// Allocates a new node holding `element` and links it between `prev` and `next`,
    /// updating `head`, `tail` and `len` accordingly.
    ///
    /// # Safety
    ///
    /// `prev` and `next` must be neighbors in this list: `next` must be the node
    /// following `prev` (or the head if `prev` is `None`), and `prev` must be the node
    /// preceding `next` (or the tail if `next` is `None`). Every `Some` pointer must
    /// refer to a live node of this list.
    unsafe fn link_between(
        &mut self,
        element: T,
        prev: Option<NonNull<Node<T>>>,
        next: Option<NonNull<Node<T>>>,
    ) {
        // Leaking the box hands out a unique, non-null pointer to a fresh node.
        // The node is now owned by the list and must be freed exactly once (via `take` or `Drop`).
        let new = NonNull::from(Box::leak(Box::new(Node { element, prev, next })));

        match prev {
            // SAFETY: the caller guarantees `p` is a live node of this list,
            // so writing to its `next` field is valid and exclusive (we hold `&mut self`).
            Some(p) => unsafe { (*p.as_ptr()).next = Some(new) },
            None => self.head = Some(new),
        }
        match next {
            // SAFETY: the caller guarantees `n` is a live node of this list,
            // so writing to its `prev` field is valid and exclusive (we hold `&mut self`).
            Some(n) => unsafe { (*n.as_ptr()).prev = Some(new) },
            None => self.tail = Some(new),
        }
        self.len += 1;
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Repeatedly removing the current element from the front frees every node.
        let mut cursor = self.cursor_front();
        while cursor.take().is_some() {}
    }
}

// SAFETY: `LinkedList<T>` uniquely owns its nodes, like a `Box<T>`, so it can be sent
// to another thread whenever `T` can be sent.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: shared access to the list only hands out `&T` (through `Iter`) or requires
// `&mut` access, so sharing it is sound whenever `T` is `Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: a `Some` current position always points to a live node of the list,
        // and we hold a mutable borrow of the cursor, so no other reference to the node exists.
        self.current
            .map(|node| unsafe { &mut (*node.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `node` is a live node of the list, so reading its `next` pointer is valid.
            Some(node) => unsafe { (*node.as_ptr()).next },
            None => self.list.head,
        };
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        self.current = match self.current {
            // SAFETY: `node` is a live node of the list, so reading its `prev` pointer is valid.
            Some(node) => unsafe { (*node.as_ptr()).prev },
            None => self.list.tail,
        };
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;

        // SAFETY: `node` is a live node of the list. We first unlink it from its neighbors,
        // so no pointer inside the list refers to it afterwards. Only then do we reclaim
        // ownership with `Box::from_raw`, which is the unique owner of the allocation.
        unsafe {
            let boxed = Box::from_raw(node.as_ptr());
            let Node { element, prev, next } = *boxed;

            match prev {
                // SAFETY: `p` is a live neighbor of the node we are removing.
                Some(p) => (*p.as_ptr()).next = next,
                None => self.list.head = next,
            }
            match next {
                // SAFETY: `n` is a live neighbor of the node we are removing.
                Some(n) => (*n.as_ptr()).prev = prev,
                None => self.list.tail = prev,
            }

            self.list.len -= 1;
            // Move to the neighbor closest to the back, falling back to the previous one.
            self.current = next.or(prev);
            Some(element)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        match self.current {
            Some(curr) => {
                // SAFETY: `curr` is a live node of the list, so reading its `next` pointer is valid.
                let next = unsafe { (*curr.as_ptr()).next };
                // SAFETY: `curr` and `next` are neighbors in the list.
                unsafe { self.list.link_between(element, Some(curr), next) }
            }
            None => {
                // The ghost position sits just before the front, so inserting after it
                // puts the new element at the front (for an empty list, this is the only element).
                let head = self.list.head;
                // SAFETY: `head` is either `None` (empty list) or the list's head, which is
                // exactly the neighbor the new node must be placed in front of.
                unsafe { self.list.link_between(element, None, head) }
            }
        }
    }

    pub fn insert_before(&mut self, element: T) {
        match self.current {
            Some(curr) => {
                // SAFETY: `curr` is a live node of the list, so reading its `prev` pointer is valid.
                let prev = unsafe { (*curr.as_ptr()).prev };
                // SAFETY: `prev` and `curr` are neighbors in the list.
                unsafe { self.list.link_between(element, prev, Some(curr)) }
            }
            None => {
                // The ghost position sits just after the back, so inserting before it
                // puts the new element at the back (for an empty list, this is the only element).
                let tail = self.list.tail;
                // SAFETY: `tail` is either `None` (empty list) or the list's tail, which is
                // exactly the neighbor the new node must be placed after.
                unsafe { self.list.link_between(element, tail, None) }
            }
        }
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: `node` is a live node of the list. The iterator holds a shared borrow of the
        // list, so the node cannot be mutated or freed while the iterator exists.
        unsafe {
            let node_ref = &*node.as_ptr();
            self.next = node_ref.next;
            Some(&node_ref.element)
        }
    }
}

