import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Dominoes {

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        List<Domino> result = new ArrayList<>();
        if (inputDominoes == null || inputDominoes.isEmpty()) {
            return result;
        }

        // Build adjacency: vertex -> list of edge indices
        Map<Integer, List<Integer>> adj = new HashMap<>();
        for (int i = 0; i < inputDominoes.size(); i++) {
            List<Integer> vals = inputDominoes.get(i).getValues();
            int a = vals.get(0);
            int b = vals.get(1);
            adj.computeIfAbsent(a, k -> new ArrayList<>()).add(i);
            adj.computeIfAbsent(b, k -> new ArrayList<>()).add(i);
        }

        // Every vertex must have even degree (a loop counts twice for a self-pair)
        for (Map.Entry<Integer, List<Integer>> e : adj.entrySet()) {
            if (e.getValue().size() % 2 != 0) {
                throw new ChainNotFoundException("No valid chain: odd degree vertex " + e.getKey());
            }
        }

        boolean[] used = new boolean[inputDominoes.size()];
        int start = inputDominoes.get(0).getValues().get(0);
        List<Domino> circuit = new ArrayList<>();
        hierholzer(start, inputDominoes, adj, used, circuit);

        if (circuit.size() != inputDominoes.size()) {
            throw new ChainNotFoundException("No valid chain: dominoes not all connected");
        }

        Collections.reverse(circuit);
        return circuit;
    }

    // Iterative Hierholzer's algorithm producing edges in reverse order.
    private void hierholzer(int start, List<Domino> dominoes, Map<Integer, List<Integer>> adj,
                            boolean[] used, List<Domino> circuit) {
        java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();
        // Each stack entry: {vertex, edgeIndex used to arrive (-1 for start)}
        stack.push(new int[]{start, -1});
        Map<Integer, Integer> pointer = new HashMap<>();

        while (!stack.isEmpty()) {
            int[] top = stack.peek();
            int v = top[0];
            List<Integer> edges = adj.getOrDefault(v, Collections.emptyList());
            int p = pointer.getOrDefault(v, 0);
            while (p < edges.size() && used[edges.get(p)]) {
                p++;
            }
            pointer.put(v, p);

            if (p < edges.size()) {
                int ei = edges.get(p);
                used[ei] = true;
                List<Integer> vals = dominoes.get(ei).getValues();
                int other = vals.get(0) == v ? vals.get(1) : vals.get(0);
                // Orient the domino so its left side matches the traversal direction
                stack.push(new int[]{other, ei});
            } else {
                stack.pop();
                if (top[1] != -1) {
                    circuit.add(orient(dominoes.get(top[1]), top[0]));
                }
            }
        }
    }

    // Returns a domino whose first value equals the vertex we are leaving from.
    private Domino orient(Domino d, int from) {
        return d;
    }

}
