import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Dominoes {

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        List<Domino> chain = new ArrayList<>();
        if (inputDominoes == null || inputDominoes.isEmpty()) {
            return chain;
        }

        int n = inputDominoes.size();

        // Build degree counts and adjacency lists (edge indices per number).
        Map<Integer, Integer> degree = new HashMap<>();
        Map<Integer, List<Integer>> adjacency = new HashMap<>();
        for (int i = 0; i < n; i++) {
            Domino d = inputDominoes.get(i);
            degree.merge(d.getHigh(), 1, Integer::sum);
            degree.merge(d.getLow(), 1, Integer::sum);
            adjacency.computeIfAbsent(d.getHigh(), k -> new ArrayList<>()).add(i);
            adjacency.computeIfAbsent(d.getLow(), k -> new ArrayList<>()).add(i);
        }

        // Every number must appear an even number of times, otherwise no closed chain exists.
        for (int count : degree.values()) {
            if (count % 2 != 0) {
                throw new ChainNotFoundException("No chain possible: a number appears an odd number of times");
            }
        }

        // Hierholzer's algorithm for an Eulerian circuit.
        boolean[] used = new boolean[n];
        Map<Integer, Integer> nextIndex = new HashMap<>();
        Deque<Integer> vertices = new ArrayDeque<>();
        Deque<Domino> edges = new ArrayDeque<>();
        List<Domino> popped = new ArrayList<>();

        int start = inputDominoes.get(0).getHigh();
        vertices.push(start);
        edges.push(null);

        while (!vertices.isEmpty()) {
            int v = vertices.peek();
            List<Integer> incident = adjacency.getOrDefault(v, Collections.emptyList());
            int p = nextIndex.getOrDefault(v, 0);
            while (p < incident.size() && used[incident.get(p)]) {
                p++;
            }

            if (p < incident.size()) {
                nextIndex.put(v, p + 1);
                int idx = incident.get(p);
                used[idx] = true;
                Domino d = inputDominoes.get(idx);
                int other = (d.getHigh() == v) ? d.getLow() : d.getHigh();
                vertices.push(other);
                edges.push(new Domino(v, other));
            } else {
                vertices.pop();
                Domino edge = edges.pop();
                if (edge != null) {
                    popped.add(edge);
                }
            }
        }

        // If not all stones were used, the stones are not connected into one chain.
        if (popped.size() != n) {
            throw new ChainNotFoundException("No chain possible: stones are not all connected");
        }

        Collections.reverse(popped);
        return popped;
    }

}
