    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        List<Domino> chain = new ArrayList<>();
        if (inputDominoes == null || inputDominoes.isEmpty()) {
            return chain;
        }

        int n = inputDominoes.size();

        // Count dot occurrences and build adjacency (value -> indices of dominoes touching it)
        Map<Integer, Integer> degree = new HashMap<>();
        Map<Integer, List<Integer>> adjacency = new HashMap<>();
        for (int i = 0; i < n; i++) {
            Domino domino = inputDominoes.get(i);
            int left = domino.getLeft();
            int right = domino.getRight();
            degree.merge(left, 1, Integer::sum);
            degree.merge(right, 1, Integer::sum);
            adjacency.computeIfAbsent(left, k -> new ArrayList<>()).add(i);
            adjacency.computeIfAbsent(right, k -> new ArrayList<>()).add(i);
        }

        // A closed chain requires every dot value to occur an even number of times
        for (int count : degree.values()) {
            if (count % 2 != 0) {
                throw new ChainNotFoundException("No closed chain possible: unmatched dot counts");
            }
        }

        // Hierholzer's algorithm for an Eulerian circuit
        boolean[] used = new boolean[n];
        List<Domino> reversedPath = new ArrayList<>();
        Deque<Step> stack = new ArrayDeque<>();
        stack.push(new Step(inputDominoes.get(0).getLeft(), null));

        while (!stack.isEmpty()) {
            Step top = stack.peek();
            int chosen = -1;
            for (int idx : adjacency.get(top.vertex)) {
                if (!used[idx]) {
                    chosen = idx;
                    break;
                }
            }

            if (chosen == -1) {
                stack.pop();
                if (top.edge != null) {
                    reversedPath.add(top.edge);
                }
            } else {
                used[chosen] = true;
                Domino domino = inputDominoes.get(chosen);
                Domino oriented;
                int other;
                if (domino.getLeft() == top.vertex) {
                    oriented = domino;
                    other = domino.getRight();
                } else {
                    oriented = new Domino(domino.getRight(), domino.getLeft());
                    other = domino.getLeft();
                }
                stack.push(new Step(other, oriented));
            }
        }

        if (reversedPath.size() != n) {
            throw new ChainNotFoundException("No chain possible: dominoes are not all connected");
        }

        Collections.reverse(reversedPath);
        chain.addAll(reversedPath);
        return chain;
    }

    private static final class Step {
        final int vertex;
        final Domino edge;

        Step(int vertex, Domino edge) {
            this.vertex = vertex;
            this.edge = edge;
        }
    }

