import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Dominoes {

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        if (inputDominoes.isEmpty()) {
            return new ArrayList<>();
        }

        // Think of each dot value as a vertex and each domino as an edge between its two halves.
        // A closed chain is an Eulerian circuit through that graph. It exists only if every dot
        // value appears on an even number of halves and all dominoes are connected to each other.
        Map<Integer, Integer> halvesByDot = new HashMap<>();
        Map<Integer, Deque<Integer>> dominoIndexesByDot = new HashMap<>();
        for (int index = 0; index < inputDominoes.size(); index++) {
            int leftDot = left(inputDominoes.get(index));
            int rightDot = right(inputDominoes.get(index));

            halvesByDot.merge(leftDot, 1, Integer::sum);
            halvesByDot.merge(rightDot, 1, Integer::sum);

            dominoIndexesByDot.computeIfAbsent(leftDot, dot -> new ArrayDeque<>()).add(index);
            if (rightDot != leftDot) {
                dominoIndexesByDot.computeIfAbsent(rightDot, dot -> new ArrayDeque<>()).add(index);
            }
        }

        for (int halves : halvesByDot.values()) {
            if (halves % 2 != 0) {
                throw new ChainNotFoundException(
                        "no chain possible: a dot value appears on an odd number of halves");
            }
        }

        // Hierholzer's algorithm: keep walking along unused dominoes until stuck, then step back.
        // When stuck, stepping back to a dot with unused dominoes splices in a sub-loop there, so
        // a chain is found whenever one exists. Dominoes are recorded as they are stepped back
        // over, which produces the chain in reverse order.
        boolean[] used = new boolean[inputDominoes.size()];
        List<Domino> chain = new ArrayList<>();
        Deque<Visit> path = new ArrayDeque<>();
        path.push(new Visit(left(inputDominoes.get(0)), null));

        while (!path.isEmpty()) {
            Visit current = path.peek();
            int index = takeUnusedDomino(current.dot, dominoIndexesByDot, used);
            if (index >= 0) {
                used[index] = true;
                Domino domino = inputDominoes.get(index);
                int nextDot = otherDot(domino, current.dot);
                path.push(new Visit(nextDot, orientStartingAt(domino, current.dot)));
            } else {
                path.pop();
                if (current.arrivedBy != null) {
                    chain.add(current.arrivedBy);
                }
            }
        }

        if (chain.size() != inputDominoes.size()) {
            throw new ChainNotFoundException(
                    "no chain possible: the dominoes are not all connected");
        }

        Collections.reverse(chain);
        return chain;
    }

    // Returns the index of an unused domino touching the given dot, or -1 if there is none.
    private static int takeUnusedDomino(
            int dot, Map<Integer, Deque<Integer>> dominoIndexesByDot, boolean[] used) {
        Deque<Integer> candidates = dominoIndexesByDot.get(dot);
        while (!candidates.isEmpty()) {
            int index = candidates.pop();
            if (!used[index]) {
                return index;
            }
        }
        return -1;
    }

    // Returns the domino, turned around if necessary, so that it starts at the given dot.
    private static Domino orientStartingAt(Domino domino, int dot) {
        return left(domino) == dot ? domino : new Domino(right(domino), left(domino));
    }

    // Returns the dot at the other end of the domino.
    private static int otherDot(Domino domino, int dot) {
        return left(domino) == dot ? right(domino) : left(domino);
    }

    // The halves of a domino are read through these two helpers only.
    private static int left(Domino domino) {
        return domino.getLeft();
    }

    private static int right(Domino domino) {
        return domino.getRight();
    }

    // A point on the walk: the dot reached, and the domino (oriented in the direction of travel)
    // that brought us there. The starting point has no such domino.
    private static final class Visit {
        private final int dot;
        private final Domino arrivedBy;

        Visit(int dot, Domino arrivedBy) {
            this.dot = dot;
            this.arrivedBy = arrivedBy;
        }
    }

}
