import java.util.ArrayList;
import java.util.List;

class Dominoes {

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        List<Domino> result = new ArrayList<>();
        if (inputDominoes == null || inputDominoes.isEmpty()) {
            return result;
        }

        // Every dot value must appear an even number of times for a closed chain.
        int[] degree = new int[7];
        for (Domino d : inputDominoes) {
            degree[d.getLeft()]++;
            degree[d.getRight()]++;
        }
        for (int count : degree) {
            if (count % 2 != 0) {
                throw new ChainNotFoundException("No valid chain exists: odd dot count");
            }
        }

        List<Domino> remaining = new ArrayList<>(inputDominoes);
        Domino first = remaining.remove(0);
        result.add(first);

        if (search(result, remaining, first.getRight(), first.getLeft())) {
            return result;
        }
        throw new ChainNotFoundException("No valid chain exists");
    }

    /**
     * Backtracking search. chain's tail value is 'end'; the chain must close
     * back to 'start' once all dominoes are used.
     */
    private boolean search(List<Domino> chain, List<Domino> remaining, int end, int start) {
        if (remaining.isEmpty()) {
            return end == start;
        }
        for (int i = 0; i < remaining.size(); i++) {
            Domino candidate = remaining.get(i);
            Domino oriented = null;
            if (candidate.getLeft() == end) {
                oriented = candidate;
            } else if (candidate.getRight() == end) {
                oriented = new Domino(candidate.getRight(), candidate.getLeft());
            }
            if (oriented == null) {
                continue;
            }

            remaining.remove(i);
            chain.add(oriented);
            if (search(chain, remaining, oriented.getRight(), start)) {
                return true;
            }
            chain.remove(chain.size() - 1);
            remaining.add(i, candidate);
        }
        return false;
    }

}
