    private boolean search(List<Domino> dominoes, boolean[] used, List<Domino> chain,
                           int startValue, int endValue, int placed) {
        if (placed == dominoes.size()) {
            return endValue == startValue;
        }

        for (int i = 0; i < dominoes.size(); i++) {
            if (used[i]) {
                continue;
            }
            Domino candidate = dominoes.get(i);

            if (candidate.getLeft() == endValue) {
                used[i] = true;
                chain.add(candidate);
                if (search(dominoes, used, chain, startValue, candidate.getRight(), placed + 1)) {
                    return true;
                }
                chain.remove(chain.size() - 1);
                used[i] = false;
            }

            if (candidate.getRight() == endValue && candidate.getLeft() != candidate.getRight()) {
                used[i] = true;
                chain.add(new Domino(candidate.getRight(), candidate.getLeft()));
                if (search(dominoes, used, chain, startValue, candidate.getLeft(), placed + 1)) {
                    return true;
                }
                chain.remove(chain.size() - 1);
                used[i] = false;
            }
        }
        return false;
    }

