import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Dominoes {

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        List<Domino> chain = new ArrayList<>();
        if (inputDominoes == null || inputDominoes.isEmpty()) {
            return chain;
        }

        int dominoCount = inputDominoes.size();

        // Map each pip value to the indices of the dominoes having that value on one of their halves.
        Map<Integer, List<Integer>> adjacency = new HashMap<>();
        for (int i = 0; i < dominoCount; i++) {
            Domino domino = inputDominoes.get(i);
            adjacency.computeIfAbsent(domino.getLeft(), key -> new ArrayList<>()).add(i);
            adjacency.computeIfAbsent(domino.getRight(), key -> new ArrayList<>()).add(i);
        }

        // A closed chain (first and last values equal) requires every pip value
        // to occur an even number of times.
        for (List<Integer> indices : adjacency.values()) {
            if (indices.size() % 2 != 0) {
                throw new ChainNotFoundException("No chain possible: a pip value occurs an odd number of times");
            }
        }

        // Hierholzer's algorithm for an Eulerian circuit.
        int startValue = inputDominoes.get(0).getLeft();
        boolean[] used = new boolean[dominoCount];
        Map<Integer, Integer> nextAdjacentPosition = new HashMap<>();
        Deque<Integer> valueStack = new ArrayDeque<>();
        Deque<Integer> dominoStack = new ArrayDeque<>();
        valueStack.push(startValue);
        dominoStack.push(-1);

        List<Integer> walkValues = new ArrayList<>();
        List<Integer> walkDominoes = new ArrayList<>();

        while (!valueStack.isEmpty()) {
            int value = valueStack.peek();
            List<Integer> indices = adjacency.get(value);
            int position = nextAdjacentPosition.getOrDefault(value, 0);
            while (position < indices.size() && used[indices.get(position)]) {
                position++;
            }

            if (position < indices.size()) {
                int dominoIndex = indices.get(position);
                nextAdjacentPosition.put(value, position + 1);
                used[dominoIndex] = true;
                Domino domino = inputDominoes.get(dominoIndex);
                int otherValue = domino.getLeft() == value ? domino.getRight() : domino.getLeft();
                valueStack.push(otherValue);
                dominoStack.push(dominoIndex);
            } else {
                nextAdjacentPosition.put(value, position);
                walkValues.add(valueStack.pop());
                walkDominoes.add(dominoStack.pop());
            }
        }

        // The walk contains every domino plus the initial start marker.
        if (walkDominoes.size() != dominoCount + 1) {
            throw new ChainNotFoundException("No chain possible: dominoes are not all connected");
        }

        // Each popped value is joined to the next popped value by the domino stored with it.
        for (int i = 0; i < dominoCount; i++) {
            int from = walkValues.get(i);
            Domino domino = inputDominoes.get(walkDominoes.get(i));
            chain.add(domino.getLeft() == from ? domino : reverse(domino));
        }

        return chain;
    }

    private static Domino reverse(Domino domino) {
        return new Domino(domino.getRight(), domino.getLeft());
    }

}
