/// Normalize a tonic like "c", "bb", "f#" into canonical "C", "Bb", "F#".
fn normalize_tonic(tonic: &str) -> Option<String> {
    let mut chars = tonic.chars();
    let first = chars.next()?;
    if !first.is_ascii_alphabetic() {
        return None;
    }
    let mut out = String::new();
    out.push(first.to_ascii_uppercase());
    for c in chars {
        match c {
            '#' => out.push('#'),
            'b' => out.push('b'),
            _ => return None,
        }
    }
    Some(out)
}

fn index_of(note: &str, table: &[&str; 12]) -> Option<usize> {
    table.iter().position(|n| *n == note)
}

fn chromatic_from(tonic: &str) -> Result<Vec<String>, Error> {
    let canon = normalize_tonic(tonic).ok_or(Error)?;
    let table: &[&str; 12] = if uses_flats(tonic) || uses_flats(&canon) {
        &FLAT_NOTES
    } else {
        &SHARP_NOTES
    };
    let start = index_of(&canon, table)
        .or_else(|| index_of(&canon, &SHARP_NOTES))
        .or_else(|| index_of(&canon, &FLAT_NOTES))
        .ok_or(Error)?;
    Ok((0..12).map(|i| table[(start + i) % 12].to_string()).collect())
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let chroma = chromatic_from(tonic)?;
        let mut notes = Vec::with_capacity(intervals.len() + 1);
        let mut pos = 0usize;
        notes.push(chroma[pos].clone());
        for c in intervals.chars() {
            let step = match c {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                _ => return Err(Error),
            };
            pos = (pos + step) % 12;
            notes.push(chroma[pos].clone());
        }
        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        let notes = chromatic_from(tonic)?;
        Ok(Scale { notes })
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
