use std::fmt;

/// Errors that can occur when constructing a scale.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Error {
    /// The tonic is not a note name such as `C`, `f#` or `Bb`.
    InvalidTonic(String),
    /// An interval is not one of `m` (minor second), `M` (major second)
    /// or `A` (augmented second).
    InvalidInterval(char),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::InvalidTonic(tonic) => write!(f, "invalid tonic: {tonic}"),
            Error::InvalidInterval(interval) => write!(f, "invalid interval: {interval}"),
        }
    }
}

impl std::error::Error for Error {}

/// Letter names, starting from C.
const LETTERS: [char; 7] = ['C', 'D', 'E', 'F', 'G', 'A', 'B'];

/// Pitch class (semitones above C) of each letter in `LETTERS`.
const NATURAL_PITCHES: [i32; 7] = [0, 2, 4, 5, 7, 9, 11];

/// Note names indexed by pitch class, written with sharps.
const SHARP_NAMES: [&str; 12] = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];

/// Note names indexed by pitch class, written with flats.
const FLAT_NAMES: [&str; 12] = ["C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B"];

/// The starting note of a scale.
#[derive(Debug)]
struct Tonic {
    /// Normalised spelling, e.g. `Bb` or `F#`.
    name: String,
    /// Index into `LETTERS`: 0 for C up to 6 for B.
    letter: usize,
    /// -1 for a flat, 0 for a natural and 1 for a sharp.
    accidental: i32,
    /// Whether the key is conventionally written with flats.
    uses_flats: bool,
}

impl Tonic {
    fn parse(tonic: &str) -> Result<Tonic, Error> {
        let chars: Vec<char> = tonic.chars().collect();
        let (note, accidental) = match chars.as_slice() {
            [note] => (*note, 0),
            [note, '#'] => (*note, 1),
            [note, 'b'] | [note, 'B'] => (*note, -1),
            _ => return Err(invalid_tonic(tonic)),
        };

        let letter = LETTERS
            .iter()
            .position(|&l| l == note.to_ascii_uppercase())
            .ok_or_else(|| invalid_tonic(tonic))?;

        let uses_flats = match accidental {
            -1 => true,
            1 => false,
            // Natural keys written with flats: F major and the minor keys d, g, c and f.
            _ => matches!(note, 'F' | 'd' | 'g' | 'c' | 'f'),
        };

        let accidental_symbol = match accidental {
            -1 => "b",
            1 => "#",
            _ => "",
        };

        Ok(Tonic {
            name: format!("{}{}", LETTERS[letter], accidental_symbol),
            letter,
            accidental,
            uses_flats,
        })
    }

    /// The pitch class of the tonic, where C = 0 and B = 11.
    fn pitch(&self) -> i32 {
        (NATURAL_PITCHES[self.letter] + self.accidental).rem_euclid(12)
    }
}

fn invalid_tonic(tonic: &str) -> Error {
    Error::InvalidTonic(tonic.to_string())
}

fn parse_intervals(intervals: &str) -> Result<Vec<i32>, Error> {
    intervals
        .chars()
        .map(|c| match c {
            'm' => Ok(1),
            'M' => Ok(2),
            'A' => Ok(3),
            other => Err(Error::InvalidInterval(other)),
        })
        .collect()
}

/// Spells a seven-note scale with one letter name per note, e.g. `C Db E F# G# A# B C`.
/// Returns `None` if that would require double sharps or flats.
fn spell_by_letter(tonic: &Tonic, steps: &[i32]) -> Option<Vec<String>> {
    let mut notes = vec![tonic.name.clone()];
    let mut letter = tonic.letter;
    let mut pitch = tonic.pitch();

    for &step in steps {
        pitch = (pitch + step).rem_euclid(12);
        letter = (letter + 1) % LETTERS.len();
        let accidental = match (pitch - NATURAL_PITCHES[letter]).rem_euclid(12) {
            0 => "",
            1 => "#",
            11 => "b",
            _ => return None,
        };
        notes.push(format!("{}{}", LETTERS[letter], accidental));
    }

    Some(notes)
}

/// Spells each note from its pitch class alone, using sharps or flats as the key requires.
fn spell_by_pitch(tonic: &Tonic, steps: &[i32]) -> Vec<String> {
    let names = if tonic.uses_flats { FLAT_NAMES } else { SHARP_NAMES };
    let mut notes = vec![tonic.name.clone()];
    let mut pitch = tonic.pitch();

    for &step in steps {
        pitch = (pitch + step).rem_euclid(12);
        notes.push(names[pitch as usize].to_string());
    }

    // A scale that returns to its tonic ends with the tonic's own spelling, e.g. `Db`.
    if pitch == tonic.pitch() {
        if let Some(last) = notes.last_mut() {
            *last = tonic.name.clone();
        }
    }

    notes
}

/// A scale, as the list of its spelled note names.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Scale {
    notes: Vec<String>,
}

impl Scale {
    /// Builds the scale that starts on `tonic` and follows `intervals`, where each character
    /// is `m` (half step), `M` (whole step) or `A` (augmented second).
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let tonic = Tonic::parse(tonic)?;
        let steps = parse_intervals(intervals)?;

        // Seven-note scales are spelled one letter per note where possible.
        let by_letter = if steps.len() == 7 {
            spell_by_letter(&tonic, &steps)
        } else {
            None
        };
        let notes = by_letter.unwrap_or_else(|| spell_by_pitch(&tonic, &steps));

        Ok(Scale { notes })
    }

    /// Builds the twelve-note chromatic scale that starts on `tonic`.
    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        let tonic = Tonic::parse(tonic)?;
        // Eleven half steps cover all twelve pitches without repeating the octave.
        let steps: [i32; 11] = [1; 11];

        Ok(Scale {
            notes: spell_by_pitch(&tonic, &steps),
        })
    }

    /// The notes of the scale, in order.
    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
