/// Converts an interval symbol into a number of semitones.
fn step_for_interval(c: char) -> Result<i32, Error> {
    match c {
        'm' => Ok(1), // minor second (half step)
        'M' => Ok(2), // major second (whole step)
        'A' => Ok(3), // augmented second (whole step + half step)
        _ => Err(Error),
    }
}

/// Parses a tonic such as "C", "Bb", "f#", or "eb".
/// Returns the pitch class (0 = C, 11 = B) and whether flats should be used.
fn parse_tonic(tonic: &str) -> Result<(usize, bool), Error> {
    let mut chars = tonic.chars();
    let letter = chars.next().ok_or(Error)?;
    let upper = letter.to_ascii_uppercase();
    let minor = letter.is_ascii_lowercase();

    let base: i32 = match upper {
        'C' => 0,
        'D' => 2,
        'E' => 4,
        'F' => 5,
        'G' => 7,
        'A' => 9,
        'B' => 11,
        _ => return Err(Error),
    };

    let accidental: i32 = match chars.as_str() {
        "" => 0,
        "#" => 1,
        "b" => -1,
        _ => return Err(Error),
    };

    // Flat keys: F, Bb, Eb, Ab, Db, Gb major; d, g, c, f, bb, eb minor.
    // Any explicit flat uses flats, any explicit sharp uses sharps.
    let flats = match accidental {
        -1 => true,
        1 => false,
        _ => upper == 'F' || (minor && matches!(upper, 'C' | 'D' | 'G')),
    };

    let pitch = (base + accidental).rem_euclid(12) as usize;
    Ok((pitch, flats))
}

