    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let (start, flats) = parse_tonic(tonic)?;
        let names = if flats { &FLAT_NAMES } else { &SHARP_NAMES };

        let mut pitch = start as i32;
        let mut notes = vec![names[start].to_string()];

        for c in intervals.chars() {
            pitch = (pitch + step_for_interval(c)?).rem_euclid(12);
            notes.push(names[pitch as usize].to_string());
        }

        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, &"m".repeat(11))
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
