/// Decides whether a tonic's scale should be spelled with flats.
///
/// Flat keys are F major and D, G, C, F minor (natural tonics), plus any
/// tonic written with a flat such as Bb, Eb, Ab, Db, Gb, bb or eb.
/// Every other tonic (C, G, D, A, E, B, a, e, b and all sharp keys) uses sharps.
fn uses_flats(tonic: &str) -> bool {
    let natural_flat_key = matches!(tonic, "F" | "d" | "g" | "c" | "f");
    let flat_tonic = tonic.len() == 2 && tonic.ends_with('b');
    natural_flat_key || flat_tonic
}

/// Converts an interval string such as "MMmMMMm" into semitone steps.
///
/// - `m` (minor second) = 1 semitone
/// - `M` (major second) = 2 semitones
/// - `A` (augmented second) = 3 semitones
fn parse_intervals(intervals: &str) -> Result<Vec<usize>, Error> {
    intervals
        .chars()
        .map(|c| match c {
            'm' => Ok(1),
            'M' => Ok(2),
            'A' => Ok(3),
            _ => Err(Error),
        })
        .collect::<Result<Vec<usize>, Error>>()
}
