    let mut chars = tonic.chars();
    match chars.next() {
        Some(first) => first.to_uppercase().collect::<String>() + chars.as_str(),
        None => String::new(),
    }
}

fn step_for(interval: char) -> Option<usize> {
    match interval {
        'm' => Some(1),
        'M' => Some(2),
        'A' => Some(3),
        _ => None,
    }
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let use_flats = FLAT_MAJOR_KEYS.contains(&tonic) || FLAT_MINOR_KEYS.contains(&tonic);
        let table: &[&str; 12] = if use_flats { &FLAT_NOTES } else { &SHARP_NOTES };

        let normalized = normalize_tonic(tonic);
        let mut index = SHARP_NOTES
            .iter()
            .position(|n| *n == normalized)
            .or_else(|| FLAT_NOTES.iter().position(|n| *n == normalized))
            .ok_or(Error)?;

        let mut notes = Vec::with_capacity(intervals.len() + 1);
        notes.push(table[index].to_string());

        for c in intervals.chars() {
            let step = step_for(c).ok_or(Error)?;
            index = (index + step) % 12;
            notes.push(table[index].to_string());
        }

        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, &"m".repeat(11))
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
