// You should change this.
//
// Depending on your implementation, there are a variety of potential errors
// which might occur. They aren't checked by the test suite in order to
// allow the greatest freedom of implementation, but real libraries should
// provide useful, descriptive errors so that downstream code can react
// appropriately.
//
// One common idiom is to define an Error enum which wraps all potential
// errors. Another common idiom is to use a helper type such as failure::Error
// which does more or less the same thing but automatically.
#[derive(Debug)]
pub struct Error;

const SHARPS: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];

const FLATS: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Scale {
    notes: Vec<String>,
}

/// Returns true if the tonic belongs to the "use flats" key signatures.
fn prefers_flats(tonic: &str) -> bool {
    let is_minor = tonic.chars().next().map_or(false, |c| c.is_ascii_lowercase());
    if is_minor {
        matches!(tonic, "d" | "g" | "c" | "f" | "bb" | "eb")
    } else {
        matches!(tonic, "F" | "Bb" | "Eb" | "Ab" | "Db" | "Gb")
    }
}

/// Normalizes the tonic so its first letter is uppercase, e.g. "bb" -> "Bb".
fn normalize(tonic: &str) -> String {
    let mut chars = tonic.chars();
    match chars.next() {
        Some(first) => first.to_ascii_uppercase().to_string() + chars.as_str(),
        None => String::new(),
    }
}

/// Converts an interval character into a number of semitones.
fn interval_steps(c: char) -> Result<usize, Error> {
    match c {
        'm' => Ok(1),
        'M' => Ok(2),
        'A' => Ok(3),
        _ => Err(Error),
    }
}

/// Builds the list of note names starting at the tonic and advancing by the
/// given semitone steps. The result contains `steps.len() + 1` notes.
fn build(tonic: &str, steps: &[usize]) -> Result<Vec<String>, Error> {
    let normalized = normalize(tonic);

    let candidates: [&[&str; 12]; 2] = if prefers_flats(tonic) {
        [&FLATS, &SHARPS]
    } else {
        [&SHARPS, &FLATS]
    };

    let (names, mut index) = candidates
        .iter()
        .find_map(|list| {
            list.iter()
                .position(|n| *n == normalized)
                .map(|idx| (*list, idx))
        })
        .ok_or(Error)?;

    let mut notes = Vec::with_capacity(steps.len() + 1);
    notes.push(names[index].to_string());
    for step in steps {
        index = (index + step) % 12;
        notes.push(names[index].to_string());
    }
    Ok(notes)
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let steps = intervals
            .chars()
            .map(interval_steps)
            .collect::<Result<Vec<usize>, Error>>()?;
        let notes = build(tonic, &steps)?;
        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        let steps = vec![1usize; 11];
        let notes = build(tonic, &steps)?;
        Ok(Scale { notes })
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
