const isPalindrome = (number) => {
  let remaining = number;
  let reversed = 0;

  while (remaining > 0) {
    reversed = reversed * 10 + (remaining % 10);
    remaining = Math.floor(remaining / 10);
  }

  return reversed === number;
};

const sortFactors = (factors) =>
  factors.sort(([a1, b1], [a2, b2]) => a1 - a2 || b1 - b2);

// Finds the smallest palindrome product of a <= b, with both factors within
// [minFactor, maxFactor], plus every factor pair that produces it.
const findSmallest = (minFactor, maxFactor) => {
  let value = null;
  let factors = [];

  for (let a = minFactor; a <= maxFactor; a += 1) {
    // Any product with `a` as the lower factor is at least a * a. Once that
    // exceeds the best palindrome, no later (larger) `a` can produce a match.
    if (value !== null && a * a > value) {
      break;
    }

    for (let b = a; b <= maxFactor; b += 1) {
      const product = a * b;

      // Products only grow as `b` increases, so stop once one exceeds the best.
      if (value !== null && product > value) {
        break;
      }

      if (isPalindrome(product)) {
        if (value === null || product < value) {
          value = product;
          factors = [[a, b]];
        } else if (product === value) {
          factors.push([a, b]);
        }
      }
    }
  }

  return { value, factors: sortFactors(factors) };
};

// Finds the largest palindrome product of a <= b, with both factors within
// [minFactor, maxFactor], plus every factor pair that produces it.
const findLargest = (minFactor, maxFactor) => {
  let value = null;
  let factors = [];

  for (let a = maxFactor; a >= minFactor; a -= 1) {
    // Any product with `a` as the lower factor is at most a * maxFactor. Once
    // that falls below the best palindrome, no earlier (smaller) `a` can match.
    if (value !== null && a * maxFactor < value) {
      break;
    }

    for (let b = maxFactor; b >= a; b -= 1) {
      const product = a * b;

      // Products only shrink as `b` decreases, so stop once one falls below the best.
      if (value !== null && product < value) {
        break;
      }

      if (isPalindrome(product)) {
        if (value === null || product > value) {
          value = product;
          factors = [[a, b]];
        } else if (product === value) {
          factors.push([a, b]);
        }
      }
    }
  }

  return { value, factors: sortFactors(factors) };
};

