   * `[a, b]` pair (a <= b) whose product equals the palindrome. If no
   * palindrome exists, `value` is `null` and `factors` is empty.
   */
  static generate({ minFactor, maxFactor }) {
    if (minFactor > maxFactor) {
      throw new Error('min must be <= max');
    }

