    }

    @Override
    public String toString() {
        return "{" + a + ", " + b + ", " + c + "}";
    }

    static class TripletListBuilder {

        private Integer sum;
        private Integer maxFactor;

        TripletListBuilder thatSumTo(int sum) {
            this.sum = sum;
            return this;
        }

        TripletListBuilder withFactorsLessThanOrEqualTo(int maxFactor) {
            this.maxFactor = maxFactor;
            return this;
        }

        List<PythagoreanTriplet> build() {
            List<PythagoreanTriplet> triplets = new ArrayList<>();

            // Without any constraint there is no bounded search space.
            if (sum == null && maxFactor == null) {
                return triplets;
            }

            int limit = Integer.MAX_VALUE;
            if (maxFactor != null) {
                limit = Math.min(limit, maxFactor);
            }
            if (sum != null) {
                limit = Math.min(limit, sum);
            }

            for (int a = 1; a <= limit; a++) {
                for (int b = a + 1; b <= limit; b++) {
                    if (sum != null) {
                        long c = (long) sum - a - b;
                        if (c <= b) {
                            // c only decreases as b grows, so no further candidates exist for this a
                            break;
                        }
                        if (c > limit) {
                            continue;
                        }
                        if ((long) a * a + (long) b * b == c * c) {
                            triplets.add(new PythagoreanTriplet(a, b, (int) c));
                        }
                    } else {
                        long cSquared = (long) a * a + (long) b * b;
                        long c = (long) Math.sqrt((double) cSquared);
                        // correct any floating point rounding in the square root
                        while (c * c < cSquared) {
                            c++;
                        }
                        while (c * c > cSquared) {
                            c--;
                        }
                        if (c * c != cSquared || c > limit) {
                            continue;
                        }
                        triplets.add(new PythagoreanTriplet(a, b, (int) c));
                    }
                }
            }

            return triplets;
        }

    }

