```
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

class PythagoreanTriplet {

    private final int a;
    private final int b;
    private final int c;

    PythagoreanTriplet(int a, int b, int c) {
        if (a < 1 || a >= b || b >= c || (long) a * a + (long) b * b != (long) c * c) {
            throw new IllegalArgumentException(
                    String.format("{%d, %d, %d} is not a Pythagorean triplet", a, b, c));
        }
        this.a = a;
        this.b = b;
        this.c = c;
    }

    static TripletListBuilder makeTripletsList() {
        return new TripletListBuilder();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }
        PythagoreanTriplet other = (PythagoreanTriplet) o;
        return a == other.a && b == other.b && c == other.c;
    }

    @Override
    public int hashCode() {
        return Objects.hash(a, b, c);
    }

    @Override
    public String toString() {
        return String.format("{%d, %d, %d}", a, b, c);
    }

    static class TripletListBuilder {

        private Integer sum;
        private int maxFactor = Integer.MAX_VALUE;

        TripletListBuilder thatSumTo(int sum) {
            this.sum = sum;
            return this;
        }

        TripletListBuilder withFactorsLessThanOrEqualTo(int maxFactor) {
            this.maxFactor = maxFactor;
            return this;
        }

        List<PythagoreanTriplet> build() {
            if (sum == null) {
                throw new IllegalStateException("thatSumTo() must be called before build()");
            }

            long n = sum;
            List<PythagoreanTriplet> triplets = new ArrayList<>();

            // Since a < b < c and a + b + c = n, every valid a satisfies 3a < n.
            for (long a = 1; 3 * a < n; a++) {
                // Substituting c = n - a - b into a*a + b*b = c*c and solving for b gives
                // b = n(n - 2a) / (2(n - a)), so each a yields at most one candidate b.
                long numerator = n * (n - 2 * a);
                long denominator = 2 * (n - a);
                if (numerator % denominator != 0) {
                    continue;
                }
                long b = numerator / denominator;
                long c = n - a - b;
                // c is the largest side, so checking it enforces the factor limit on all three.
                if (a < b && b < c && c <= maxFactor) {
                    triplets.add(new PythagoreanTriplet((int) a, (int) b, (int) c));
                }
            }
            return triplets;
        }
    }
}
