src/main/java/PythagoreanTriplet.java
```
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

class PythagoreanTriplet {

    private final int a;
    private final int b;
    private final int c;

    PythagoreanTriplet(int a, int b, int c) {
        this.a = a;
        this.b = b;
        this.c = c;
    }

    static TripletListBuilder makeTripletsList() {
        return new TripletListBuilder();
    }

    int getA() {
        return a;
    }

    int getB() {
        return b;
    }

    int getC() {
        return c;
    }

    int sum() {
        return a + b + c;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof PythagoreanTriplet)) {
            return false;
        }
        PythagoreanTriplet other = (PythagoreanTriplet) o;
        return a == other.a && b == other.b && c == other.c;
    }

    @Override
    public int hashCode() {
        return Objects.hash(a, b, c);
    }

    @Override
    public String toString() {
        return "{" + a + ", " + b + ", " + c + "}";
    }

    static class TripletListBuilder {

        private Integer sum;
        private Integer maxFactor;

        TripletListBuilder thatSumTo(int sum) {
            this.sum = sum;
            return this;
        }

        TripletListBuilder withFactorsLessThanOrEqualTo(int maxFactor) {
            this.maxFactor = maxFactor;
            return this;
        }

        List<PythagoreanTriplet> build() {
            List<PythagoreanTriplet> result = new ArrayList<>();
            int limit;
            if (maxFactor != null) {
                limit = maxFactor;
            } else if (sum != null) {
                limit = sum;
            } else {
                return result;
            }

            for (int c = 1; c <= limit; c++) {
                for (int b = 1; b < c; b++) {
                    int a2 = c * c - b * b;
                    int a = (int) Math.round(Math.sqrt(a2));
                    if (a <= 0 || a >= b) {
                        continue;
                    }
                    if (a * a + b * b != c * c) {
                        continue;
                    }
                    if (sum != null && a + b + c != sum) {
                        continue;
                    }
                    result.add(new PythagoreanTriplet(a, b, c));
                }
            }
            result.sort((x, y) -> {
                if (x.a != y.a) {
                    return Integer.compare(x.a, y.a);
                }
                return Integer.compare(x.b, y.b);
            });
            return result;
        }

    }

}
