namespace Bankaccount {

Bankaccount::Bankaccount() : is_open_(false), balance_(0) {}

void Bankaccount::open() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (is_open_) {
        throw std::runtime_error("account already open");
    }
    is_open_ = true;
    balance_ = 0;
}

void Bankaccount::close() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (!is_open_) {
        throw std::runtime_error("account not open");
    }
    is_open_ = false;
    balance_ = 0;
}

std::optional<long> Bankaccount::get_balance() const {
    std::lock_guard<std::mutex> lock(mutex_);
    if (!is_open_) {
        return std::nullopt;
    }
    return balance_;
}

void Bankaccount::deposit(long amount) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (!is_open_) {
        throw std::runtime_error("account not open");
    }
    if (amount <= 0) {
        throw std::runtime_error("amount must be greater than 0");
    }
    balance_ += amount;
}

void Bankaccount::withdraw(long amount) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (!is_open_) {
        throw std::runtime_error("account not open");
    }
    if (amount <= 0) {
        throw std::runtime_error("amount must be greater than 0");
    }
    if (amount > balance_) {
        throw std::runtime_error("amount must be less than balance");
    }
    balance_ -= amount;
}

}  // namespace Bankaccount
