import re

_QUESTION_PATTERN = re.compile(r"what\s+is\b(.*)", re.IGNORECASE | re.DOTALL)
_INTEGER_PATTERN = re.compile(r"[+-]?[0-9]+")
_BY_OPERATIONS = {"multiplied", "divided"}


def _add(left, right):
    return left + right


def _subtract(left, right):
    return left - right


def _multiply(left, right):
    return left * right


def _divide(left, right):
    if right == 0:
        raise ValueError("division by zero")
    # Truncate toward zero, as is conventional for integer word-problem division.
    quotient = abs(left) // abs(right)
    if (left < 0) != (right < 0):
        quotient = -quotient
    return quotient


_OPERATIONS = {
    "plus": _add,
    "minus": _subtract,
    "multiplied": _multiply,
    "divided": _divide,
}

_KEYWORDS = set(_OPERATIONS) | {"by"}


def _tokenize(question):
    match = _QUESTION_PATTERN.fullmatch(question.strip())
    if match is None:
        raise ValueError("unknown operation")

    body = match.group(1).strip()
    if body.endswith("?"):
        body = body[:-1]
    return body.split()


def _parse_operand(token):
    if _INTEGER_PATTERN.fullmatch(token):
        return int(token)
    if token.lower() in _KEYWORDS:
        raise ValueError("syntax error")
    raise ValueError("unknown operation")


def answer(question):
    tokens = _tokenize(question)
    if not tokens:
        raise ValueError("syntax error")

    result = _parse_operand(tokens[0])
    position = 1

    while position < len(tokens):
        operation = tokens[position].lower()
        if operation not in _OPERATIONS:
            if _INTEGER_PATTERN.fullmatch(tokens[position]):
                raise ValueError("syntax error")
            raise ValueError("unknown operation")
        position += 1

        if operation in _BY_OPERATIONS:
            if position >= len(tokens) or tokens[position].lower() != "by":
                raise ValueError("syntax error")
            position += 1

        if position >= len(tokens):
            raise ValueError("syntax error")
        operand = _parse_operand(tokens[position])
        position += 1

        result = _OPERATIONS[operation](result, operand)

    return result
```

