import operator

OPERATIONS = {
    "plus": operator.add,
    "minus": operator.sub,
    "multiplied": operator.mul,
    "divided": operator.floordiv,
}

KNOWN_WORDS = set(OPERATIONS) | {"by"}


def _is_number(token):
    try:
        int(token)
        return True
    except ValueError:
        return False


def answer(question):
    prefix = "What is"
    if not question.startswith(prefix):
        raise ValueError("unknown operation")

    body = question[len(prefix):].strip()
    if body.endswith("?"):
        body = body[:-1]
    tokens = body.split()

    if not tokens:
        raise ValueError("syntax error")

    # Validate vocabulary first so unsupported words are reported as unknown operations.
    for token in tokens:
        if not _is_number(token) and token not in KNOWN_WORDS:
            raise ValueError("unknown operation")

    # The problem must start with a number.
    if not _is_number(tokens[0]):
        raise ValueError("syntax error")

    value = int(tokens[0])
    i = 1
    while i < len(tokens):
        word = tokens[i]
        if word in ("plus", "minus"):
            op = OPERATIONS[word]
            i += 1
        elif word in ("multiplied", "divided"):
            if i + 1 >= len(tokens) or tokens[i + 1] != "by":
                raise ValueError("syntax error")
            op = OPERATIONS[word]
            i += 2
        else:
            raise ValueError("syntax error")

        if i >= len(tokens) or not _is_number(tokens[i]):
            raise ValueError("syntax error")

        operand = int(tokens[i])
        i += 1

        if op is operator.floordiv and operand == 0:
            raise ValueError("division by zero")

        value = op(value, operand)

    return value
