import operator


OPERATIONS = {
    "plus": operator.add,
    "minus": operator.sub,
    "multiplied by": operator.mul,
    "divided by": None,  # handled specially for integer division
}


def _tokenize(body):
    words = body.split()
    tokens = []
    i = 0
    while i < len(words):
        if i + 1 < len(words) and f"{words[i]} {words[i + 1]}" in OPERATIONS:
            tokens.append(f"{words[i]} {words[i + 1]}")
            i += 2
        else:
            tokens.append(words[i])
            i += 1
    return tokens


def _to_int(token):
    try:
        return int(token)
    except ValueError:
        return None


def answer(question):
    if not question.startswith("What is"):
        raise ValueError("unknown operation")

    body = question[len("What is"):].strip()
    if body.endswith("?"):
        body = body[:-1].strip()

    if not body:
        raise ValueError("syntax error")

    tokens = _tokenize(body)

    first = _to_int(tokens[0])
    if first is None:
        if tokens[0] in OPERATIONS or tokens[0].isalpha():
            # Something like "What is cubed" or a non-math word
            raise ValueError("unknown operation" if len(tokens) > 1 or tokens[0].isalpha() else "syntax error")
        raise ValueError("syntax error")

    result = first
    i = 1
    while i < len(tokens):
        op_token = tokens[i]
        if i + 1 >= len(tokens):
            raise ValueError("syntax error")

        operand = _to_int(tokens[i + 1])
        if operand is None:
            raise ValueError("syntax error")

        if op_token == "plus":
            result = result + operand
        elif op_token == "minus":
            result = result - operand
        elif op_token == "multiplied by":
            result = result * operand
        elif op_token == "divided by":
            if operand == 0:
                raise ValueError("division by zero")
            result = int(result / operand)
        else:
            if _to_int(op_token) is not None:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")

        i += 2

    return result
