import operator

OPERATIONS = {
    "plus": operator.add,
    "minus": operator.sub,
    "multiplied by": operator.mul,
    "divided by": None,  # handled specially below
}


def _parse_int(token):
    try:
        return int(token)
    except (TypeError, ValueError):
        return None


def answer(question):
    if not isinstance(question, str):
        raise ValueError("unknown operation")

    text = question.strip()
    if not text.startswith("What is") or not text.endswith("?"):
        raise ValueError("unknown operation")

    body = text[len("What is"):-1].strip()
    if not body:
        raise ValueError("syntax error")

    tokens = body.split()

    # Combine two-word operators into single tokens.
    combined = []
    i = 0
    while i < len(tokens):
        if i + 1 < len(tokens):
            pair = f"{tokens[i]} {tokens[i + 1]}"
            if pair in ("multiplied by", "divided by"):
                combined.append(pair)
                i += 2
                continue
        combined.append(tokens[i])
        i += 1
    tokens = combined

    # First token must be a number.
    result = _parse_int(tokens[0])
    if result is None:
        if any(t.lstrip("-").isdigit() for t in tokens):
            raise ValueError("syntax error")
        raise ValueError("unknown operation")

    if len(tokens) == 1:
        return result

    index = 1
    while index < len(tokens):
        op_token = tokens[index]
        if op_token not in OPERATIONS:
            # Determine whether this is an unknown operation or a syntax error.
            if _parse_int(op_token) is None and op_token.isalpha():
                raise ValueError("unknown operation")
            raise ValueError("syntax error")

        if index + 1 >= len(tokens):
            raise ValueError("syntax error")

        operand = _parse_int(tokens[index + 1])
        if operand is None:
            raise ValueError("syntax error")

        if op_token == "divided by":
            if operand == 0:
                raise ValueError("division by zero")
            result = int(result / operand)
        else:
            result = OPERATIONS[op_token](result, operand)

        index += 2

    return result
